// REQ-NAV1 · la barra son tres botones y un menú. Un solo enrutador por `data-tab` para los dos, que
// es lo que permite que mover una entrada de la barra al menú (o al revés) sea mover una línea de
// HTML y nada más.
const MAS=$('#mas-menu'), BTN_MAS=$('#btn-mas');
function cerrarMas(){ MAS.hidden=true; BTN_MAS.setAttribute('aria-expanded','false'); }
function alternarMas(){ MAS.hidden ? (MAS.hidden=false, BTN_MAS.setAttribute('aria-expanded','true')) : cerrarMas(); }
// La línea de RPG (Mapa y Jugar) está APARCADA por decisión del dueño: el código se queda entero,
// solo se esconde la puerta. Quién está aparcado lo DECLARA el HTML con `data-rpg` y aquí se deriva
// —escrito dos veces se despega en cuanto se mueva una entrada—, y el interruptor es `game.rpg`.
// El guarda va en `irA` y no solo en el menú porque a una vista también se llega por `game`, por un
// snippet o por un atajo: esconder el botón no es cerrar la puerta.
// NO se persiste en `localStorage` a propósito: «aparcado» quiere decir apagado en cada carga, y así
// una prueba en la consola no puede dejar la UI en un estado que luego nadie recuerda haber pedido.
let _rpgOn = false;
const TABS_RPG = new Set([...document.querySelectorAll('[data-rpg][data-tab]')].map(e => e.dataset.tab));
function aplicaRpg(){ document.querySelectorAll('[data-rpg]').forEach(el => { el.hidden = !_rpgOn; }); }
aplicaRpg();
function irA(tab){
  if(TABS_RPG.has(tab) && !_rpgOn) return;           // aparcado: ver `game.rpg.enabled`
  if(tab==='galeria'){ openHabitantes(); return; }   // sin bucket = TODO (decisión del dueño)
  if(tab==='mapa'){ openMapa(); return; }            // overlay mapa del mundo
  if(tab==='jugar'){ quickPlay(); return; }          // jugar ya (sala + personaje al azar)
  if(tab==='mundo'){ openWorld(); return; }          // sandbox 3D en primera persona (WebGL)
  if(tab==='codigo'){ openSnips(); return; }         // gestor de snippets de código
  if(tab==='agentes'){ openAgentes(); return; }      // panel de agentes articulados
}
$('#tabs').addEventListener('click',e=>{
  const t=e.target.closest('.tab'); if(!t) return;
  if(t.dataset.tab==='mas'){ alternarMas(); return; }
  cerrarMas(); irA(t.dataset.tab);
});
// Las entradas del menú que NO son data-tab (Nuevo, Guardar, Exportar, Importar…) conservan sus ids y
// sus manejadores de siempre; aquí solo se cierra el menú y, si la entrada es una vista, se abre.
MAS.addEventListener('click',e=>{
  const it=e.target.closest('.menu-item'); if(!it) return;
  cerrarMas();
  if(it.dataset.tab) irA(it.dataset.tab);
});
// Cerrar: Esc, un clic fuera, o un segundo clic en «⋯» (que lo lleva alternarMas).
document.addEventListener('pointerdown',e=>{
  if(MAS.hidden) return;
  if(e.target.closest('#mas-menu') || e.target.closest('#btn-mas')) return;
  cerrarMas();
},true);
$('#btn-habitantes').onclick=()=>openHabitantes('habitante');
$('#btn-habitaciones').onclick=()=>openHabitantes('habitacion');
$('#btn-texturas').onclick=()=>openHabitantes('textura');
$('#hab-close').onclick=closeHabitantes;
$('#hab-refresh').onclick=()=>openHabitantes(habKind);   // recarga sin cambiar lo que se está viendo
$('#ficha-close').onclick=closeFicha;
$('#ficha-save').onclick=guardarFicha;
// Copiar la clave / el ejemplo. La confirmación va por toast: el dueño mira desde el móvil y un
// botón que no dice nada parece que no ha hecho nada.
document.querySelectorAll('#ficha-modal [data-copy]').forEach(b=>{
  b.onclick=()=>{
    const inp=$('#'+b.dataset.copy);
    inp.select();
    const ok = navigator.clipboard
      ? (navigator.clipboard.writeText(inp.value), true)
      : document.execCommand('copy');
    toast(ok ? 'Copiado' : 'No se pudo copiar — está seleccionado');
  };
});
$('#hab-modal').addEventListener('click',e=>{ if(e.target.id==='hab-modal') closeHabitantes(); });

// atajos
window.addEventListener('keydown',e=>{
  // El menú «⋯» es lo más superficial que hay abierto: se cierra ANTES que cualquier modal (REQ-NAV1).
  if(e.key==='Escape' && !MAS.hidden){ cerrarMas(); return; }
  if(e.key==='Escape' && !$('#mc-modal').hidden){                               // Mundo (REQ-MC): Esc de 2 pasos
    if(!$('#snip-modal').hidden){ closeSnips(); return; }                         // 1º si el modal de código está abierto → cerrarlo
    if(!$('#ag-modal').hidden){ closeAgentes(); return; }                         // 1º ídem el panel de agentes (Alt+A)
    if(!$('#mc-note').hidden){ mcCloseNote(); return; }                          // 1º si el editor de nota está abierto → cerrarlo
    if(!$('#mc-picker').hidden){ mcClosePicker(); return; }                     // 1º si el selector está abierto → cerrarlo
    if(mc.osdAbierta){ mcOsdCerrar(); return; }                                 // 1º una pantalla OSD (REQ-OSD2): cierra el menú, no el Mundo
    if(mc.active && (document.pointerLockElement===mc.canvas || performance.now()-mc.unlockedAt<350)){ document.exitPointerLock(); return; } // 1º Esc: suelta el ratón, NO cierra
    closeWorld(); return;                                                       // 2º Esc (ratón ya libre): cierra el Mundo
  }
  // Alt+C = abre/cierra la vista de código, también desde el Mundo (el botón 🧩 obliga a soltar antes el ratón).
  // Va ANTES del corte de Mundo y del de input/textarea a propósito: así cierra igual con el foco en el código.
  // Se mira e.code (tecla FÍSICA) porque con Alt pulsado e.key llega compuesto en varios teclados, y se excluye
  // Ctrl/⌘ para no pisar AltGr ni el Ctrl+C de copiar selección del Mundo.
  if(e.code==='KeyC' && e.altKey && !e.ctrlKey && !e.metaKey){
    e.preventDefault();
    if(!$('#snip-modal').hidden){ closeSnips(); return; }
    if(document.pointerLockElement===mc.canvas) document.exitPointerLock();      // en el Mundo el ratón está capturado
    openSnips(); return;
  }
  // Alt+A = lo mismo para el panel de agentes: hasta ahora solo se llegaba por la pestaña del editor,
  // así que retocar un bicho obligaba a salir del Mundo. Mismas cautelas que Alt+C (e.code, sin Ctrl/⌘
  // para no pisar el Ctrl+A de seleccionar todo) y va antes del corte de Mundo por la misma razón.
  if(e.code==='KeyA' && e.altKey && !e.ctrlKey && !e.metaKey){
    // ⚠️ stopImmediatePropagation, que Alt+C no necesita: al CERRAR el panel el handler del Mundo
    // (más abajo, mismo window) ya lo ve oculto, y su `a` es andar hacia la izquierda — cerrarías el
    // panel dando un paso de lado. La `c` de Alt+C no significa nada allí, por eso se libraba.
    e.preventDefault(); e.stopImmediatePropagation();
    if(!$('#ag-modal').hidden){ closeAgentes(); return; }
    if(document.pointerLockElement===mc.canvas) document.exitPointerLock();
    openAgentes(); return;
  }
  if(!$('#mc-modal').hidden) return;                                            // en Mundo, los atajos del editor no aplican
  if(e.key==='Escape' && !$('#play-modal').hidden){ closePlay(); return; }
  if(e.key==='Escape' && !$('#room-modal').hidden){ closeRoom(); return; }
  if(!$('#room-modal').hidden && (e.key==='Delete'||e.key==='Backspace') && roomSelHab>=0){
    e.preventDefault(); const habs=mapa.cells[roomCell].habs; habs.splice(roomSelHab,1); roomSelHab=-1; updateRoomDel(); renderRoomCanvas(); saveMapa(); return;
  }
  if(e.key==='Escape' && !$('#mapa-picker').hidden){ closePicker(); return; }
  if(e.key==='Escape' && !$('#snip-modal').hidden){ closeSnips(); return; }
  if(e.key==='Escape' && !$('#ag-modal').hidden){ closeAgentes(); return; }
  if(e.key==='Escape' && !$('#mapa-modal').hidden){ closeMapa(); return; }
  if(e.key==='Escape' && !$('#ficha-modal').hidden){ closeFicha(); return; }   // antes que la galería: va encima
  if(e.key==='Escape' && !$('#hab-modal').hidden){ closeHabitantes(); return; }
  if(e.key==='Escape' && modalOpen){ closeModal(); return; }
  if(e.key==='Escape' && cancelPaste()) return;      // Esc cancela la colocación de un pegado
  if(e.target.matches('input,select,textarea')) return;
  if(modalOpen){
    if(e.key.toLowerCase()==='r'){ modalView.yaw+=Math.PI/4; drawIsoBig(); }
    else if(e.key.toLowerCase()==='f') closeModal();
    else if(e.key==='+'||e.key==='=') modalZoomAt(bigCv.width/2, bigCv.height/2, 1.12);
    else if(e.key==='-'||e.key==='_') modalZoomAt(bigCv.width/2, bigCv.height/2, 1/1.12);
    else if(e.key==='0') resetModalView();
    return;
  }
  if((e.ctrlKey||e.metaKey) && e.key.toLowerCase()==='z'){ e.preventDefault(); e.shiftKey?redo():undo(); return; }
  if((e.ctrlKey||e.metaKey) && e.key.toLowerCase()==='y'){ e.preventDefault(); redo(); return; }
  if((e.ctrlKey||e.metaKey) && e.key.toLowerCase()==='a'){ e.preventDefault(); selectAll(); return; }           // seleccionar todos los voxels (2D Capas y 3D)
  if((e.ctrlKey||e.metaKey) && e.key.toLowerCase()==='c'){ if(copySelection()) e.preventDefault(); return; }   // copiar selección (2D Capas y 3D comparten `selection`)
  if((e.ctrlKey||e.metaKey) && e.key.toLowerCase()==='v'){ if(startPaste()) e.preventDefault(); return; }       // pegar (modo colocación · Capas y 3D)
  if(e.key==='Delete'||e.key==='Backspace'){ if(deleteSelection()) return; }
  // flechas con selección: extruir (herramienta Extruir) o recolocar (resto)
  if(selection.size){
    if(state.tool==='extrude'){
      if(e.key==='ArrowUp'||e.key==='ArrowDown'){                  // ↑ hacia fuera (eleva) · ↓ hacia dentro (aplana)
        e.preventDefault(); const dir = e.key==='ArrowUp' ? 1 : -1;
        edit(()=>{                                                 // un paso planar, mismo motor que el arrastre
          exBase=[]; for(const k of selection){ const [x,y,z]=k.split(',').map(Number); exBase.push({x,y,z,c:getVoxel(x,y,z)}); }
          exCells=new Set(); exCarved=new Map(); exDir=selectionNormal();
          applyExtrudeDrag(dir);
        });
        render(); return;
      }
    } else {
      const d={ArrowLeft:[-1,0],ArrowRight:[1,0],ArrowUp:[0,-1],ArrowDown:[0,1]}[e.key];
      if(d){ e.preventDefault(); edit(()=>moveSel(d[0],d[1],0)); render(); return; }
    }
  }
  // en 3D (sin selección que recolocar) ←/→ giran la vista como los botones #e3-rot-left/right
  if(mode==='3d' && (e.key==='ArrowLeft'||e.key==='ArrowRight')){
    e.preventDefault();
    view3d.yaw += (e.key==='ArrowLeft' ? Math.PI/4 : -Math.PI/4);
    hover3d=null; buildGhost=null; drawEdit3d(); return;
  }
  const map={b:'paint',e:'erase',i:'pick',g:'fill',s:'select',h:'hand',o:'orbit',x:'extrude',c:'build',p:'pivot',a:'caras'};
  if(map[e.key]){ setTool(map[e.key]); }
  else if(e.key===']') setLayer(state.layer+1);
  else if(e.key==='[') setLayer(state.layer-1);
  else if(e.key.toLowerCase()==='r'){ state.rot=(state.rot+1)&3; drawIso(); }
  else if(e.key.toLowerCase()==='f') openModal();
  else if(e.key==='+'||e.key==='=') { if(mode==='3d') zoom3dAt(edit3d.width/2, edit3d.height/2, 1.12); else zoomAt(editCv.width/2, editCv.height/2, 1.12); }
  else if(e.key==='-'||e.key==='_') { if(mode==='3d') zoom3dAt(edit3d.width/2, edit3d.height/2, 1/1.12); else zoomAt(editCv.width/2, editCv.height/2, 1/1.12); }
  else if(e.key==='0') resetView();
});

// ===================== Init =====================
function buildPalette(){
  buildPalettePicker();
  const p=$('#palette');
  p.innerHTML='';
  PALETTES[paletteId].colors.forEach(([c,name])=>{
    const d=document.createElement('div');
    d.className='sw'; d.style.background=c; d.dataset.c=c; d.title=name+' · '+c;
    d.onclick=()=>pickColorPalette(c);
    p.appendChild(d);
  });
  syncColor();   // remarca la muestra activa si el color actual sigue en la paleta
}
// Rellena el <select> de paletas una sola vez y refleja la elegida.
function buildPalettePicker(){
  const sel=$('#palette-picker'); if(!sel) return;
  if(!sel.options.length){
    for(const [id,pal] of Object.entries(PALETTES)){
      const o=document.createElement('option');
      o.value=id; o.textContent=pal.emoji+' '+pal.name;
      sel.appendChild(o);
    }
    sel.onchange=()=>setPalette(sel.value);
  }
  sel.value=paletteId;
}
// Cambia la paleta activa: recuerda la elección, redibuja las muestras.
function setPalette(id){
  if(!PALETTES[id]) return;
  paletteId=id;
  PALETTE=PALETTES[id].colors.map(c=>c[0]);
  try{ localStorage.setItem('vf_palette',id); }catch(e){}
  buildPalette();
}
// Habitaciones = assets del servidor de tipo 'bloque' (Habitantes lo llena refreshHabitantesList()).
// Recibe el índice ya cargado por loadServerAssets, o lo pide si se llama suelto.
async function loadRooms(idx){
  const ul=$('#roster-habitaciones'); if(!ul) return;
  try{
    if(!idx) idx=await fetch('assets/index.json',{cache:'no-store'}).then(r=>r.json());
    const rooms=idx.filter(a=>a.type==='bloque');
    let saved=[]; try{ saved=(await apiHabitantes()).filter(h=>h.type==='bloque'); }catch(e){}   // guardadas por el usuario
    ul.innerHTML='';
    if(!rooms.length && !saved.length){ ul.innerHTML='<li class="muted">(sin habitaciones)</li>'; return; }
    rooms.forEach(a=>{
      const li=document.createElement('li');
      li.innerHTML=`<span class="ic">${a.icon||'🏠'}</span>${a.name}<span class="badge">asset</span>`;
      li.title='Cargar «'+a.name+'»';
      li.onclick=()=>loadFromUrl(a.file, a.id);
      ul.appendChild(li);
    });
    saved.forEach(h=>{
      const li=document.createElement('li');
      li.innerHTML=`<span class="ic">${h.icon||'🏠'}</span><div><span>${esc(h.name)}</span>`+
                   `<span class="badge" style="margin:0">guardada</span></div>`;
      li.title='Cargar «'+h.name+'»';
      li.onclick=()=>loadHabitante(h.id);
      ul.appendChild(li);
    });
  }catch(e){ ul.innerHTML='<li class="muted">Sirve por HTTP para cargar habitaciones</li>'; }
}

// ================== MAPA DEL MUNDO (F2) ==================
// Modelo: {cols,rows,cells:{"col,row":{room:<key>|null, habs:[{ref,x,y}]}}}
// key de habitación: 'asset:<file>' (asset del server) | 'hab:<id>' (habitación guardada).
let mapa=null, mapaCatalog=null, mapaSel=null;
const roomDataCache=new Map();     // key -> objeto {voxels,...}

async function getRoomData(key){
  if(roomDataCache.has(key)) return roomDataCache.get(key);
  // Una variante girada ('…@5', ver mcClaveBase) es el MISMO documento: solo cambia cómo se hornea su
  // geometría, no lo que hay en disco. Comparte la promesa con la clave base — ni un fetch de más.
  const base = (typeof mcFluidBase === 'function') ? mcFluidBase(mcClaveBase(key)) : mcClaveBase(key);
  if(base!==key){ const p=getRoomData(base); roomDataCache.set(key,p); return p; }
  const p=(async()=>{
    if(key.startsWith('asset:')) return fetch(key.slice(6),{cache:'no-store'}).then(r=>r.json());
    if(key.startsWith('hab:'))   return fetch('/api/habitantes/'+key.slice(4),{cache:'no-store'}).then(r=>r.json());
    return {voxels:{}};
  })();
  roomDataCache.set(key,p); return p;
}

// --- Defs de textura (comparten resolución/caché con getRoomData) ---
const texDefs=new Map();               // clave -> {size, voxels} de la textura ya resuelta
function computeTexRepr(def){          // color medio del bloque: representativo para 2D/tira
  let R=0,G=0,B=0,n=0;
  for(let c of Object.values(def.voxels||{})){ if(typeof c!=='string') continue; if(c[0]==='*') c=c.slice(1); if(c[0]!=='#') continue; const v=parseInt(c.slice(1,7),16); R+=v>>16&255; G+=v>>8&255; B+=v&255; n++; }
  if(!n) return '#8a8f94';
  return '#'+((1<<24)+((R/n&255)<<16)+((G/n&255)<<8)+(B/n&255)).toString(16).slice(1);
}
// El `size` de un doc puede ser escalar (texturas de fábrica, 16) o {x,y,z} (formato del editor).
// Una textura es cúbica: normaliza a un entero N>0 válido para createImageData/proyección.
function texSize(sz){
  let n = (sz && typeof sz==='object') ? (sz.x ?? sz.w ?? sz.size) : sz;
  n = Math.round(+n);
  return (Number.isFinite(n) && n>0) ? n : 16;
}
async function getTexDef(key){
  if(texDefs.has(key)) return texDefs.get(key);
  const d=await getRoomData(key);
  // `atravesable` viaja con la def porque mcBuildPalette es el unico sitio que recorre TODOS los
  // materiales del mundo con su documento en la mano: es ahi donde se hornea mc.atraviesaDoc.
  const def={ size:texSize(d.size), voxels:d.voxels||{}, caras:d.caras||null, atravesable:!!d.atravesable, aislante:!!d.aislante, inamovible:!!d.inamovible };
  texDefs.set(key,def); texReprCache.set(key, computeTexRepr(def));
  return def;
}
// Olvida todo lo cacheado de una textura (tras editarla y re-guardarla) => se recarga fresca
// Ojo con las variantes giradas ('…@5'): cuelgan del mismo documento, así que si se olvida solo la clave
// base se quedan servidas las viejas y la pieza girada seguiría saliendo con el dibujo de antes.
function invalidateTex(key){ texDefs.delete(key); texFaceCache.delete(key); texReprCache.delete(key); roomDataCache.delete(key); e3baseKey='';
  for(const m of [texDefs, texFaceCache, texReprCache, roomDataCache]) for(const k of [...m.keys()]) if(mcClaveBase(k)===key && k!==key) m.delete(k);
  for(const k in mc.finoGeom) if(mcClaveBase(k)===key) delete mc.finoGeom[k];
  for(const k in mc.structs) if(mcClaveBase(k)===key) delete mc.structs[k];
}
// Rehidrata texturas embebidas en un modelo cargado: pobla defs+caché+repr (render offline)
function ingestTextures(doc){
  if(!doc || !doc.textures) return;
  for(const [k,def] of Object.entries(doc.textures)){
    const d={ size:texSize(def.size), voxels:def.voxels||{}, caras:def.caras||null };
    texDefs.set(k,d); texReprCache.set(k, computeTexRepr(d));
    roomDataCache.set(k, Promise.resolve(d));
  }
}
async function buildRoomCatalog(){
  const cat=[];
  try{ const idx=await fetch('assets/index.json',{cache:'no-store'}).then(r=>r.json());
    idx.filter(a=>a.type==='bloque').forEach(a=>cat.push({key:'asset:'+a.file, name:a.name, icon:a.icon||'🏠', badge:'asset'})); }catch(e){}
  try{ (await apiHabitantes()).filter(h=>h.type==='bloque').forEach(h=>cat.push({key:'hab:'+h.id, name:h.name, icon:h.icon||'🏠', badge:'guardada'})); }catch(e){}
  mapaCatalog=cat; return cat;
}
function catEntry(key){ return (mapaCatalog||[]).find(c=>c.key===key); }

// ================== TEXTURAS (pinceles-objeto) ==================
// Una textura es un objeto de tipo 'textura'. Su id de pincel es la clave getRoomData
// ('asset:<file>' | 'hab:<id>'); el voxel pintado guardará 'tex:'+clave (F2/F3).
let texItems=[];                 // texturas cargadas {key,name,icon,group}
let texCat=null;                 // categoría activa del desplegable
async function refreshTexturas(idx){
  const strip=$('#texstrip'); if(!strip) return;
  try{
    if(!idx) idx=await fetch('assets/index.json',{cache:'no-store'}).then(r=>r.json());
    const assets=idx.filter(a=>a.type==='textura').map(a=>({key:'asset:'+a.file, name:a.name, icon:a.icon||'🎨', group:a.group||'Básicas'}));
    let saved=[]; try{ saved=(await apiHabitantes()).filter(h=>h.type==='textura').map(h=>({key:'hab:'+h.id, name:h.name, icon:h.icon||'🎨', group:'Mis texturas'})); }catch(e){}
    texItems=assets.concat(saved);
    buildTexCatPicker();          // llena/actualiza el <select> de categorías (como el de paletas)
    renderTexStrip();             // pinta solo las chips de la categoría activa
  }catch(e){ strip.innerHTML='<span class="muted">Sirve por HTTP para ver texturas</span>'; }
}
// Rellena el desplegable con las categorías presentes (orden de aparición) y recuerda la elegida.
function buildTexCatPicker(){
  const sel=$('#tex-cat'); if(!sel) return;
  const groups=[]; for(const it of texItems) if(!groups.includes(it.group)) groups.push(it.group);
  sel.innerHTML='';
  for(const g of groups){ const o=document.createElement('option'); o.value=g; o.textContent=g; sel.appendChild(o); }
  if(!texCat || !groups.includes(texCat)){
    let s=null; try{ s=localStorage.getItem('vf_texcat'); }catch(e){}
    texCat=(s && groups.includes(s)) ? s : groups[0];
  }
  sel.value=texCat||'';
  sel.hidden=groups.length<2;     // sin desplegable si solo hay una categoría
  sel.onchange=()=>{ texCat=sel.value; try{ localStorage.setItem('vf_texcat',texCat); }catch(e){} renderTexStrip(); };
}
// Pinta la tira con las texturas de la categoría activa.
function renderTexStrip(){
  const strip=$('#texstrip'); if(!strip) return;
  const items=texItems.filter(it=>it.group===texCat);
  strip.innerHTML='';
  if(!items.length){ strip.innerHTML='<span class="muted">(sin texturas)</span>'; return; }
  for(const it of items){
    const b=document.createElement('button');
    b.className='texchip'+(state.tex===it.key?' is-active':'');
    b.title=it.name; b.dataset.key=it.key;
    const cv=document.createElement('canvas'); cv.width=cv.height=34; b.appendChild(cv);
    b.onclick=()=>chooseTex(it.key);
    b.onmouseenter=()=>showTexPreview(it, b);   // vista previa grande al pasar por encima
    b.onmouseleave=hideTexPreview;
    strip.appendChild(b);
    getRoomData(it.key).then(d=>drawThumb(cv,d)).catch(()=>{});   // miniatura iso real
  }
}
// Popup de vista previa (miniatura grande) junto al chip apuntado.
function showTexPreview(it, anchor){
  const pv=$('#tex-preview'); if(!pv) return;
  pv.querySelector('.tp-name').textContent=(it.icon?it.icon+' ':'')+it.name;
  getRoomData(it.key).then(d=>drawThumb(pv.querySelector('canvas'), d)).catch(()=>{});
  pv.hidden=false;
  const r=anchor.getBoundingClientRect(), pw=pv.offsetWidth||184, ph=pv.offsetHeight||210;
  let x=r.right+10; if(x+pw>innerWidth-6) x=r.left-pw-10;   // a la derecha del chip, o a la izquierda si no cabe
  const y=Math.max(6, Math.min(innerHeight-ph-6, r.top+r.height/2-ph/2));
  pv.style.left=x+'px'; pv.style.top=y+'px';
}
function hideTexPreview(){ const pv=$('#tex-preview'); if(pv) pv.hidden=true; }
// Activa una textura como pincel; al pintar se escribe 'tex:'+key. Elegir un color la desactiva.
function chooseTex(key){
  state.tex=key;
  getTexDef(key).then(()=>syncColor()).catch(()=>{});   // asegura def + color representativo cargados
  syncColor();
}

// ---- Composición con escala (F4): habitación + habitantes reducidos, de pie sobre el suelo ----
// Downsample no destructivo: cada bloque f³ -> color mayoritario, si el bloque está bastante lleno.
function downsampleVox(d, f){
  const s=d.size||32, dim=(typeof s==='number')?{x:s,y:s,z:s}:s;
  const blocks=new Map();                       // "bx,by,bz" -> Map(color->conteo)
  for(const k in (d.voxels||{})){ const [x,y,z]=k.split(',').map(Number);
    const bk=Math.floor(x/f)+','+Math.floor(y/f)+','+Math.floor(z/f);
    let b=blocks.get(bk); if(!b){ b=new Map(); blocks.set(bk,b); }
    const c=d.voxels[k]; b.set(c,(b.get(c)||0)+1);
  }
  const minFill=Math.max(2, Math.round(f*f*f*0.10));   // evita inflar detalles finos a un pegote
  const out={}; let ex=0,ey=0,ez=0;
  for(const [bk,counts] of blocks){
    let best=null,bn=0,tot=0; for(const [c,n] of counts){ tot+=n; if(n>bn){bn=n;best=c;} }
    if(tot<minFill) continue;
    out[bk]=best; const [bx,by,bz]=bk.split(',').map(Number);
    ex=Math.max(ex,bx+1); ey=Math.max(ey,by+1); ez=Math.max(ez,bz+1);
  }
  return {voxels:out, ext:{x:ex,y:ey,z:ez}, dim:{x:Math.ceil(dim.x/f),y:Math.ceil(dim.y/f),z:Math.ceil(dim.z/f)}};
}
// Devuelve {voxels, size} = habitación + habitantes (habEntries=[{h:{x,y,ref}, d:datosHab}]) compuestos.
function composeRoomData(roomData, habEntries){
  const rs=roomData.size||28, rdim=(typeof rs==='number')?{x:rs,y:rs,z:rs}:rs;
  const native=rdim.x>=64;                     // sala a escala de personaje => personaje NATIVO
  const standZ=native?4:1;                     // losa de suelo 4 en las salas nativas
  const voxels={}; for(const k in (roomData.voxels||{})) voxels[k]=roomData.voxels[k];
  for(const {h,d} of (habEntries||[])){
    const ds=native ? (()=>{ const c=charShell(d); return {voxels:c.voxels, ext:c.ext}; })() : downsampleVox(d,4);
    const cx=Math.floor(ds.ext.x/2), cy=Math.floor(ds.ext.y/2);   // centra la huella en (h.x,h.y)
    for(const k in ds.voxels){ const [lx,ly,lz]=k.split(',').map(Number);
      const wx=h.x+(lx-cx), wy=h.y+(ly-cy), wz=standZ+lz;         // de pie sobre el suelo
      if(wx<0||wy<0||wz<0||wx>=rdim.x||wy>=rdim.y||wz>=rdim.z) continue;
      voxels[wx+','+wy+','+wz]=ds.voxels[k];
    }
  }
  return {voxels, size:rdim};
}
// Dibuja en `cv` la miniatura de una celda = habitación + sus habitantes compuestos.
async function drawCellComposed(cv, cell){
  try{
    const roomData=await getRoomData(cell.room);
    const habs=cell.habs||[];
    const entries=(await Promise.all(habs.map(h=>getRoomData(h.ref).then(d=>({h,d})).catch(()=>null)))).filter(Boolean);
    drawThumb(cv, composeRoomData(roomData, entries));
  }catch(e){}
}

async function openMapa(){
  const modal=$('#mapa-modal'); modal.hidden=false;
  const grid=$('#mapa-grid'); grid.innerHTML='<p class="hab-empty">Cargando…</p>';
  try{ mapa=await fetch('/api/mapa',{cache:'no-store'}).then(r=>r.json()); }
  catch(e){ grid.innerHTML='<p class="hab-empty">No se pudo cargar el mapa.</p>'; return; }
  if(!mapa.cells) mapa.cells={};
  await buildRoomCatalog();
  renderMapaGrid();
}
function closeMapa(){ $('#mapa-modal').hidden=true; closePicker(); }

// ===================== Gestor de snippets de código =====================
// Guarda/edita/ejecuta código (p.ej. constructores como buildMayanPyramid) contra el Mundo vía setVoxel.
// Persistencia en el servidor: /api/snippets (lista/uno/POST guardar/DELETE) → data/snippets/<id>.json.
let snips=[], snipCur=null;
const SNIP_TEMPLATE=
`// Snippet nuevo · usa setVoxel(x,y,z,material) para construir en el Mundo.
// Materiales: stone, smooth_stone, sandstone, stone_bricks, log, grass, dirt, sand, obsidian…
// Recuerda LLAMAR a tu función al final para que se ejecute (▶ Ejecutar / Ctrl+Enter).

function build(cx, cy, cz){
  for (let i = 0; i < 6; i++) setVoxel(cx, cy + i, cz, 'log');   // ejemplo: un tronco de 6
}
build(50, 15, 50);
`;
async function openSnips(){
  $('#snip-modal').hidden=false;
  const prev=snipCur;                                                            // al reabrir (Alt+C) vuelve al que estabas viendo, no al primero
  await snipReload();
  if(prev && snips.some(s=>s.id===prev)) snipLoad(prev);
  else if(snips.length) snipLoad(snips[0].id); else snipNew();
}
function closeSnips(){ $('#snip-modal').hidden=true; }
async function snipReload(){
  const list=$('#snip-list'); list.innerHTML='<p class="snip-empty">Cargando…</p>';
  try{ snips=await fetch('/api/snippets',{cache:'no-store'}).then(r=>r.json()); }
  catch(e){ list.innerHTML='<p class="snip-empty">No se pudo cargar.</p>'; return; }
  renderSnipList();
}
function renderSnipList(){
  const list=$('#snip-list'); list.innerHTML='';
  if(!snips.length){ list.innerHTML='<p class="snip-empty">Sin snippets. Crea uno con «+ Nuevo».</p>'; return; }
  for(const s of snips){
    const b=document.createElement('button'); b.className='snip-item'+(s.id===snipCur?' is-active':'');
    b.innerHTML='<b></b><small></small>';
    b.querySelector('b').textContent=s.name||'(sin nombre)';
    b.querySelector('small').textContent=(s.lines||1)+' líneas · '+(s.savedAt||'').replace('T',' ').slice(0,16);
    b.onclick=()=>snipLoad(s.id);
    list.appendChild(b);
  }
}
async function snipLoad(id){
  let d=null;
  try{ d=await fetch('/api/snippets/'+id,{cache:'no-store'}).then(r=>r.json()); }catch(e){}
  if(!d || d.error){ toast('No se pudo abrir el snippet'); return; }
  snipCur=d.id; $('#snip-name').value=d.name||''; $('#snip-code').value=d.code||'';
  // Los protegidos (el Mundo los ejecuta al entrar) se editan y se guardan, pero no se borran: se
  // esconde el botón para no ofrecer algo que el servidor va a rechazar. La lista trae el flag.
  const meta=snips.find(s=>s.id===d.id);
  $('#snip-del').hidden=!!(meta && meta.protegido); renderSnipList();
}
function snipNew(){
  snipCur=null; $('#snip-name').value=''; $('#snip-code').value=SNIP_TEMPLATE;
  $('#snip-del').hidden=true; renderSnipList(); $('#snip-name').focus();
}
async function snipSave(){
  const name=$('#snip-name').value.trim()||'Sin nombre', code=$('#snip-code').value;
  const body={ name, code }; if(snipCur) body.id=snipCur;
  let r=null;
  try{ r=await fetch('/api/snippets',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}).then(x=>x.json()); }catch(e){}
  if(!r || !r.id){ toast('No se pudo guardar'); return; }
  snipCur=r.id; await snipReload(); $('#snip-del').hidden=false; toast('Snippet guardado');
}
async function snipDelete(){
  if(!snipCur){ snipNew(); return; }
  if(!confirm('¿Borrar este snippet? (va a la papelera del servidor)')) return;
  let r=null;
  try{ r=await fetch('/api/snippets/'+snipCur,{method:'DELETE'}); }catch(e){}
  // Antes se decía «borrado» pasara lo que pasara: no se miraba la respuesta. Con snippets protegidos
  // (el Mundo ejecuta 'mundo-autoarranque' al entrar) eso anunciaría como hecho un borrado rechazado.
  if(!r || !r.ok){
    let msg='No se pudo borrar';
    if(r){ try{ const d=await r.json(); if(d && d.error) msg=d.error; }catch(e){} }
    toast(msg); return;
  }
  toast('Snippet borrado'); snipCur=null; await snipReload();
  if(snips.length) snipLoad(snips[0].id); else snipNew();
}
// Ejecuta un snippet DEJANDO CONSTANCIA de cuál es mientras corre (`mc._snippetActual`). Lo que un
// snippet registre en el motor —una acción de OSD, un comportamiento de bloque— puede así decir de
// dónde salió. Sin esto, «¿dónde cambio este botón?» no tiene respuesta: el código no está en ningún
// fichero del repo, sino en un documento del servidor que se edita en vivo.
// ── REQ-SNIP1 · DEPURAR UN SNIPPET ───────────────────────────────────────────────────────────────
// Un snippet no es un fichero: se compila con `new AsyncFunction(code)`, así que el navegador lo llama
// «VM2571» y da una línea que NO es la que se está mirando en el panel. Con eso, un error de sintaxis
// era una caza a ciegas sobre 4 000 líneas. Estas tres funciones traducen el fallo al código del panel.
//
// El DESFASE (el preámbulo `async function anonymous(\n) {\n` que el motor pone delante del cuerpo) no
// se escribe a mano: se MIDE una vez con una sonda. Vale 2 en los motores de hoy, pero cablearlo sería
// exactamente el tipo de número que se rompe en silencio con una versión nueva.
let _mcSnipDesfase = null;
function mcSnippetDesfase(){
  if(_mcSnipDesfase !== null) return _mcSnipDesfase;
  _mcSnipDesfase = 2;
  try{ const AF = Object.getPrototypeOf(async function(){}).constructor; new AF('opts', 'args', 'throw new Error("sonda-vf")')(); }
  catch(e){
    const m = /<anonymous>:(\d+):\d+/.exec((e && e.stack) || '');
    if(m) _mcSnipDesfase = (+m[1]) - 1;          // la sonda está en la línea 1 del cuerpo
  }
  return _mcSnipDesfase;
}
// Un SyntaxError no tiene pila que mirar —el código nunca llegó a existir—, así que la línea se busca
// COMPILANDO PREFIJOS: el primero que rompe por algo que no sea «se acabó el texto» es el culpable.
// Un prefijo cortado a mitad de un bloque siempre da «Unexpected end of input», y ése no cuenta.
function mcSnippetLineaSintaxis(code){
  const AF = Object.getPrototypeOf(async function(){}).constructor;
  const lineas = String(code||'').split('\n');
  const seAcabo = /unexpected end of (input|script)|unexpected eof/i;
  for(let i=0;i<lineas.length;i++){
    try{ new AF('opts', 'args', lineas.slice(0,i+1).join('\n')); }
    catch(e){ if(e instanceof SyntaxError && !seAcabo.test(e.message||'')) return i+1; }
  }
  return 0;                                       // no se ha podido acotar: mejor no señalar una línea al azar
}
// Informe al console: cabecera, la línea señalada con su cursor y dos líneas de contexto.
// Devuelve la línea (0 si no se supo) para que quien tenga interfaz la resalte.
function mcSnippetInforme(nombre, code, err){
  const lineas = String(code||'').split('\n');
  let linea = 0, col = 0;
  if(err instanceof SyntaxError){
    linea = mcSnippetLineaSintaxis(code);
  }else{
    const m = new RegExp('(?:vf-snippet/[^:]*|<anonymous>):(\\d+):(\\d+)').exec((err && err.stack) || '');
    if(m){ linea = Math.max(0, (+m[1]) - mcSnippetDesfase()); col = +m[2]; }
  }
  const tipo = (err && err.name) || 'Error';
  const msg  = (err && err.message) || String(err);
  const cab  = '✖ snippet «' + nombre + '» · ' + tipo + (linea ? ' en la línea ' + linea : '') + ': ' + msg;
  const trozos = [cab];
  if(linea > 0 && linea <= lineas.length){
    for(let n = Math.max(1, linea-2); n <= Math.min(lineas.length, linea+2); n++){
      trozos.push((n===linea ? ' → ' : '   ') + String(n).padStart(4) + ' │ ' + lineas[n-1]);
      if(n===linea && col > 0) trozos.push('        │ ' + ' '.repeat(Math.max(0,col-1)) + '↑');
    }
    if(err instanceof SyntaxError)
      trozos.push('   (es la primera línea donde el análisis se rompe; el descuido puede venir de la de antes)');
  }else{
    trozos.push('   (no se ha podido acotar la línea; la pila va debajo)');
  }
  console.error(trozos.join('\n'), err);
  return linea;
}
async function mcCorreSnippet(nombre, code, ...args){
  const antes = (typeof mc!=='undefined') ? mc._snippetActual : undefined;
  if(typeof mc!=='undefined') mc._snippetActual = nombre || null;
  const AsyncFunction = Object.getPrototypeOf(async function(){}).constructor;
  // `sourceURL` va al FINAL, así que no desplaza ni una línea, y a cambio la pila deja de decir «VM2571»
  // y dice el nombre del snippet — que es lo que se busca cuando el error sale tres capas más abajo.
  const conNombre = code + '\n//# sourceURL=vf-snippet/' + String(nombre||'anonimo').replace(/[^\w.-]/g,'_');
  const opts = args.length > 0 ? args[0] : undefined;
  try{
    const fn = new AsyncFunction('opts', 'args', conNombre);
    return await fn.call(this, opts, args.length > 1 ? args : (opts !== undefined ? opts : args), ...args);
  }
  catch(err){
    // La línea viaja EN el error: quien lo recoja arriba (el panel) no tiene que volver a calcularla
    // ni adivinarla, y quien no la quiera no se entera de que está.
    try{ err.vfLinea = mcSnippetInforme(nombre, code, err); }catch(e){}
    throw err;
  }
  finally{ if(typeof mc!=='undefined') mc._snippetActual = antes; }
}

// Lleva el cursor del panel a la línea que falló y la deja seleccionada: leer un número de línea y
// buscarla a mano en un textarea de 4 000 es la mitad del trabajo de depurar.
function snipMarcaLinea(linea){
  const ta = $('#snip-code');
  if(!ta || !linea) return;
  const lineas = ta.value.split('\n');
  if(linea > lineas.length) return;
  let ini = 0;
  for(let i=0;i<linea-1;i++) ini += lineas[i].length + 1;
  ta.focus();
  ta.setSelectionRange(ini, ini + lineas[linea-1].length);
  // El textarea no desplaza solo hasta la selección: se estima por altura de línea y se centra.
  const alto = parseFloat(getComputedStyle(ta).lineHeight) || 18;
  ta.scrollTop = Math.max(0, (linea-1)*alto - ta.clientHeight/2);
}

async function snipRun(){
  const code=$('#snip-code').value;
  const nombre = snipCur ? (snipCur.id || snipCur.name) : '(sin guardar, editor de snippets)';
  try{
    await mcCorreSnippet(nombre, code);
    toast('▶ Snippet ejecutado');
  }catch(err){
    // mcCorreSnippet ya ha volcado el informe al console; aquí solo queda lo que es de la interfaz.
    const linea = (err && err.vfLinea) || 0;
    snipMarcaLinea(linea);
    toast(linea ? ('Error en la línea ' + linea + ': ' + err.message) : ('Error en el snippet: ' + err.message));
  }
}
$('#snip-close').onclick=closeSnips;
$('#snip-refresh').onclick=snipReload;
$('#snip-new').onclick=snipNew;
$('#snip-save').onclick=snipSave;
$('#snip-run').onclick=snipRun;
$('#snip-del').onclick=snipDelete;
$('#snip-code').addEventListener('keydown',e=>{
  if((e.ctrlKey||e.metaKey) && e.key.toLowerCase()==='s'){ e.preventDefault(); snipSave(); }
  else if((e.ctrlKey||e.metaKey) && e.key==='Enter'){ e.preventDefault(); snipRun(); }
  else if(e.key==='Tab'){ e.preventDefault(); const t=e.target, s=t.selectionStart, en=t.selectionEnd;   // Tab = 2 espacios
    t.value=t.value.slice(0,s)+'  '+t.value.slice(en); t.selectionStart=t.selectionEnd=s+2; }
});
// ===================== Panel de agentes articulados (fase 3) =====================
// Compone piezas y articulaciones, y las enseña MOVIÉNDOSE.
//
// ⚠️ La pose NO se calcula aquí. §0 dice que app.js es agnóstico a cómo son los agentes, así que
// la compone la librería del Mundo: `game.esqueletos.preparar(doc)` devuelve una plantilla con una
// matriz por pieza y `pose(pl,{fase,giro,activo,andando})` las reescribe. Este panel solo DIBUJA lo
// que salga de ahí, y por eso el muñeco del preview y el que luego anda por el Mundo NO PUEDEN
// divergir: es literalmente el mismo código el que los coloca. Lo que hay aquí es un rasterizador
// de voxels y formularios; ni un grado de ángulo.
//
// La librería vive en un snippet y en esta pestaña nadie la ha ejecutado todavía (solo la ejecuta
// mcAutoarranque al entrar al Mundo), así que el panel la carga él mismo. Es idempotente.
let libMundoP=null;
function cargarLibMundo(){
  if(window.game && game.esqueletos && game.esqueletos.preparar) return Promise.resolve(true);
  if(!libMundoP) libMundoP=mcAutoarranque().then(()=>{
    const ok=!!(window.game && game.esqueletos && game.esqueletos.preparar);
    if(!ok) libMundoP=null;                                   // fallo: que el siguiente intento reintente
    return ok;
  });
  return libMundoP;
}

let agLista=[], agDoc=null, agSel=0, agPl=null, agRAF=0, agFase=0, agTPrev=0, agCat=null, agPrepId=0, agCargaId=0;
// Qué tarjetas de capacidad quedan desplegadas (el formulario se reconstruye entero en cada cambio).
const agAbiertas={seguir:true};
const agVista={yaw:0.6, pitch:0.32, zoom:1};
const agGeomCache=new Map();                                   // clave|rot -> caras ya fusionadas
// Las 6 caras del cubo unidad: normal y las 4 esquinas. El orden de los vértices da igual (se rellena,
// no se cullea por él): las traseras se descartan comparando la normal ya girada con la cámara.
const AG_CARAS=[
  {n:[-1,0,0]}, {n:[1,0,0]}, {n:[0,-1,0]}, {n:[0,1,0]}, {n:[0,0,-1]}, {n:[0,0,1]}
];
// Luz de estudio ATADA A LA CÁMARA, no al mundo: [derecha, arriba, hacia el espectador]. Con un sol
// fijo en coordenadas de mundo, girar el preview a un perfil dejaba las caras visibles en el suelo
// del término ambiente y el muñeco se veía casi negro. Así la cara que miras siempre recibe luz.
const AG_LUZ=[0.30,0.72,0.62];                                 // se normaliza abajo
const AG_PLANTILLA={ nombre:'agente nuevo',
  raiz:{nombre:'torso', pieza:'asset:assets/torso-zombie.vox.json', rot:0}, piezas:[] };

function agColorHex(v){
  if(typeof v!=='string') return '#8a8f94';
  if(v[0]==='*') v=v.slice(1);                                 // emisivo: para el preview es un color más
  if(v[0]==='#') return v.slice(0,7);
  if(v.slice(0,4)==='tex:') return texRepr(v.slice(4));
  return '#8a8f94';
}
function agRGB(hex){ const n=parseInt(hex.slice(1),16)||0; return [n>>16&255, n>>8&255, n&255]; }

// Los voxels de un dibujo, colocados como los coloca el Mundo al estampar. Las tres conversiones que
// no se ven y que, saltadas, dejan la pieza en otro sitio que el bicho de verdad:
//   · el editor es Z-arriba y el Mundo Y-arriba: el Y del dibujo es la PROFUNDIDAD.
//   · el origen es la esquina de la CELDA 16³ que contiene el mínimo, no el mínimo.
//   · `rot` son cuartos de vuelta con el sentido de mcRotXZ, sobre la caja redondeada a celdas.
// Es el mismo camino que mcStructGeom (app.js:4190) y que ladosDeDibujo en la librería; si alguno de
// los tres se desvía, el preview y el aabb del Mundo dejan de contar lo mismo.
function agGeom(clave, rot, doc){
  const ck=clave+'|'+rot, hit=agGeomCache.get(ck); if(hit) return hit;
  const src=(doc&&doc.voxels)||{}, T=MC_TILE, base=[];
  let minx=Infinity, minh=Infinity, minz=Infinity;
  for(const k in src){
    const p=k.split(','), ax=+p[0], ay=+p[1], az=+p[2], v=src[k];
    if(v==null || !Number.isFinite(ax) || !Number.isFinite(ay) || !Number.isFinite(az)) continue;
    base.push([ax, az, ay, v]);                                // [x, altura, profundidad, valor]
    if(ax<minx)minx=ax; if(az<minh)minh=az; if(ay<minz)minz=ay;
  }
  const g={caras:[]};
  if(!base.length){ agGeomCache.set(ck,g); return g; }
  const cx=Math.floor(minx/T)*T, ch=Math.floor(minh/T)*T, cz=Math.floor(minz/T)*T;
  let bx=0, bz=0;
  for(const b of base){ b[0]-=cx; b[1]-=ch; b[2]-=cz; if(b[0]+1>bx)bx=b[0]+1; if(b[2]+1>bz)bz=b[2]+1; }
  bx=Math.ceil(bx/T)*T; bz=Math.ceil(bz/T)*T;
  const lleno=new Set(), pos=[];
  for(const b of base){
    const r=mcRotXZ(b[0], b[2], rot, bx, bz);
    lleno.add(r[0]+','+b[1]+','+r[1]); pos.push([r[0], b[1], r[1], b[3]]);
  }
  g.caras=agFusionar(pos, lleno);
  agGeomCache.set(ck,g); return g;
}
// Fusiona caras coplanares del mismo color (greedy, como el mallado del Mundo). No es solo
// velocidad: la cabeza del zombie pasa de 1350 cuadros a un puñado, y menos cuadros = menos
// costuras del antialias del canvas entre caras que deberían ser UNA superficie.
function agFusionar(pos, lleno){
  const caras=[];
  for(let f=0;f<6;f++){
    const a=f>>1, d=AG_CARAS[f].n[a], u=(a+1)%3, v=(a+2)%3;
    const capas=new Map();                                     // rebanada -> Map("u,v" -> color)
    for(const q of pos){
      const nx=q[0]+(a===0?d:0), ny=q[1]+(a===1?d:0), nz=q[2]+(a===2?d:0);
      if(lleno.has(nx+','+ny+','+nz)) continue;                // tapada por su vecina: no se ve
      let cp=capas.get(q[a]); if(!cp){ cp=new Map(); capas.set(q[a],cp); }
      cp.set(q[u]+','+q[v], agColorHex(q[3]));
    }
    for(const [s,cp] of capas) agFusionarCapa(caras, f, a, u, v, s, cp);
  }
  return caras;
}
function agFusionarCapa(caras, f, a, u, v, s, cp){
  let u0=Infinity, u1=-Infinity, v0=Infinity, v1=-Infinity;
  for(const k of cp.keys()){ const p=k.split(','), pu=+p[0], pv=+p[1];
    if(pu<u0)u0=pu; if(pu>u1)u1=pu; if(pv<v0)v0=pv; if(pv>v1)v1=pv; }
  const hecho=new Set(), S=1/MC_TILE, pa=(AG_CARAS[f].n[a]>0)? s+1 : s;
  for(let pv=v0; pv<=v1; pv++) for(let pu=u0; pu<=u1; pu++){
    const k=pu+','+pv, col=cp.get(k); if(col===undefined || hecho.has(k)) continue;
    let w=1; while(pu+w<=u1){ const kk=(pu+w)+','+pv; if(cp.get(kk)!==col || hecho.has(kk)) break; w++; }
    let h=1;
    crecer: while(pv+h<=v1){
      for(let i=0;i<w;i++){ const kk=(pu+i)+','+(pv+h); if(cp.get(kk)!==col || hecho.has(kk)) break crecer; }
      h++;
    }
    for(let j=0;j<h;j++) for(let i=0;i<w;i++) hecho.add((pu+i)+','+(pv+j));
    const esq=[[0,0],[w,0],[w,h],[0,h]], val=new Float32Array(12);
    for(let i=0;i<4;i++){ const p=[0,0,0];
      p[a]=pa; p[u]=pu+esq[i][0]; p[v]=pv+esq[i][1];
      val[i*3]=p[0]*S; val[i*3+1]=p[1]*S; val[i*3+2]=p[2]*S; }
    caras.push({f, v:val, rgb:agRGB(col)});
  }
}

// ── El preview ──────────────────────────────────────────────────────────────────────────────────
// Proyección ortográfica con orden pintor, el mismo esqueleto que project3d pero sobre las matrices
// que devuelve la librería: cada pieza lleva la SUYA, así que aquí no hay jerarquía que recorrer.
const agBuf={xy:new Float32Array(0), z:new Float32Array(0), col:[], ord:null, n:0};
function agReservar(n){
  if(agBuf.ord && agBuf.xy.length>=n*8) return;
  const cap=Math.max(256, n*2);
  agBuf.xy=new Float32Array(cap*8); agBuf.z=new Float32Array(cap); agBuf.ord=new Uint32Array(cap);
  agBuf.col=new Array(cap);
}
// El lienzo lo estira el CSS (el dueño mira esto en el móvil), así que el buffer se ajusta a la caja
// real por dpr: con la resolución fija del HTML, un móvil estrecho lo escalaba y el voxel salía borroso.
function agResize(cv){
  const dpr=Math.min(2, window.devicePixelRatio||1);
  const w=Math.max(200, Math.round(cv.clientWidth*dpr)), h=Math.max(200, Math.round(cv.clientHeight*dpr));
  if(cv.width!==w || cv.height!==h){ cv.width=w; cv.height=h; }
}
function agDibujar(){
  const cv=$('#ag-canvas'); if(!cv) return;
  agResize(cv);
  const g=cv.getContext('2d'), W=cv.width, H=cv.height;
  g.clearRect(0,0,W,H);
  if(!agPl || !agPl.partes.length){
    g.fillStyle='#5a6270'; g.font='13px system-ui,sans-serif'; g.textAlign='center';
    g.fillText('Sin piezas que dibujar', W/2, H/2); return;
  }
  const cy=Math.cos(agVista.yaw), sy=Math.sin(agVista.yaw),
        cp=Math.cos(agVista.pitch), sp=Math.sin(agVista.pitch);
  // Ejes de la cámara en coordenadas de MUNDO: derecha, arriba y hacia el fondo. El tercero es el
  // gradiente de la profundidad, y con él se cullean las caras traseras sin depender del orden de
  // los vértices — que la matriz de una pieza puede espejar.
  const rx=cy,        ry=0,  rz=sy;
  const ux=sp*sy,     uy=cp,  uz=-sp*cy;
  const fx=-cp*sy,    fy=sp,  fz=cp*cy;
  // La luz se compone con esos mismos ejes (el tercero, negado: hacia el espectador), así que
  // acompaña al giro y la cara que se mira nunca cae al ambiente.
  const lwx=AG_LUZ[0]*rx+AG_LUZ[1]*ux-AG_LUZ[2]*fx,
        lwy=AG_LUZ[0]*ry+AG_LUZ[1]*uy-AG_LUZ[2]*fy,
        lwz=AG_LUZ[0]*rz+AG_LUZ[1]*uz-AG_LUZ[2]*fz;
  const ln=Math.hypot(lwx,lwy,lwz)||1;
  const lx=lwx/ln, ly=lwy/ln, lz=lwz/ln;
  // Encuadre: el eje de giro del cuerpo se queda quieto en el centro (si se centrase la caja, el
  // muñeco se pasearía por el lienzo al girar), y la escala cabe tanto de alto como al dar la vuelta.
  const c=agPl.caja, alto=Math.max(0.001, c[4]-c[1]);
  const radio=Math.max(0.001, 0.5*Math.hypot(c[3]-c[0], c[5]-c[2]));
  const esc=Math.min(0.80*H/alto, 0.42*W/radio)*agVista.zoom;
  const ox=W/2, oy=H/2, cxm=agPl.eje[0], cym=(c[1]+c[4])/2, czm=agPl.eje[2];
  let n=0, total=0;
  for(const P of agPl.partes) total+=agGeom(P.clave,P.rot,P.dibujo).caras.length;
  agReservar(total);
  const nrm=new Float32Array(18);
  for(const P of agPl.partes){
    const m=P.m, geo=agGeom(P.clave,P.rot,P.dibujo).caras;
    for(let f=0;f<6;f++){ const d=AG_CARAS[f].n;                // la normal, girada por la pieza
      nrm[f*3]  =m[0]*d[0]+m[4]*d[1]+m[8]*d[2];
      nrm[f*3+1]=m[1]*d[0]+m[5]*d[1]+m[9]*d[2];
      nrm[f*3+2]=m[2]*d[0]+m[6]*d[1]+m[10]*d[2];
    }
    for(const cara of geo){
      const nX=nrm[cara.f*3], nY=nrm[cara.f*3+1], nZ=nrm[cara.f*3+2];
      if(nX*fx+nY*fy+nZ*fz >= 0) continue;                      // mira al fondo: trasera
      const sh=0.42+0.58*Math.max(0, nX*lx+nY*ly+nZ*lz);
      const q=cara.v; let zs=0, k=n*8;
      for(let i=0;i<4;i++){
        const vx=q[i*3]+P.aa[0], vy=q[i*3+1]+P.aa[1], vz=q[i*3+2]+P.aa[2];
        const wx=m[0]*vx+m[4]*vy+m[8]*vz+m[12] - cxm,
              wy=m[1]*vx+m[5]*vy+m[9]*vz+m[13] - cym,
              wz=m[2]*vx+m[6]*vy+m[10]*vz+m[14] - czm;
        agBuf.xy[k+i*2]  = ox + (wx*rx+wy*ry+wz*rz)*esc;
        agBuf.xy[k+i*2+1]= oy - (wx*ux+wy*uy+wz*uz)*esc;
        zs += wx*fx+wy*fy+wz*fz;
      }
      const r=cara.rgb;
      agBuf.z[n]=zs; agBuf.ord[n]=n;
      agBuf.col[n]='rgb('+(r[0]*sh|0)+','+(r[1]*sh|0)+','+(r[2]*sh|0)+')';
      n++;
    }
  }
  const orden=agBuf.ord.subarray(0,n), z=agBuf.z;
  orden.sort((a,b)=>z[b]-z[a]);                                 // orden pintor: primero lo del fondo
  const xy=agBuf.xy;
  for(let i=0;i<n;i++){
    const j=orden[i], k=j*8;
    g.fillStyle=agBuf.col[j];
    g.beginPath(); g.moveTo(xy[k],xy[k+1]);
    g.lineTo(xy[k+2],xy[k+3]); g.lineTo(xy[k+4],xy[k+5]); g.lineTo(xy[k+6],xy[k+7]);
    g.closePath(); g.fill();
  }
}
function agLoop(t){
  agRAF=requestAnimationFrame(agLoop);
  const dt=agTPrev? Math.min(0.1,(t-agTPrev)/1000) : 0; agTPrev=t;
  const activo=$('#ag-activo').checked?1:0, andando=$('#ag-andando').checked?1:0;
  // ⚠️ Aquí la fase la mueve el RELOJ. En el Mundo avanza con la DISTANCIA recorrida (por eso un
  // zombie frenado contra una pared deja de pedalear), pero un preview no anda a ningún sitio. Es
  // la única divergencia con el bicho vivo, y la cuenta de las articulaciones es la misma.
  if(andando) agFase+=dt*2*Math.PI*1.2;
  if(agPl && window.game && game.esqueletos)
    game.esqueletos.pose(agPl, {fase:agFase, giro:+$('#ag-giro').value, activo, andando});
  agDibujar();
}

// ── Documento, lista y formulario ───────────────────────────────────────────────────────────────
async function openAgentes(){
  $('#ag-modal').hidden=false;
  agCat=null;                      // el catálogo se cacheaba de por vida: una pieza guardada en el
                                   // editor no salía en el desplegable hasta recargar la página

  if(!await cargarLibMundo()) toast('No he podido cargar la librería del Mundo: el preview no se moverá', 3);
  await agRecargar();
  if(!agDoc){ if(agLista.length) await agCargar(agLista[0].id); else agNuevo(); }
  if(!agRAF){ agTPrev=0; agRAF=requestAnimationFrame(agLoop); }
}
function closeAgentes(){
  $('#ag-modal').hidden=true;
  if(agRAF){ cancelAnimationFrame(agRAF); agRAF=0; }
}
async function agRecargar(){
  try{ agLista=await fetch('/api/agentes',{cache:'no-store'}).then(r=>r.json()); }catch(e){ agLista=[]; }
  agRenderLista();
}
function agRenderLista(){
  const el=$('#ag-list'); el.innerHTML='';
  if(!agLista.length){ el.innerHTML='<p class="ag-empty">Sin agentes guardados.</p>'; }
  for(const a of agLista){
    const b=document.createElement('button');
    b.className='ag-item'+(agDoc&&agDoc.id===a.id?' is-active':'');
    b.innerHTML='<b></b><small></small>';
    b.querySelector('b').textContent=a.nombre||a.id;
    // Un agente escrito a mano no trae `savedAt`; sin el filtro quedaba un «·» suelto al final.
    b.querySelector('small').textContent=[a.piezas+' piezas', (a.savedAt||'').replace('T',' ').slice(0,16)]
      .filter(Boolean).join(' · ');
    b.onclick=()=>agCargar(a.id);
    el.appendChild(b);
  }
  $('#ag-del').hidden=!(agDoc && agDoc.id && agLista.some(a=>a.id===agDoc.id));
}
// Dos agentes seguidos (o abrir el panel y elegir otro antes de que llegue el primero): la carga
// vieja NO puede pisar la nueva. Mismo billete que usa agPreparar() con agPrepId.
async function agCargar(id){
  const mio=++agCargaId;
  let d=null;
  try{ d=await fetch('/api/agentes/'+id,{cache:'no-store'}).then(r=>r.json()); }catch(e){}
  if(mio!==agCargaId) return;
  if(!d || d.error){ toast('No se pudo abrir el agente'); return; }
  agDoc=d; agSel=0; agRenderLista(); agRefrescar();
}
function agNuevo(){
  agCargaId++;                       // una carga en vuelo no debe pisar el agente recién creado
  agDoc=JSON.parse(JSON.stringify(AG_PLANTILLA)); agSel=0; agRenderLista(); agRefrescar();
  $('#ag-nombre').focus();
}
async function agGuardar(){
  if(!agDoc) return false;
  agDoc.nombre=$('#ag-nombre').value.trim()||'agente';
  let r=null;
  try{ r=await fetch('/api/agentes',{method:'POST',headers:{'Content-Type':'application/json'},
        body:JSON.stringify(agDoc)}).then(x=>x.json()); }catch(e){}
  if(!r || !r.id){ toast((r&&r.error)||'No se pudo guardar'); return false; }
  agDoc.id=r.id; await agRecargar(); toast('Agente guardado en data/agentes/'+r.id+'.json');
  return true;
}
// «Guardar como…» no es comodidad, es la única forma de sacar una copia: `POST /api/agentes` deriva
// el fichero de `d.id || d.nombre` (`server.py:437`), o sea que **el `id` manda sobre el nombre**.
// Cargar el zombie, renombrarlo y darle a Guardar reescribía `data/agentes/zombie.json` con otro
// nombre dentro; partir de un bicho que ya funciona para hacer una variante era imposible sin
// pisarlo. Quitarle el `id` al documento es justamente lo que convierte el guardado en un «como…».
function agNombreLibre(base){
  const hay=n=>agLista.some(a=>a.id===slug(n));
  if(!hay(base)) return base;
  for(let i=2;i<1000;i++){ const n=base+' '+i; if(!hay(n)) return n; }
  return base+' copia';
}
async function agGuardarComo(){
  if(!agDoc) return;
  const base=$('#ag-nombre').value.trim()||agDoc.nombre||'agente';
  const nom=(prompt('Guardar una copia como…', agNombreLibre(base))||'').trim();
  if(!nom) return;
  // El MISMO slug que `server.py:33-35`: si aquí se calculara de otra forma, el aviso de «ya existe»
  // mentiría justo en los casos raros (acentos, símbolos) y la copia pisaría un agente en silencio.
  const id=slug(nom), choca=agLista.find(a=>a.id===id);
  if(choca && !confirm('Ya hay un agente en «'+id+'.json» ('+(choca.nombre||id)+').\n'+
                       '¿Sobrescribirlo? La versión anterior se respalda en la papelera.')) return;
  const idAntes=agDoc.id, nomAntes=agDoc.nombre;
  agDoc.nombre=nom; delete agDoc.id;
  $('#ag-nombre').value=nom;
  if(await agGuardar()) return;
  agDoc.id=idAntes; agDoc.nombre=nomAntes;              // el POST falló: el panel vuelve al original
  $('#ag-nombre').value=nomAntes||'';                    // o el siguiente Guardar escribiría el fichero equivocado
}
async function agBorrar(){
  if(!agDoc || !agDoc.id) return;
  if(!confirm('¿Borrar «'+(agDoc.nombre||agDoc.id)+'»? (va a la papelera del servidor)')) return;
  let ok=false;
  try{ ok=(await fetch('/api/agentes/'+agDoc.id,{method:'DELETE'})).ok; }catch(e){}
  if(!ok){ toast('No se pudo borrar'); return; }
  toast('Agente borrado'); agDoc=null; await agRecargar();
  if(agLista.length) await agCargar(agLista[0].id); else agNuevo();
}
// Todas las piezas en una sola lista: la 0 es la raíz y las demás van en `piezas`. El resto del
// panel trabaja con este índice y no con dos colecciones.
function agPiezas(){ return agDoc? [agDoc.raiz].concat(agDoc.piezas||[]) : []; }
function agRefrescar(){
  if(!agDoc) return;
  $('#ag-nombre').value=agDoc.nombre||'';
  const ps=agPiezas();
  if(agSel>=ps.length) agSel=0;
  const ul=$('#ag-piezas'); ul.innerHTML='';
  ps.forEach((p,i)=>{
    const li=document.createElement('li'); li.className=(i===agSel?'is-active':'');
    const nm=document.createElement('span'); nm.textContent=p.nombre||('pieza '+i);
    const tag=document.createElement('span'); tag.className='ap-tag';
    tag.textContent=i===0? 'raíz' : (p.articula? (p.articula.eje==='y'?'gira':'cabecea') : (p.mirar?'mira':'fija'));
    li.appendChild(nm); li.appendChild(tag);
    // «Te lleva montado» va en su PROPIA etiqueta y no dentro de la de arriba: es ortogonal a lo que
    // hace la pieza —una cabeza puede mirarte y llevarte a la vez— y meterla ahí escondería lo otro.
    if(p.montable){ const mt=document.createElement('span'); mt.className='ap-tag'; mt.textContent='🧍 llevas'; li.appendChild(mt); }
    li.onclick=()=>{ agSel=i; agRefrescar(); };
    ul.appendChild(li);
  });
  agForm();
  agChips();
  agPreparar();
}
// Re-monta la plantilla del preview. Es asíncrono (los dibujos viajan por red, aunque la librería
// los cachea), así que las respuestas que lleguen tarde se descartan por número de petición: sin
// eso, teclear rápido en el formulario deja mandando a la plantilla de una versión anterior.
function agPreparar(){
  if(!agDoc || !window.game || !game.esqueletos) return;
  const mio=++agPrepId;
  Promise.resolve(game.esqueletos.preparar(JSON.parse(JSON.stringify(agDoc)))).then(pl=>{
    if(mio!==agPrepId) return;
    // La geometría fusionada se cachea por `clave|rot`, así que hay que soltarla JUSTO cuando entra el
    // plan nuevo, no antes: entre la petición y la respuesta el bucle de dibujo sigue pintando el plan
    // viejo y volvería a llenar la caché con el dibujo de antes. Ese era el «guardo la pieza y en el
    // editor de agentes sigo viendo el torso antiguo» que sobrevivía incluso limpiando al guardar.
    agGeomCache.clear();
    agPl=pl||null;
    const el=$('#ag-caja');
    if(el) el.textContent=agPl? ('alto '+(+(agPl.caja[4]-agPl.caja[1]).toFixed(4))+' · ancho '+
      (+(agPl.caja[3]-agPl.caja[0]).toFixed(4))+' bloques · '+agPl.partes.length+' piezas') : '';
  });
}
// Las piezas de agente son `type:'textura'` (así se editan y se guardan de vuelta en assets/, que
// es lo que deja reponer un pivote con 📍). Aquí NO SE ESCONDE NADA, y es a propósito: el filtro de
// antes (`type!=='textura' || group==='Agentes'`) dejaba fuera cualquier pieza nueva, porque el
// editor guarda todo como `textura` + `Bloques de construcción` (`server.py`, POST /api/assets) y
// **no hay UI para elegir el grupo** — copiar la cabeza, llamarla «Cabeza de Personaje» y guardarla
// la hacía invisible para siempre en este desplegable (también le pasaba a `cabeza`/`brazo`, las dos
// del zombie original). Lo que aquel filtro resolvía de verdad — que los azulejos de 1×1 no tapen
// los brazos — lo hace ahora el reparto en <optgroup> con **Agentes primero**.
const AG_GRUPOS=['Agentes','Piezas y objetos','Mis guardados','Bloques de construcción','Básicas','Mis texturas','Otros'];
async function agCatalogo(){
  if(agCat) return agCat;
  const out=[];
  try{ const idx=await fetch('assets/index.json',{cache:'no-store'}).then(r=>r.json());
    idx.forEach(a=>out.push({key:'asset:'+a.file, name:a.name,
      grupo: a.group==='Agentes' ? 'Agentes' : (a.type!=='textura' ? 'Piezas y objetos' : (a.group||'Otros'))})); }catch(e){}
  try{ (await apiHabitantes()).forEach(h=>out.push({key:'hab:'+h.id, name:h.name+' (guardado)',
    grupo: h.type==='textura' ? 'Mis texturas' : 'Mis guardados'})); }catch(e){}
  // Los grupos van en el orden de AG_GRUPOS (Agentes primero), y DENTRO de cada grupo por nombre:
  // el índice los trae en el orden en que se fueron guardando, que para buscar «la cabeza» no sirve
  // de nada. `localeCompare` con 'es' y `sensitivity:'base'` para que ni las mayúsculas ni los
  // acentos partan la lista (Ñ después de N, «Árbol» junto a «Arena»), y `numeric` para que
  // «grass 128x128» no se ordene por dígitos sueltos.
  const peso=g=>{ const i=AG_GRUPOS.indexOf(g); return i<0? AG_GRUPOS.length : i; };
  const cmp=new Intl.Collator('es',{sensitivity:'base', numeric:true});
  out.sort((a,b)=>peso(a.grupo)-peso(b.grupo) || cmp.compare(a.name, b.name));
  agCat=out; return out;
}
// El formulario de la pieza elegida. Se reconstruye entero en cada cambio: son ~10 campos y así no
// hay estado de UI que sincronizar con el documento — el documento es la única fuente de verdad.
function agForm(){
  const box=$('#ag-form'); box.innerHTML=''; if(!agDoc) return;
  const ps=agPiezas(), p=ps[agSel]; if(!p) return;
  const raiz=(agSel===0);
  const h=document.createElement('h4');
  h.textContent=raiz? 'Raíz · '+(p.nombre||'torso') : 'Pieza · '+(p.nombre||'');
  box.appendChild(h);
  const cambia=()=>{ agRefrescar(); };
  box.appendChild(agCampoTexto({t:'nombre', ayuda:
    'Cómo llamas TÚ a esta pieza, para reconocerla en la lista de arriba. El Mundo no lo mira: puedes '+
    'tener dos «brazo» sin que pase nada.'},
    p.nombre||'', v=>{ p.nombre=v; cambia(); }));
  const sel=agCampoSelect({t:'dibujo', ayuda:
    'Qué bloque se dibuja aquí. Vale cualquiera del catálogo, no solo los del grupo «Agentes». '+
    '⚠️ Un bloque de 16×16×16 macizo cuenta como TERRENO y el terreno no se puede animar: por eso las '+
    'piezas de un bicho se dibujan de 15 o menos.'},
    p.pieza||'', v=>{ p.pieza=v; cambia(); });
  box.appendChild(sel);
  agCatalogo().then(cat=>{
    const s=sel.querySelector('select'); if(!s) return;
    const val=p.pieza||'';
    s.innerHTML='';
    // Lo que el documento ya trae va SIEMPRE primero aunque el catálogo no lo conozca: si no, elegir
    // otra pieza y volver dejaría el <select> apuntando a un dibujo distinto del que dice el JSON.
    if(val && !cat.some(c=>c.key===val)) cat=[{key:val, name:val, grupo:'En el documento'}].concat(cat);
    let gr, cont=s;
    for(const c of cat){
      if(c.grupo!==gr){ gr=c.grupo; cont=document.createElement('optgroup'); cont.label=gr||'Otros'; s.appendChild(cont); }
      const o=document.createElement('option'); o.value=c.key; o.textContent=c.name; cont.appendChild(o);
    }
    s.value=val;
  });
  box.appendChild(agCampoNum({t:'rot (¼ de vuelta)', ayuda:
    'Cuántos cuartos de vuelta (0-3, o sea 0°, 90°, 180°, 270°) se gira el DIBUJO antes de nada, para '+
    'orientarlo sin tener que repintarlo. Ojo: los límites de «mira» se cuentan desde esta pose, así '+
    'que dos piezas iguales con rot distinto miran hacia lados opuestos.'},
    p.rot|0, 1, v=>{ p.rot=((v|0)%4+4)%4; cambia(); }));
  if(!raiz){
    const en=p.en||[0,0,0];
    box.appendChild(agTerna({t:'en (x, alto, z)', ayuda:
      'Dónde va la pieza respecto a la RAÍZ, en bloques (el alto es el del medio, y sube). Se puede '+
      'afinar por dieciseisavos: 0,0625 es un voxel.'},
      en, v=>{ p.en=v; cambia(); }));
  }
  // Articulación: sin ella la pieza va soldada al cuerpo, que es lo que quiere una hombrera.
  const art=p.articula||null;
  const bArt=agTarjeta(box, 'articula', '🔩', 'Se articula', !!art,
    art? ((art.eje==='y'?'gira':'cabecea')+' ±'+(+art.amplitud||0)+'° desde '+(+art.base||0)+'°')
       : 'soldada al cuerpo',
    v=>{ if(v) p.articula={pivote:1, base:0, reposo:0, amplitud:30, fase:0, eje:'x'};
         else delete p.articula; cambia(); });
  if(art){
    bArt.appendChild(agCampoSelect({t:'eje', ayuda:
      'Sobre qué eje gira la pieza. «x» la hace cabecear adelante y atrás, que es lo de un brazo o '+
      'una pierna; «y» la hace girar sobre sí misma como una torreta. No hay más: son los dos que '+
      'sabe componer la matriz de una pieza.'},
      art.eje==='y'?'y':'x', v=>{ art.eje=v; cambia(); },
      [{key:'x', name:'x · cabecea (brazo, pierna)'}, {key:'y', name:'y · gira (torreta)'}]));
    bArt.appendChild(agCampoNum({t:'pivote nº', ayuda:
      'Por qué punto engancha la pieza, o sea el centro del giro: es uno de los pivotes que dibujaste '+
      'en ella con la herramienta 📍, por su orden (el 1º dibujado es el nº 1). Un brazo tiene que '+
      'llevarlo en el hombro; si el dibujo no trae ninguno, la pieza gira por el centro de su caja y '+
      'se ve como aspas de molino.'},
      art.pivote===undefined?1:art.pivote, 1, v=>{ art.pivote=v|0; cambia(); }));
    bArt.appendChild(agCampoNum({t:'base (te ve)', ayuda:
      'Los grados en los que se queda la pieza MIENTRAS te ve y va a por ti; el vaivén se suma a este '+
      'ángulo. Los brazos del zombie en alto son esto: base 90.'},
      +art.base||0, 5, v=>{ art.base=v; cambia(); }));
    bArt.appendChild(agCampoNum({t:'reposo', ayuda:
      'Los grados en los que se queda cuando NO te ve, y a los que vuelve al perderte. Con reposo y '+
      'base iguales la pieza no cambia de pose al verte.'},
      +art.reposo||0, 5, v=>{ art.reposo=v; cambia(); }));
    bArt.appendChild(agCampoNum({t:'amplitud', ayuda:
      'Cuántos grados se balancea a cada lado mientras ANDA (±, sobre la pose que toque). A 0 la pieza '+
      'no se mueve aunque el bicho corra: queda rígida en su ángulo.'},
      +art.amplitud||0, 5, v=>{ art.amplitud=v; cambia(); }));
    bArt.appendChild(agCampoNum({t:'desfase (grados)', ayuda:
      'Por dónde del vaivén empieza esta pieza, para que no se muevan todas a la vez. 0 y 180 son el '+
      'paso contrario: pierna izquierda y pierna derecha. Un brazo va a 180 de su pierna del mismo lado.'},
      +art.fase||0, 15, v=>{ art.fase=v; cambia(); }));
    agNota(bArt, 'El ciclo avanza con la DISTANCIA recorrida, no con el reloj: parado deja de pedalear '+
                 'solo. Dos piezas iguales con desfase 0 y 180 son la pierna izquierda y la derecha.');
  }
  // `mirar` va aparte de la articulación y no es lo mismo: una articulación es un CICLO (fase,
  // amplitud) y esto lo manda el jugador — es la cabeza girándose hacia ti. La raíz no lo lleva
  // nunca: hacia dónde encara el cuerpo lo decide la persecución.
  if(!raiz){
    const mir=(p.mirar&&typeof p.mirar==='object')? p.mirar : null;
    const lim=(mir&&mir.limites&&mir.limites.y)||[-70,70];
    // BUG-AG9 · el cono vertical. `limites.x` es hermano del `y` de toda la vida y hay que leerlos
    // por separado: escribir uno pisando el objeto entero borraba el otro en silencio.
    const limV=(mir&&mir.limites&&mir.limites.x)||[-70,70];
    const bMir=agTarjeta(box, 'mirar', '👀', 'Te mira', !!mir,
      mir? ('alcance '+(+mir.alcance||12)+' · ±'+Math.abs(+lim[1]||70)+'°↔ · ±'+Math.abs(+limV[1]||70)+'°↕')
         : 'la pieza no gira',
      v=>{ if(v) p.mirar={alcance:12, limites:{y:[-70,70]}}; else delete p.mirar; cambia(); });
    if(mir){
      const ponLim=(eje,v)=>{ if(!mir.limites||typeof mir.limites!=='object') mir.limites={};
                              mir.limites[eje]=[-Math.abs(v), Math.abs(v)]; cambia(); };
      bMir.appendChild(agCampoNum({t:'alcance (bloques)', ayuda:
        'A qué distancia deja de seguirte con la vista y vuelve a mirar al frente. Si la pieza no gira, '+
        'lo primero que hay que mirar es esto: los rayos X dicen «en reposo (a 14 bloques, alcance 12)».'},
        +mir.alcance||12, 1, v=>{ mir.alcance=v; cambia(); }));
      bMir.appendChild(agCampoNum({t:'tope del cuello (±°)', ayuda:
        'Hasta dónde puede torcerse a cada lado. Pasado el cono se queda quieta en vez de darse la '+
        'vuelta entera: es lo que evita la cabeza del exorcista. Se cuenta desde la pose que le deja «rot».'},
        Math.abs(+lim[1]||70), 5,
        v=>ponLim('y', v)));
      bMir.appendChild(agCampoNum({t:'tope arriba y abajo (±°)', ayuda:
        'Cuánto puede levantar y bajar la vista. Fuera de este cono NO te ve: vuelve a su postura de '+
        'reposo en vez de quedarse clavada en el tope —quedarse clavada es seguir mirándote—, que es '+
        'lo que hacía que subiéndote a su cabeza te siguiera encarando. 90 mira recto arriba y recto '+
        'abajo, o sea el radar de antes. En gris significa que está en su valor por defecto.'},
        Math.abs(+limV[1]||70), 5,
        v=>ponLim('x', v), !(mir.limites&&mir.limites.x)));
      bMir.appendChild(agCampoNum({t:'suavidad del cuello (s)', ayuda:
        'Cuánto tarda en alcanzarte con la vista. 0 la clava en ti como un radar; subirlo hace el giro '+
        'más perezoso y más vivo. En gris significa que está en su valor por defecto.'},
        mir.suavidad!==undefined? +mir.suavidad : 0.12, 0.02,
        v=>{ mir.suavidad=v; cambia(); }, mir.suavidad===undefined));
      agNota(bMir, 'Gira RELATIVO al cuerpo: cuando la persecución ya te encara, el cuello no lo suma '+
                   'dos veces.');
    }
  }
  // 🧍 montable (REQ-MNT2). Antes solo se podía encender a mano y por instancia
  // (`game.esqueletos.montable(1,'cabeza')`), así que había que repetirlo cada vez que se plantaba el
  // bicho y no quedaba escrito en ninguna parte. La marca vive en la PIEZA del documento, al lado de
  // `articula` y `mirar`; quien la aplica es la librería al plantar (`crearEsqueleto` la copia a la
  // parte). Aquí solo se escribe la clave: app.js sigue sin saber qué es ir montado (§0).
  // Vale también en la raíz a propósito — un agente-plataforma (una barca, un ascensor) no tiene más
  // pieza que su torso. Y apagada NO se guarda, como el resto de capacidades: un agente de siempre
  // sale byte a byte igual que antes.
  box.appendChild(agCampoBool({t:'te lleva montado', ayuda:
    'Si te subes encima de ESTA pieza, el bicho te lleva: te mueves con ella y, cuando se vuelve, '+
    'orbitas con ella en vez de resbalarte. Subirse encima ya se podía siempre; lo que enciende esto '+
    'es que te LLEVE. Queda escrito en el agente, así que vale para todos los que plantes: '+
    'game.esqueletos.montable(id, «'+(p.nombre||'pieza')+'», false) solo lo apaga en un bicho suelto.'},
    !!p.montable, v=>{ if(v) p.montable=true; else delete p.montable; cambia(); }));
  if(raiz) agCapacidades(box, cambia);
  if(!raiz){
    const del=document.createElement('button'); del.className='btn sm danger'; del.textContent='Quitar esta pieza';
    del.onclick=()=>{ agDoc.piezas.splice(agSel-1,1); agSel=0; agRefrescar(); };
    box.appendChild(del);
  }
}
// Lo que NO es el esqueleto: qué sabe hacer el bicho entero. Cuelga del formulario de la RAÍZ
// porque no es de ninguna pieza. Va en TARJETAS, una por capacidad: plegada dice si está encendida
// y con qué valores, abierta enseña TODOS sus parámetros. Antes era una lista plana con 4 de los
// 20 parámetros, y `empuje` y `fisica` no aparecían por ninguna parte aunque el bicho las tuviera:
// un agente podía tener cosas encendidas que el panel no enseñaba.
//
// ⚠️ Dos reglas que no son cosméticas:
// · Los números que salen cuando el documento no trae la clave son los que de verdad va a usar la
//   librería (normalizarSeguir / crearEsqueleto / normalizarFisica), no ceros ni blancos: un 0 en
//   «distancia» diría que se te echa encima, y es justo lo contrario de lo que hace un agente sin
//   `seguir`. Van en gris cursiva (.def) para que no se lean como una decisión de nadie.
// · Abrir el panel NO debe engordar el documento: una capacidad encendida en su valor por defecto
//   se guarda sin la clave, y apagar una vuelve a borrarla. Los defectos viven en un solo sitio,
//   que es la librería; duplicarlos aquí es cómo se acaba con dos verdades distintas.
function agCapacidades(box, cambia){
  const h=document.createElement('h4'); h.className='ag-h2'; h.textContent='El bicho entero · capacidades';
  box.appendChild(h);
  agCapSeguir(box, cambia);
  agCapCabalgable(box, cambia);
  agCapAndar(box, cambia);
  agCapEmpuje(box, cambia);
  agCapFisica(box, cambia);
  agCapCuerpo(box, cambia);
  agCapEscala(box, cambia);
}
// 🏇 cabalgable (REQ-AG12). Montado en él te permite conducirlo con WASD/flechas en vez de ir como un pasajero pasivo.
function agCapCabalgable(box, cambia){
  const on=!!agDoc.cabalgable;
  const b=agTarjeta(box, 'cabalgable', '🏇', 'Cabalgable', on,
    on? 'se conduce con WASD / flechas al montarlo' : 'pasajero pasivo',
    v=>{ if(v) agDoc.cabalgable=true; else delete agDoc.cabalgable; cambia(); });
  if(!on){
    agNota(b, 'Enciéndela para que al subirte a una pieza montable del agente puedas conducirlo directamente con WASD / flechas en lugar de que vuelva a su ancla.');
    return;
  }
  agNota(b, 'Al subirte a cualquier pieza «te lleva montado» de este agente, la montura se frena y tus teclas de movimiento (WASD / flechas) la orientan y desplazan directamente a ella.');
}
// 📏 escala. «Para crear enanos y gigantes» (REQ-AGESC1). Multiplica la geometría de cada pieza Y las
// distancias entre ellas, así que el bicho crece entero en vez de desmontarse; la caja de choque va
// con él. Sin la clave, `escala` no se guarda: un agente de siempre sigue midiendo lo que medía.
function agCapEscala(box, cambia){
  const e=+agDoc.escala;
  const on=!!(e>0 && e!==1);
  const b=agTarjeta(box, 'escala', '📏', 'Escala del agente', on,
    on? '×'+e+(e>1?' (gigante)':' (enano)') : 'tamaño normal (×1)',
    v=>{ if(v) agDoc.escala=2; else delete agDoc.escala; cambia(); });
  if(!on){ agNota(b, 'Enciéndela para hacer enanos y gigantes con el MISMO dibujo: multiplica las piezas '+
                     'y lo que se separan entre ellas.'); return; }
  b.appendChild(agCampoNum('escala (1 = normal)', e, 0.25, v=>{
    // Los mismos topes que la librería (crearEsqueleto): un 0 o un negativo harían desaparecer al bicho.
    agDoc.escala=Math.max(0.1, Math.min(8, +v||1)); cambia(); }));
  agNota(b, 'Se multiplica también la caja de choque, así que un gigante no cabe por donde cabía antes. '+
            'Entre 0.1 y 8.');
}
// 👁 seguir. Apagarlo no es un matiz: la librería SE NIEGA a plantar un agente sin `seguir` (sin
// nada que perseguir no haría falta ningún rig), así que la tarjeta lo dice antes de guardar.
function agCapSeguir(box, cambia){
  const on=!(agDoc.seguir===false || agDoc.seguir===null);
  const seg=(agDoc.seguir&&typeof agDoc.seguir==='object')? agDoc.seguir : null;
  const S=(k,d)=>(seg&&seg[k]!==undefined)? +seg[k] : d;
  const hay=k=>!!(seg && seg[k]!==undefined);
  const ponS=(k,v)=>{ if(!agDoc.seguir||typeof agDoc.seguir!=='object') agDoc.seguir={}; agDoc.seguir[k]=v; cambia(); };
  const b=agTarjeta(box, 'seguir', '👁', 'Te persigue', on,
    on? ('te ve a '+S('deteccion',16)+' · se para a '+S('distancia',2.5)+' · '+S('velocidad',3)+' b/s')
      : 'plantado para siempre',
    v=>{ if(v) delete agDoc.seguir; else agDoc.seguir=false; cambia(); });
  if(!on){ agNota(b, 'La librería se niega a plantarlo y avisa. Para un bicho que espera quieto, baja '+
                     'la detección en vez de apagar esto.', true); return; }
  // La librería admite tres objetivos, pero para un RIG solo dos: seguir a OTRA CLAVE de material
  // busca la instancia más cercana con esa clave, y un esqueleto no es una instancia. No se ofrece
  // lo que la librería va a rechazar.
  const obj=seg? seg.objetivo : undefined, punto=Array.isArray(obj);
  b.appendChild(agCampoSelect('objetivo', punto?'punto':'jugador',
    v=>{ if(v!=='punto'){ if(seg) delete seg.objetivo; cambia(); }
         else ponS('objetivo', (window.mc&&mc.pos)? mc.pos.map(n=>Math.round(n)) : [0,0,0]); },
    [{key:'jugador', name:'el jugador'}, {key:'punto', name:'un punto fijo'}]));
  if(punto) b.appendChild(agTerna('punto (x, alto, z)', obj, v=>ponS('objetivo',v)));
  b.appendChild(agCampoNum({t:'detección (bloques)', ayuda:
    'El radio en el que arranca a perseguirte y fuera del cual te pierde de vista. 0 = alcance '+
    'infinito: no te pierde NUNCA, te sigue todo el rato estés donde estés.'},
    S('deteccion',16), 1, v=>ponS('deteccion',v), !hay('deteccion')));
  // BUG-AG10 · la detección era una ESFERA y este campo es lo que la convierte en un cono.
  b.appendChild(agCampoNum({t:'campo de visión (°)', ayuda:
    'El cono en el que te ve para EMPEZAR a perseguirte. 180 es todo lo que tiene delante; 360 es a su '+
    'alrededor, que es como funcionaba antes: pasarle por la espalda dentro de la detección bastaba '+
    'para que se diera la vuelta y te siguiera. Una vez en faena manda la detección, no el cono — si no, '+
    'parpadearía justo en el borde.'},
    S('vision',180), 15, v=>ponS('vision',v), !hay('vision')));
  b.appendChild(agCampoNum('se para a (bloques)', S('distancia',2.5), 0.5, v=>ponS('distancia',v), !hay('distancia')));
  b.appendChild(agCampoNum('velocidad (bloques/s)', S('velocidad',3), 0.2, v=>ponS('velocidad',v), !hay('velocidad')));
  b.appendChild(agCampoNum({t:'correa (bloques, 0 = suelto)', ayuda:
    'Lo que se puede alejar de DONDE LA PLANTASTE (su sitio), no de ti: es un atado a su sitio, '+
    'no una correa que la lleva a tu lado. Para que te siga de lejos no uses esto, sino «detección» '+
    'y «se para a». 0 = suelta, sin atar.'},
    S('correa',24), 1, v=>ponS('correa',v), !hay('correa')));
  b.appendChild(agCampoBool('vuelve a su sitio si te pierde', seg? seg.volver!==false : true, v=>ponS('volver',v)));
  b.appendChild(agCampoSelect('se mueve', (seg&&String(seg.ejes||'').toLowerCase()==='xyz')?'xyz':'xz',
    v=>ponS('ejes',v), [{key:'xz', name:'xz · pegado al suelo'}, {key:'xyz', name:'xyz · vuela'}]));
  b.appendChild(agCampoNum('suavidad del giro (s)', S('suavidad',0.12), 0.02, v=>ponS('suavidad',v), !hay('suavidad')));
  agNota(b, 'La distancia no es un mínimo, es un SITIO donde estar: si te acercas más, retrocede.');
}
// 🚶 andar. El interruptor es la cadencia: 0 ciclos por bloque = las patas no se mueven, que es lo
// que quiere un objeto mecánico que se desliza entero.
function agCapAndar(box, cambia){
  const and=(agDoc.andar&&typeof agDoc.andar==='object')? agDoc.andar : null;
  const cad=(and&&and.cadencia!==undefined)? +and.cadencia : 0.7, on=cad>0;
  const ponA=(k,v)=>{ if(!agDoc.andar||typeof agDoc.andar!=='object') agDoc.andar={}; agDoc.andar[k]=v; cambia(); };
  const b=agTarjeta(box, 'andar', '🚶', 'Anda', on, on? (cad+' pasos/bloque') : 'no mueve las patas',
    v=>{ if(v){ if(and){ delete and.cadencia; if(!Object.keys(and).length) delete agDoc.andar; } }
         else { if(!agDoc.andar||typeof agDoc.andar!=='object') agDoc.andar={}; agDoc.andar.cadencia=0; }
         cambia(); });
  // Ciclos de paso por BLOQUE recorrido (no por segundo): un bicho de patas cortas necesita más, y
  // con el número del zombie parece que va en patines.
  b.appendChild(agCampoNum('pasos por bloque', cad, 0.1, v=>ponA('cadencia',v), !(and&&and.cadencia!==undefined)));
  b.appendChild(agCampoNum('suavidad de la pose (s)', (and&&and.suavidad!==undefined)? +and.suavidad : 0.12, 0.02,
    v=>ponA('suavidad',v), !(and&&and.suavidad!==undefined)));
  // REQ-AG18 · antes se teletransportaba hasta arriba sin importar lo hondo que hubiera caído.
  b.appendChild(agCampoNum({t:'trepa al atascarse (bloques)', ayuda:
    'Andando sube SIEMPRE un escalón, y eso no se toca. Este número es lo que se atreve a trepar DE '+
    'UNA VEZ cuando lleva un rato queriendo ir a algún sitio y no avanza ni un milímetro — o sea, en '+
    'el fondo de un hoyo. 0 es «no trepa»: ni el escalón de andar, así que se queda donde lo dejen.'},
    (and&&and.escalar!==undefined)? +and.escalar : 3, 1, v=>ponA('escalar',v),
    !(and&&and.escalar!==undefined)));
  agNota(b, 'Por bloque RECORRIDO, no por segundo: frenado contra un muro deja de pedalear solo.');
}
// 👊 empuje (v1.25). El clic izquierdo sobre el bicho es un golpe, no un roto: sale despedido y pega
// un brinco. No hay clave para apagarlo entero, así que apagado es fuerza 0 y brinco 0 — aguanta el
// golpe sin moverse, que es lo que quiere una estatua.
function agCapEmpuje(box, cambia){
  const e=(agDoc.empuje&&typeof agDoc.empuje==='object')? agDoc.empuje : null;
  const E=(k,d)=>(e&&e[k]!==undefined)? +e[k] : d;
  const hay=k=>!!(e && e[k]!==undefined);
  const on=!(E('fuerza',8)===0 && E('salto',4.5)===0);
  const ponE=(k,v)=>{ if(!agDoc.empuje||typeof agDoc.empuje!=='object') agDoc.empuje={}; agDoc.empuje[k]=v; cambia(); };
  const b=agTarjeta(box, 'empuje', '👊', 'Empujable', on,
    on? ('fuerza '+E('fuerza',8)+' · brinco '+E('salto',4.5)) : 'aguanta el golpe',
    v=>{ if(v) delete agDoc.empuje; else agDoc.empuje={fuerza:0, salto:0}; cambia(); }, true);
  b.appendChild(agCampoNum('fuerza (bloques/s)', E('fuerza',8), 1, v=>ponE('fuerza',v), !hay('fuerza')));
  b.appendChild(agCampoNum('freno (s)', E('freno',0.15), 0.05, v=>ponE('freno',v), !hay('freno')));
  b.appendChild(agCampoNum('brinco (bloques/s)', E('salto',4.5), 0.5, v=>ponE('salto',v), !hay('salto')));
  agNota(b, 'El brinco solo sale desde el suelo: pegarle en el aire no lo encadena. Mientras sale '+
            'despedido sigue persiguiéndote, y por eso vuelve solo.');
}
// 🧊 fisica (v1.26). Lee la MISMA tabla de materiales que el jugador desde los pies del bicho:
// hielo, barro, trampolín, bordes. Encendida por defecto — un agente que ignora el suelo que pisa
// es el fallo, no la conducta normal.
function agCapFisica(box, cambia){
  const on=!(agDoc.fisica===false || agDoc.fisica===null);
  const f=(agDoc.fisica&&typeof agDoc.fisica==='object')? agDoc.fisica : null;
  const B=(k,d)=>(f&&f[k]!==undefined)? !!f[k] : d;
  const N=(k,d)=>(f&&f[k]!==undefined)? +f[k] : d;
  const hay=k=>!!(f && f[k]!==undefined);
  const ponF=(k,v)=>{ if(!agDoc.fisica||typeof agDoc.fisica!=='object') agDoc.fisica={}; agDoc.fisica[k]=v; cambia(); };
  const activas=[B('marcha',true)&&'hielo', B('desliza',true)&&'patina', B('impulso',true)&&'trampolín',
                 B('cae',true)&&'bordes', B('placas',false)&&'placas'].filter(Boolean);
  const comoTu=B('marcha',true)&&B('desliza',true)&&B('impulso',true)&&B('cae',true)&&!B('placas',false);
  const b=agTarjeta(box, 'fisica', '🧊', 'Pisa como tú', on,
    !on? 'ignora el suelo' : (comoTu? 'como el jugador' : (activas.join(' · ')||'nada encendido')),
    v=>{ if(v) delete agDoc.fisica; else agDoc.fisica=false; cambia(); }, true);
  if(!on){ agNota(b, 'Anda a su bola: ni el hielo le cambia el paso, ni el trampolín lo lanza, ni se '+
                     'cae por un borde.'); return; }
  b.appendChild(agCampoBool('el suelo le cambia la marcha (hielo ×2, barro ×0.5)', B('marcha',true), v=>ponF('marcha',v)));
  b.appendChild(agCampoBool('patina al parar (deslizamiento)', B('desliza',true), v=>ponF('desliza',v)));
  b.appendChild(agCampoBool('el trampolín lo lanza (impulso)', B('impulso',true), v=>ponF('impulso',v)));
  b.appendChild(agCampoBool('se cae por los bordes', B('cae',true), v=>ponF('cae',v)));
  b.appendChild(agCampoBool('dispara las placas (alPisar)', B('placas',false), v=>ponF('placas',v)));
  // El único interruptor que no se puede encender: trepar todavía no existe para un agente. Sale
  // en gris y apagado a propósito — dejarlo fuera de la lista haría pensar que se ha olvidado.
  const trepa=agCampoBool('trepa por las escaleras (todavía no)', false, ()=>{});
  trepa.querySelector('input').disabled=true; b.appendChild(trepa);
  b.appendChild(agCampoNum('peso (÷ impulso, 1 = como tú)', N('peso',1), 0.5, v=>ponF('peso',v), !hay('peso')));
  b.appendChild(agCampoNum('caída máxima (bloques)', N('caida',12), 1, v=>ponF('caida',v), !hay('caida')));
  agNota(b, 'Las placas van apagadas a propósito: el alPisar escrito hoy hace game.tp(...), o sea que '+
            'un zombie pisando una placa TE teletransportaría a ti. Trepar escaleras aún no está: '+
            'trepableEnColumna() está atada a las claves de mc.pos.');
}
// 🧱 cuerpo. Sin la clave, la caja de choque es la unión de las piezas.
function agCapCuerpo(box, cambia){
  const cue=(agDoc.cuerpo&&typeof agDoc.cuerpo==='object')? agDoc.cuerpo : null;
  const caja=agPl&&agPl.caja;
  const b=agTarjeta(box, 'cuerpo', '🧱', 'Caja de choque a medida', !!cue,
    cue? ((+cue.ancho||0.6)+' × '+(cue.fondo!==undefined? +cue.fondo : (+cue.ancho||0.6))+' × '+(+cue.alto||1.8))
       : 'la unión de las piezas',
    v=>{ if(v) agDoc.cuerpo={ancho:caja? +(caja[3]-caja[0]).toFixed(4):0.6,
                             fondo:caja? +(caja[5]-caja[2]).toFixed(4):0.6,
                             alto: caja? +(caja[4]-caja[1]).toFixed(4):1.8};
         else delete agDoc.cuerpo; cambia(); });
  if(!cue){ agNota(b, 'Un zombie con los brazos en cruz mide 1.4 de ancho y no cabe por una puerta.'); return; }
  const ponC=(k,v)=>{ agDoc.cuerpo[k]=v; cambia(); };
  b.appendChild(agCampoNum('ancho', +cue.ancho||0.6, 0.0625, v=>ponC('ancho',v)));
  b.appendChild(agCampoNum('fondo', cue.fondo!==undefined? +cue.fondo : (+cue.ancho||0.6), 0.0625, v=>ponC('fondo',v)));
  b.appendChild(agCampoNum('alto', +cue.alto||1.8, 0.0625, v=>ponC('alto',v)));
}
// La tarjeta. El interruptor vive en la CABECERA para que se vea encendido sin desplegar nada, y por
// eso su clic tiene que parar la burbuja: si no, encender una capacidad la plegaría en el mismo acto.
// Qué tarjetas quedan abiertas se guarda en `agAbiertas` y NO en el DOM: el formulario se reconstruye
// entero en cada tecla, así que cualquier estado que viva en el nodo se pierde al primer cambio.
function agTarjeta(box, clave, em, titulo, on, resumen, alConmutar, nuevo){
  const c=document.createElement('div');
  c.className='ag-cap '+(on?'on':'off')+(agAbiertas[clave]?' abierta':'');
  c.dataset.cap=clave;
  const h=document.createElement('div'); h.className='ag-cap-h';
  const fl=document.createElement('span'); fl.className='flecha'; fl.textContent=agAbiertas[clave]?'▾':'▸';
  const e=document.createElement('span'); e.className='em'; e.textContent=em;
  const t=document.createElement('b'); t.textContent=titulo;
  h.appendChild(fl); h.appendChild(e); h.appendChild(t);
  if(nuevo){ const n=document.createElement('span'); n.className='ag-nuevo'; n.textContent='NUEVO'; h.appendChild(n); }
  const chk=document.createElement('input'); chk.type='checkbox'; chk.checked=!!on;
  chk.onclick=ev=>ev.stopPropagation();
  chk.onchange=()=>{ if(chk.checked) agAbiertas[clave]=true; alConmutar(chk.checked); };
  h.appendChild(chk);
  const r=document.createElement('span'); r.className='resumen'; r.textContent=resumen;
  h.appendChild(r);
  h.onclick=()=>{ agAbiertas[clave]=!agAbiertas[clave];
                  c.classList.toggle('abierta', !!agAbiertas[clave]);
                  fl.textContent=agAbiertas[clave]?'▾':'▸'; };
  const cuerpo=document.createElement('div'); cuerpo.className='ag-cap-b';
  c.appendChild(h); c.appendChild(cuerpo); box.appendChild(c);
  return cuerpo;
}
function agNota(box, texto, aviso){
  const p=document.createElement('p'); p.className='ag-cap-nota'+(aviso?' aviso':'');
  p.textContent=texto; box.appendChild(p); return p;
}
// Los chips del preview: lo que sabe hacer el bicho de un vistazo, sin abrir ninguna tarjeta. Leen
// el MISMO documento que las tarjetas y con los mismos valores por defecto, o sea que el chip y el
// formulario no pueden decir cosas distintas.
function agChips(){
  const el=$('#ag-chips'); if(!el) return;
  el.innerHTML=''; if(!agDoc) return;
  const seg=(agDoc.seguir&&typeof agDoc.seguir==='object')? agDoc.seguir : null;
  const sigue=!(agDoc.seguir===false || agDoc.seguir===null);
  const and=(agDoc.andar&&typeof agDoc.andar==='object')? agDoc.andar : null;
  const cad=(and&&and.cadencia!==undefined)? +and.cadencia : 0.7;
  const emp=(agDoc.empuje&&typeof agDoc.empuje==='object')? agDoc.empuje : null;
  const fue=(emp&&emp.fuerza!==undefined)? +emp.fuerza : 8;
  const sal=(emp&&emp.salto!==undefined)? +emp.salto : 4.5;
  const fis=!(agDoc.fisica===false || agDoc.fisica===null);
  const cue=!!(agDoc.cuerpo&&typeof agDoc.cuerpo==='object');
  const mira=(agDoc.piezas||[]).some(q=>q&&q.mirar);
  // Por `agPiezas()` y no por `agDoc.piezas`: la raíz también puede llevarte (agente-plataforma).
  const monta=agPiezas().some(q=>q&&q.montable);
  const cabalg=!!(agDoc.cabalgable || (seg&&seg.cabalgable));
  const chips=[[sigue, sigue? '👁 te ve a '+((seg&&seg.deteccion!==undefined)? +seg.deteccion : 16) : '👁 plantado'],
               [cad>0, cad>0? '🚶 '+cad+' pasos/bloque' : '🚶 sin patas'],
               [!(fue===0&&sal===0), !(fue===0&&sal===0)? '👊 empujable' : '👊 aguanta el golpe'],
               [fis, fis? '🧊 pisa como tú' : '🧊 ignora el suelo'],
               [cue, cue? '🧱 caja a medida' : '🧱 caja de las piezas'],
               [mira, mira? '👀 te mira' : '👀 sin cuello'],
               [monta, monta? (cabalg? '🏇 cabalgable' : '🧍 te lleva encima') : '🧍 no te lleva']];
  for(const [on,txt] of chips){
    const s=document.createElement('span'); s.className='ag-chip'+(on?' on':''); s.textContent=txt;
    el.appendChild(s);
  }
}
function agCampoBool(etiqueta, val, set){
  const e=agRotulo(etiqueta), l=document.createElement('label'); l.className='ag-fld';
  const i=document.createElement('input'); i.type='checkbox'; i.checked=!!val;
  i.onchange=()=>set(i.checked);
  l.appendChild(i); l.appendChild(document.createTextNode(' '+e.t));
  const pis=agPista(l, e); if(pis){ l.appendChild(pis[0]); l.appendChild(pis[1]); }
  return l;
}
// Una etiqueta puede ser 'amplitud' o {t:'amplitud', ayuda:'…'}. Va así, y no como un argumento más,
// porque en agCampoNum el último ya lo tiene pillado `esDef`: con un objeto cualquier campo puede
// explicarse sin tocar ninguna firma ni el orden de los que ya existen.
function agRotulo(etiqueta){ return (etiqueta&&typeof etiqueta==='object')? etiqueta : {t:etiqueta}; }
// La ayuda sale por DOS vías a propósito: el `title` de siempre (el globo del navegador, escritorio)
// y un «?» que la despliega debajo del campo, porque en el móvil no hay hover y el globo no existe.
// Se abre con :focus y no con :hover para que las dos no se pisen, y así no hay que recordar cuál
// estaba abierta: el formulario se reconstruye entero en cada tecla y cualquier estado en el DOM se
// perdería (por eso `agAbiertas` vive fuera). Devuelve [botón, nota] SIN meterlos: el orden tiene que
// ser rótulo · ? · control · nota, porque la nota ocupa la fila entera y en medio partiría el campo.
function agPista(l, e){
  if(!e.ayuda) return null;
  l.classList.add('con-ayuda'); l.title=e.ayuda;
  const b=document.createElement('button');
  b.type='button'; b.className='ag-i'; b.textContent='?';
  b.setAttribute('aria-label', 'Qué es «'+e.t+'»');
  const n=document.createElement('small'); n.className='ag-tip'; n.textContent=e.ayuda;
  return [b, n];
}
function agCampo(etiqueta, ctrl){
  const e=agRotulo(etiqueta), l=document.createElement('label'); l.className='ag-fld';
  l.appendChild(document.createTextNode(e.t));
  const pis=agPista(l, e); if(pis) l.appendChild(pis[0]);
  l.appendChild(ctrl);
  if(pis) l.appendChild(pis[1]);
  return l;
}
function agCampoTexto(etiqueta, val, set){
  const i=document.createElement('input'); i.type='text'; i.value=val;
  i.onchange=()=>set(i.value); return agCampo(etiqueta, i);
}
// `esDef` = este número lo va a usar la librería pero el documento NO lo trae escrito. Se pinta en
// gris cursiva para que no se lea como un valor elegido por alguien; al tocarlo se escribe la clave.
function agCampoNum(etiqueta, val, paso, set, esDef){
  const i=document.createElement('input'); i.type='number'; i.step=paso; i.value=val;
  if(esDef) i.className='def';
  i.onchange=()=>set(+i.value||0); return agCampo(etiqueta, i);
}
function agCampoSelect(etiqueta, val, set, opts){
  const s=document.createElement('select');
  for(const o of (opts||[])){ const e=document.createElement('option'); e.value=o.key; e.textContent=o.name; s.appendChild(e); }
  s.value=val; s.onchange=()=>set(s.value); return agCampo(etiqueta, s);
}
// Los sitios van en BLOQUES, y un voxel del dibujo es 1/16: el paso del 0,0625 es lo que deja
// colocar una pieza voxel a voxel sin escribir decimales a mano.
function agTerna(etiqueta, val, set){
  const wrap=document.createElement('span'); wrap.className='ag-tern';
  const ins=[0,1,2].map(i=>{
    const n=document.createElement('input'); n.type='number'; n.step=0.0625; n.value=+val[i]||0;
    n.onchange=()=>set(ins.map(x=>+x.value||0));
    wrap.appendChild(n); return n;
  });
  return agCampo(etiqueta, wrap);
}
function agAnadirPieza(){
  if(!agDoc) return;
  if(!Array.isArray(agDoc.piezas)) agDoc.piezas=[];
  agDoc.piezas.push({nombre:'pieza '+(agDoc.piezas.length+1), pieza:agDoc.raiz.pieza, en:[0,1,0]});
  agSel=agDoc.piezas.length; agRefrescar();
}
// Plantarlo es cosa del Mundo: aquí solo se pide. Si no hay Mundo montado no hay dónde ponerlo.
// Plantar es IRSE al Mundo: se cierra el panel y, si veníamos del editor, se abre el Mundo — antes
// de crear el bicho, porque openWorld() reanuda los agentes y relanza el autoarranque.
async function agPlantar(){
  if(!agDoc){ return; }
  if(typeof mc==='undefined' || !mc || !mc.gl || !window.game || !game.esqueletos){
    toast('Abre el Mundo (🌍) y vuelve: es ahí donde se planta'); return;
  }
  closeAgentes();
  if($('#mc-modal').hidden) await openWorld();
  const yaw=mc.yaw||0, dx=-Math.sin(yaw)*3, dz=-Math.cos(yaw)*3;
  const h=await game.esqueletos.crear(agDoc, mc.pos[0]+dx, mc.pos[1], mc.pos[2]+dz);
  toast(h? 'Plantado ahí delante' : 'No se pudo plantar (mira la consola)');
}
$('#ag-close').onclick=closeAgentes;
$('#ag-new').onclick=agNuevo;
$('#ag-save').onclick=agGuardar;
$('#ag-save-as').onclick=agGuardarComo;
$('#ag-del').onclick=agBorrar;
$('#ag-add').onclick=agAnadirPieza;
$('#ag-plantar').onclick=agPlantar;
$('#ag-nombre').onchange=e=>{ if(agDoc) agDoc.nombre=e.target.value; };
$('#ag-modal').addEventListener('click',e=>{ if(e.target.id==='ag-modal') closeAgentes(); });
(()=>{                                                          // orbitar y acercar el preview
  const cv=$('#ag-canvas'); if(!cv) return;
  let arr=null;
  cv.addEventListener('pointerdown',e=>{ arr={x:e.clientX,y:e.clientY}; cv.classList.add('is-grab');
    cv.setPointerCapture(e.pointerId); });
  cv.addEventListener('pointermove',e=>{ if(!arr) return;
    agVista.yaw+=(e.clientX-arr.x)*0.01;
    agVista.pitch=Math.max(-1.2, Math.min(1.2, agVista.pitch+(e.clientY-arr.y)*0.008));
    arr={x:e.clientX,y:e.clientY}; });
  const suelta=()=>{ arr=null; cv.classList.remove('is-grab'); };
  cv.addEventListener('pointerup',suelta); cv.addEventListener('pointercancel',suelta);
  cv.addEventListener('wheel',e=>{ e.preventDefault();
    agVista.zoom=Math.max(0.3, Math.min(4, agVista.zoom*(e.deltaY<0?1.1:1/1.1))); },{passive:false});
})();

function renderMapaGrid(){
  const grid=$('#mapa-grid'); const {cols,rows}=mapa;
  grid.style.gridTemplateColumns=`repeat(${cols}, 1fr)`;
  grid.innerHTML='';
  for(let r=0;r<rows;r++) for(let c=0;c<cols;c++){
    const ck=c+','+r, cell=mapa.cells[ck];
    const el=document.createElement('div'); el.className='mapa-cell'+(cell&&cell.room?' filled':'');
    el.title='Celda '+ck;
    if(cell&&cell.room){
      const ent=catEntry(cell.room);
      const cv=document.createElement('canvas'); cv.width=cv.height=180; el.appendChild(cv);
      drawCellComposed(cv, cell);   // habitación + habitantes (escalados) compuestos
      const tag=document.createElement('span'); tag.className='mc-tag'; tag.textContent=ent?ent.name:'(borrada)'; el.appendChild(tag);
      const nh=(cell.habs||[]).length; if(nh){ const b=document.createElement('span'); b.className='mc-hab'; b.textContent='🧍'+nh; el.appendChild(b); }
      const pe=document.createElement('span'); pe.className='mc-people'; pe.textContent='🧍+'; pe.title='Colocar habitantes dentro';
      pe.onclick=(ev)=>{ ev.stopPropagation(); openRoom(ck); }; el.appendChild(pe);
    } else {
      const p=document.createElement('span'); p.className='mc-plus'; p.textContent='+'; el.appendChild(p);
    }
    el.onclick=()=>openPicker(ck);
    grid.appendChild(el);
  }
}
function openPicker(ck){
  mapaSel=ck;
  const pk=$('#mapa-picker'), g=$('#mapa-picker-grid');
  $('#mapa-picker-title').textContent='Habitación para la celda '+ck;
  g.innerHTML='';
  (mapaCatalog||[]).forEach(c=>{
    const o=document.createElement('div'); o.className='mapa-opt';
    o.innerHTML=`<div class="mo-thumb"><canvas width="120" height="120"></canvas></div>`+
                `<div class="mo-name">${c.icon} ${esc(c.name)}</div><div class="mo-badge">${c.badge}</div>`;
    getRoomData(c.key).then(d=>drawThumb(o.querySelector('canvas'),d)).catch(()=>{});
    o.onclick=()=>setCell(ck,c.key);
    g.appendChild(o);
  });
  if(!mapaCatalog||!mapaCatalog.length) g.innerHTML='<p class="hab-empty">No hay habitaciones. Crea una y guárdala como «Bloque de habitación».</p>';
  const occupied=!!(mapa.cells[ck]&&mapa.cells[ck].room);
  $('#mapa-picker-remove').hidden=!occupied;
  pk.hidden=false;
}
function closePicker(){ $('#mapa-picker').hidden=true; mapaSel=null; }
async function setCell(ck,roomKey){
  const prev=mapa.cells[ck]||{};
  mapa.cells[ck]={room:roomKey, habs:prev.habs||[]};
  closePicker(); renderMapaGrid(); await saveMapa();
}
async function removeCell(){
  if(!mapaSel) return;
  delete mapa.cells[mapaSel];
  closePicker(); renderMapaGrid(); await saveMapa();
}
let mapaSaveT=null;
function saveMapa(){                 // POST con pequeño debounce por si hay cambios rápidos
  clearTimeout(mapaSaveT);
  return new Promise(res=>{ mapaSaveT=setTimeout(async()=>{
    try{ await fetch('/api/mapa',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(mapa)}); toast('Mapa guardado'); }
    catch(e){ toast('No se pudo guardar el mapa'); } res();
  },120); });
}
$('#mapa-close').onclick=closeMapa;
$('#mapa-refresh').onclick=openMapa;
$('#mapa-picker-close').onclick=closePicker;
$('#mapa-picker-remove').onclick=removeCell;
$('#mapa-modal').addEventListener('click',e=>{ if(e.target.id==='mapa-modal') closeMapa(); });

// ================== HABITANTES DENTRO DE UNA HABITACIÓN (F3) ==================
// cells[ck].habs = [{ref:'hab:<id>', x, y}]  (x,y = celda del suelo de la habitación)
let roomCell=null, roomData=null, roomDim=null, roomTop=null, roomGeom=null, roomSelHab=-1, roomDragging=false, roomDown=null;
let roomHabNames={};   // ref -> {name, role}
const faceCache=new Map(), faceLoading=new Set();   // ref -> canvas con la cara (vista frontal, recorte cabeza)

// Cara del habitante: vista frontal (color del voxel de MÁS y por cada x,z) recortada a la cabeza+hombros.
function renderFace(cv,d){
  const ctx=cv.getContext('2d'), W=cv.width, H=cv.height; ctx.clearRect(0,0,W,H);
  const s=d.size||32, dim=(typeof s==='number')?{x:s,y:s,z:s}:s;
  const col={}, front={}; let minx=1e9,maxx=-1e9,minz=1e9,maxz=-1e9;
  for(const k in (d.voxels||{})){ const [x,y,z]=k.split(',').map(Number), key=x+','+z;
    if(front[key]===undefined||y>front[key]){ front[key]=y; col[key]=d.voxels[k]; }
    if(x<minx)minx=x; if(x>maxx)maxx=x; if(z<minz)minz=z; if(z>maxz)maxz=z; }
  if(maxx<minx) return;
  const bw=(maxx-minx+1)||1, fullh=(maxz-minz+1)||1;
  const cropH=Math.min(fullh, Math.max(bw, Math.round(bw*1.2)));   // cuadrado superior ≈ cabeza+hombros
  const zBot=maxz-cropH+1, cell=Math.min(W/bw, H/cropH), ox=(W-cell*bw)/2, oy=(H-cell*cropH)/2;
  for(const key in col){ const [x,z]=key.split(',').map(Number); if(z<zBot) continue;
    ctx.fillStyle=col[key]; ctx.fillRect(Math.floor(ox+(x-minx)*cell), Math.floor(oy+(maxz-z)*cell), Math.ceil(cell), Math.ceil(cell)); }
}
function ensureFace(ref){
  if(faceCache.has(ref)||faceLoading.has(ref)) return;
  faceLoading.add(ref);
  getRoomData(ref).then(d=>{ const c=document.createElement('canvas'); c.width=c.height=64; renderFace(c,d);
    faceCache.set(ref,c); faceLoading.delete(ref); if(roomCell) renderRoomCanvas(); })
    .catch(()=>faceLoading.delete(ref));
}

async function openRoom(ck){
  const cell=mapa.cells[ck]; if(!cell||!cell.room) return;
  roomCell=ck; roomSelHab=-1; roomDragging=false;
  if(!cell.habs) cell.habs=[];
  $('#room-modal').hidden=false;
  const ent=catEntry(cell.room);
  $('#room-title').textContent=(ent?ent.name:'Habitación')+' · celda '+ck;
  roomData=await getRoomData(cell.room);
  computeRoomTop();
  await buildRoomHabList();
  updateRoomDel(); renderRoomCanvas();
}
function closeRoom(){ $('#room-modal').hidden=true; roomCell=null; if(mapa) renderMapaGrid(); }

function computeRoomTop(){
  const s=roomData.size||28, dim=(typeof s==='number')?{x:s,y:s,z:s}:s;
  roomDim={x:dim.x||28, y:dim.y||28, z:dim.z||16};
  roomTop=new Array(roomDim.x*roomDim.y).fill(null);
  const topz=new Array(roomDim.x*roomDim.y).fill(-1);
  for(const k in (roomData.voxels||{})){ const [x,y,z]=k.split(',').map(Number);
    if(x<0||y<0||x>=roomDim.x||y>=roomDim.y) continue;
    const i=y*roomDim.x+x; if(z>topz[i]){ topz[i]=z; roomTop[i]=roomData.voxels[k]; } }
}
async function buildRoomHabList(){
  const ul=$('#room-hablist'); ul.innerHTML='<li class="muted">Cargando…</li>';
  let list; try{ list=await apiHabitantes(); }catch(e){ ul.innerHTML='<li class="muted">servidor no disponible</li>'; return; }
  list=list.filter(h=>habBucket(h.type)==='habitante');    // solo personajes/habitantes (no objetos ni bloques)
  roomHabNames={}; list.forEach(h=>roomHabNames['hab:'+h.id]={name:h.name, role:h.role||h.type});
  if(!list.length){ ul.innerHTML='<li class="muted">No hay habitantes. Crea uno y pulsa Guardar.</li>'; return; }
  ul.innerHTML='';
  list.forEach(h=>{
    const li=document.createElement('li');
    li.innerHTML=`<canvas width="60" height="60"></canvas>`+
                 `<div style="min-width:0"><div class="rh-name">${esc(h.name)}</div><div class="rh-role">${esc(h.role||h.type)}</div></div>`;
    getRoomData('hab:'+h.id).then(d=>drawThumb(li.querySelector('canvas'),d)).catch(()=>{});   // ver la otra galería
    li.title='Añadir «'+h.name+'» a la habitación';
    li.onclick=()=>addHabToRoom('hab:'+h.id);
    ul.appendChild(li);
  });
}
function addHabToRoom(ref){
  const habs=mapa.cells[roomCell].habs;
  const n=habs.length;                                              // escalona para que no se apilen
  const x=Math.min(roomDim.x-1, Math.floor(roomDim.x*0.5)+(n%4)*2),
        y=Math.min(roomDim.y-1, Math.floor(roomDim.y*0.5)+Math.floor(n/4)*2);
  habs.push({ref, x, y}); roomSelHab=habs.length-1;
  updateRoomDel(); renderRoomCanvas(); saveMapa();
  const nm=roomHabNames[ref]; toast('Añadido «'+((nm&&nm.name)||ref)+'» · arrástralo para colocarlo');
}
function updateRoomDel(){
  const b=$('#room-del'), habs=(mapa.cells[roomCell]||{}).habs||[];
  if(roomSelHab>=0 && habs[roomSelHab]){ const nm=roomHabNames[habs[roomSelHab].ref];
    b.hidden=false; b.textContent='Quitar: '+((nm&&nm.name)||'habitante'); }
  else b.hidden=true;
}
function renderRoomCanvas(){
  const cv=$('#room-canvas'), ctx=cv.getContext('2d'), W=cv.width, H=cv.height;
  ctx.clearRect(0,0,W,H); ctx.fillStyle='#0a0c12'; ctx.fillRect(0,0,W,H);
  const cell=Math.min(W/roomDim.x, H/roomDim.y), ox=(W-cell*roomDim.x)/2, oy=(H-cell*roomDim.y)/2;
  roomGeom={cell,ox,oy};
  for(let y=0;y<roomDim.y;y++) for(let x=0;x<roomDim.x;x++){
    const c=roomTop[y*roomDim.x+x]; if(!c) continue;
    ctx.fillStyle=c; ctx.fillRect(Math.floor(ox+x*cell), Math.floor(oy+y*cell), Math.ceil(cell), Math.ceil(cell));
  }
  // borde del suelo
  ctx.strokeStyle='rgba(255,255,255,.08)'; ctx.lineWidth=1; ctx.strokeRect(ox,oy,cell*roomDim.x,cell*roomDim.y);
  // marcadores de habitantes = su CARA (vista frontal) en un círculo
  const habs=mapa.cells[roomCell].habs||[], R=Math.max(10, cell*1.4);
  habs.forEach((h,i)=>{
    const px=ox+(h.x+0.5)*cell, py=oy+(h.y+0.5)*cell, sel=i===roomSelHab;
    ensureFace(h.ref);
    const face=faceCache.get(h.ref);
    ctx.save();
    ctx.beginPath(); ctx.arc(px,py,R,0,Math.PI*2); ctx.closePath();
    ctx.fillStyle='#0a0c12'; ctx.fill(); ctx.clip();
    if(face) ctx.drawImage(face, px-R, py-R, 2*R, 2*R);
    ctx.restore();
    ctx.beginPath(); ctx.arc(px,py,R,0,Math.PI*2);
    ctx.lineWidth=sel?4:2.5; ctx.strokeStyle=sel?'#ffd36a':'#3fe0ff';
    if(sel){ ctx.shadowColor='#ffd36a'; ctx.shadowBlur=8; } ctx.stroke(); ctx.shadowBlur=0;
  });
}
function roomPosFromEvent(e){
  const cv=$('#room-canvas'), r=cv.getBoundingClientRect();
  const sx=(e.clientX-r.left)*cv.width/r.width, sy=(e.clientY-r.top)*cv.height/r.height;
  const {cell,ox,oy}=roomGeom;
  return { gx:Math.max(0,Math.min(roomDim.x-1,Math.floor((sx-ox)/cell))),
           gy:Math.max(0,Math.min(roomDim.y-1,Math.floor((sy-oy)/cell))), sx, sy };
}
function roomHitMarker(sx,sy){
  const habs=mapa.cells[roomCell].habs||[], {cell,ox,oy}=roomGeom, R=Math.max(9, cell);
  for(let i=habs.length-1;i>=0;i--){ const px=ox+(habs[i].x+0.5)*cell, py=oy+(habs[i].y+0.5)*cell;
    if((sx-px)**2+(sy-py)**2<=R*R) return i; }
  return -1;
}
(function initRoomCanvas(){
  const cv=$('#room-canvas');
  cv.addEventListener('contextmenu',e=>e.preventDefault());
  cv.addEventListener('pointerdown',e=>{
    if(!roomCell) return; cv.setPointerCapture(e.pointerId);
    const p=roomPosFromEvent(e), hit=roomHitMarker(p.sx,p.sy);
    if(e.button===2){ if(hit>=0){ mapa.cells[roomCell].habs.splice(hit,1); roomSelHab=-1; updateRoomDel(); renderRoomCanvas(); saveMapa(); } return; }
    if(hit>=0){ roomSelHab=hit; roomDown={sx:p.sx,sy:p.sy}; roomDragging=false; }  // selecciona; mover requiere ARRASTRAR
    else { roomSelHab=-1; roomDown=null; }                                          // clic en vacío deselecciona
    updateRoomDel(); renderRoomCanvas();
  });
  cv.addEventListener('pointermove',e=>{
    if(!roomDown||roomSelHab<0) return;
    const p=roomPosFromEvent(e);
    if(!roomDragging && Math.hypot(p.sx-roomDown.sx, p.sy-roomDown.sy)<5) return;   // umbral: un clic no mueve
    roomDragging=true;
    const h=mapa.cells[roomCell].habs[roomSelHab]; h.x=p.gx; h.y=p.gy; renderRoomCanvas();
  });
  const end=()=>{ if(roomDragging) saveMapa(); roomDown=null; roomDragging=false; };
  cv.addEventListener('pointerup',end); cv.addEventListener('pointerleave',end);
})();
$('#room-del').onclick=()=>{ const habs=mapa.cells[roomCell].habs; if(roomSelHab>=0){ habs.splice(roomSelHab,1); roomSelHab=-1; updateRoomDel(); renderRoomCanvas(); saveMapa(); } };
$('#room-close').onclick=closeRoom;
$('#room-back').onclick=()=>{ closeRoom(); };
$('#room-modal').addEventListener('click',e=>{ if(e.target.id==='room-modal') closeRoom(); });

// ================== JUGAR (F5) ==================
// Clic en el suelo => ruta (esquiva sólidos) => el personaje camina y gira hacia la dirección.
const play={ active:false, cellKey:null, charRef:null, base:null, g:null, dim:null, walk:null,
             sprites:null, refFoot:null, baseImg:null, depth:null, exits:{}, transitioning:false, fade:0,
             pos:{x:0,y:0}, facing:0, path:[], speed:6.5, last:0, raf:0 };
let PLAY_W=760, PLAY_H=560;                          // se ajustan al tamaño real del escenario al cargar
// Encuadre del modo jugar: fillX>1 deja que las esquinas iso vacías se salgan por los lados para
// APROVECHAR el alto. Las salas anchas y bajas quedan limitadas por el ancho => subir fillX las
// agranda hasta llenar la altura (ajustable en vivo con `game.playFill`, persistido). fillY=1 para
// no recortar el suelo/techo de las salas altas (que ya llenan el alto).
let _playFillX=0.8; try{ const s=parseFloat(localStorage.getItem('vf_playFillX')); if(isFinite(s)&&s>=0.5) _playFillX=s; }catch(e){}
// Las salas son cáscaras SIN techo: la silueta de encuadre reserva alto para la tapa de los muros
// del FONDO (que se proyecta arriba pero queda OCLUIDA tras los muros de delante) => margen muerto
// arriba. Se corrige con un zoom (acerca) + una subida vertical (`playLift`, fracción del alto) que
// se comen ese margen. Ambos ajustables en vivo por consola (`game.playZoom` / `game.playLift`).
let _playZoom=1.05; try{ const s=parseFloat(localStorage.getItem('vf_playZoom')); if(isFinite(s)&&s>0.2) _playZoom=s; }catch(e){}
let _playLift=0.035; try{ const s=parseFloat(localStorage.getItem('vf_playLift')); if(isFinite(s)) _playLift=Math.max(0,Math.min(0.45,s)); }catch(e){}
const PLAY_VIEW={yaw:-2.42, pitch:0.62, zoom:_playZoom, panX:0, panY:0, fillX:_playFillX, fillY:1.0};
let PLAY_FACING_OFFSET=0;   // ajuste si el personaje mira al revés (0..3 giros de 90°)
// RECORTE del carril de puerta: voxels a cada lado del centro que se despejan de mueble para abrir
// un vano recto (media anchura del carril). Ajustable EN VIVO desde el visor de Jugar; se recuerda
// entre sesiones. Menos = muebles más intactos pero paso más estrecho; más = puerta ancha, recorta
// más mueble. carveDoorways/clearExitLanes y checkExit usan este valor.
let playTrim = 7;
try{ const v=parseInt(localStorage.getItem('vf_playTrim'),10); if(Number.isFinite(v)) playTrim=v; }catch(e){}
let _trimReloadT=null;
// Sin tope: acepta CUALQUIER entero (0, negativo = puerta cerrada, o enorme = vano de toda la sala).
// Los bucles de carveDoorways/clearExitLanes están acotados a la rejilla, así que no rompe nada.
function setPlayTrim(v, live){
  const n=Number(v);
  if(!Number.isFinite(n)){ console.warn('room.doorTrim: dame un número'); return playTrim; }
  playTrim=Math.round(n);
  try{ localStorage.setItem('vf_playTrim', playTrim); }catch(e){}
  if(live!==false && play.active){ clearTimeout(_trimReloadT); _trimReloadT=setTimeout(reloadPlayRoom, 90); }  // recarga en vivo (debounce)
  syncGameRoom();
  return playTrim;
}
// Inspector por CONSOLA (F12), sin UI. Teclear `room` a secas lista TODAS sus propiedades con su
// valor actual; leer una la devuelve (`room.doorTrim` => nº), y `room.doorTrim = 4` la ajusta y
// recarga la sala en vivo. Propiedades escribibles = solo las que tienen `set`; el resto es de solo
// lectura (reflejan el estado de la partida). `doorTrim` se recuerda entre sesiones.
const ROOM_PROPS = {
  doorTrim: { get:()=>playTrim, set:v=>setPlayTrim(v,true) },                       // recorte del carril de puerta (vox)
  name:  { get:()=>{ const c=mapa&&mapa.cells&&play.cellKey&&mapa.cells[play.cellKey], e=c&&catEntry(c.room); return e?e.name:null; } },
  cell:  { get:()=>play.cellKey||null },                                            // celda del mapa actual "col,row"
  exits: { get:()=>Object.keys(play.exits||{}) },                                   // salidas con vecino: W/E/N/S
  pos:   { get:()=>play.active?{x:Math.round(play.pos.x), y:Math.round(play.pos.y)}:null },
};
// BUG-RM1: `room` es un OBJETO PLANO (no Proxy) con accessors enumerables → la consola lo muestra
// como diccionario `{doorTrim, name, cell, exits, pos}` en vez de los slots internos del Proxy.
// `room.doorTrim` => nº · `room.doorTrim = 4` => ajusta y recarga · el resto es de solo lectura.
const room = {};
for(const k in ROOM_PROPS){ const p=ROOM_PROPS[k];
  Object.defineProperty(room, k, { enumerable:true,
    get:p.get, set:p.set || (()=>console.warn('room.'+k+' es de solo lectura')) });
}
window.room = room;

