  const cz0=Math.max(0,Math.floor(az0/MC_CHUNK)), cz1=Math.min(ncz-1,Math.floor(az1/MC_CHUNK));
  for(let nz=cz0;nz<=cz1;nz++) for(let nx=cx0;nx<=cx1;nx++) mcMeshChunk(nx,nz);
