// ── REQ-FLY1 · game.volar / game.fantasma / game.volarVel ────────────────────────────────────────────
// `game.volar` sigue el patrón función-valor de game.showFPS: vale como LECTURA (`game.volar` →
// false), como ORDEN (`game.volar(true)`) y como CONMUTADOR (`game.volar()`), que es lo que necesita la
// tecla F y lo que hace cómodo teclearlo en el inspector.
// NO se persiste en localStorage a propósito: el vuelo es un modo de una sesión, y encontrarse volando al
// abrir un mapa dos días después sería un fallo, no una comodidad (playerScale/speed sí persisten porque
// son preferencias del jugador, esto no).
function mcSetVolar(v){
  const antes=mc.volar;
  mc.volar=!!v;
  if(antes && !mc.volar) mc.vel[1]=0;   // al aterrizar el mando lo recoge la gravedad desde parado, sin un impulso heredado
  if(!mc.volar) mc.fantasma=false;      // sin vuelo no hay fantasma: el noclip a pie no existe
  return mc.volar;
}
Object.defineProperty(game,'volar',{ enumerable:true,
  get(){ const f=v=>mcSetVolar(v===undefined?!mc.volar:v); f.valueOf=()=>mc.volar; f.toString=()=>String(mc.volar); return f; },
  set(v){ mcSetVolar(v); } });
Object.defineProperty(game,'fantasma',{ enumerable:true,   // atraviesa el terreno; SOLO surte efecto volando
  get(){ const f=v=>{ mc.fantasma=(v===undefined?!mc.fantasma:!!v); return mc.fantasma; }; f.valueOf=()=>mc.fantasma; f.toString=()=>String(mc.fantasma); return f; },
  set(v){ mc.fantasma=!!v; } });
Object.defineProperty(game,'volarVel',{ enumerable:true, get:()=>mc.volarVel,
  set:v=>{ v=Math.max(0.1,Math.min(10, isFinite(+v)?+v:1)); mc.volarVel=v; return v; } });   // REQ-FLY2 · multiplicador sobre playerSpeed
// game.playerScale = tamaño del jugador (>1 grande → todo se ve más pequeño; <1 pequeño → todo más grande).
try{ const s=parseFloat(localStorage.getItem('vf_mcScale')); if(isFinite(s)&&s>0) mc.scale=s; }catch(e){}
Object.defineProperty(game,'playerScale',{ enumerable:true, get:()=>mc.scale,
  set:v=>{ v=Math.max(0.25,Math.min(64,+v||1)); mc.scale=v; try{localStorage.setItem('vf_mcScale',v);}catch(e){} if(mc.active) mcUnstick(); return v; } });
// game.playerTool = qué hace el clic: 'build' (pone al lado) | 'paint' (repinta el apuntado) | 'select' (marca caja)
// | 'pick' (cuentagotas: el material del apuntado va a la ranura activa). Se rotan con P.
//
// REQ-TOOL1: **por defecto el pico** (`build`), decisión del dueño, y la herramienta YA NO SE PERSISTE.
// Antes se guardaba en `vf_mcTool` pero al cargar solo se restauraban `build` y `paint`: una asimetría
// que no se veía porque la herramienta tampoco se veía. Con la ranura 10 delante, salir con la varita
// y volver con el pico habría parecido un fallo. Se arranca siempre igual y no hay nada que explicar.
try{ localStorage.removeItem('vf_mcTool'); }catch(e){}   // limpia lo que dejaron las versiones anteriores
function mcSetPlayerTool(v, announce){    // centraliza mc.tool (setter de consola + atajos B/P); persiste
  v=(v==='box'||v==='paint'||v==='select'||v==='pick')?v:'build'; mc.tool=v;
  mcPintaSlotHerramienta();          // la ranura 10 se entera aquí, venga el cambio de P, de la galería o de consola
  mcSetCrosshair(MC_HERRAMIENTA_MIRA[v] || '+');
  mc.selA=null;                                      // al cambiar de herramienta, olvida la esquina a medio marcar (la caja confirmada se conserva para Ctrl+C)
  if(v!=='box') mcBoxClear();
  if(announce && mc.active) toast(v==='box' ? 'Volumen: arrastra base con clic izq · fija altura con clic izq · clic dcho planta · clic izq reinicia'
                                : v==='select' ? 'Seleccionar: clic marca 2 esquinas · Ctrl+C copia · clic dcho limpia'
                                : v==='pick' ? 'Cuentagotas: clic sobre un bloque y su material va a la ranura'
                                : 'Clic derecho: '+(v==='paint'?'Pintar bloque':'Construir'));
  return v;
}
// Conmutación de herramientas:
// 'principales' (tecla 'e'): conmuta únicamente Construir ↔ Volumen
// 'secundarias' (tecla 'E' con mayúsculas / shift): conmuta Pintar → Seleccionar → Cuentagotas
function mcRotaHerramienta(grupo){
  if(grupo === 'secundarias' || grupo === 'sec' || grupo === true){
    const nextSec = { paint:'select', select:'pick', pick:'paint' };
    return mcSetPlayerTool(nextSec[mc.tool] || 'paint', true);
  }
  const nextPrinc = { build:'box', box:'build' };
  return mcSetPlayerTool(nextPrinc[mc.tool] || 'build', true);
}
Object.defineProperty(game,'playerTool',{ enumerable:true, get:()=>mc.tool, set:v=>mcSetPlayerTool(v) });
try{ const t=localStorage.getItem('vf_mcStructTex'); if(t!==null) mc.structTextures=(t!=='0'); }catch(e){}
// Textureado de las estructuras estampadas. true (por defecto) = textura COMPLETA por voxel como el editor 3D,
// vía atlas + shader del terreno (coste de geometría de nivel 1, sin tope aunque la sala sea la Taberna).
// false = color plano por cara (media, más barato) como escape de rendimiento. Re-malla en vivo todas las estructuras.
Object.defineProperty(game,'structTextures',{ enumerable:true, get:()=>mc.structTextures,
  set:v=>{ v=!!v; mc.structTextures=v; try{localStorage.setItem('vf_mcStructTex', v?'1':'0');}catch(e){}
    for(const k in mc.structs){ if(mc.structs[k]) mc.structs[k].meshRot={}; }   // invalida geometría (rebuild al reabrir si no está activo)
    if(mc.active) mcRestampAll(); return v; } });
try{ const t=localStorage.getItem('vf_mcStructGreedy'); if(t!==null) mc.structGreedy=(t!=='0'); }catch(e){}
// game.structGreedy = greedy meshing de las estructuras: fusiona caras coplanares del mismo material en rectángulos
// grandes (una pared lisa pasa de miles de cuadraditos a un puñado de quads) → muchas menos caras a dibujar, mismo
// aspecto (el tile se repite por voxel vía shader). true por defecto; false = una cara por voxel (comportamiento
// anterior, escape si algo se viera raro). Re-malla en vivo todas las estructuras.
Object.defineProperty(game,'structGreedy',{ enumerable:true, get:()=>mc.structGreedy,
  set:v=>{ v=!!v; mc.structGreedy=v; try{localStorage.setItem('vf_mcStructGreedy', v?'1':'0');}catch(e){}
    for(const k in mc.structs){ if(mc.structs[k]) mc.structs[k].meshRot={}; }   // invalida geometría cacheada
    if(mc.active) mcRestampAll(); return v; } });
try{ const t=localStorage.getItem('vf_mcOldStructBuild'); if(t!==null) mc.useOldStructBuild=(t==='1'); }catch(e){}
// game.useOldStructBuildCall = volver a la llamada de siempre al construir con el clic derecho. Desde que el
// mallador emite la geometría de verdad de lo que no llena su celda (mc.finoRejilla), poner una pieza que CABE
// en una celda y pintarla con setVoxel dan la misma imagen, así que el clic derecho usa setVoxel y esa pieza
// deja de costar un draw call. Lo que NO cabe (una sala, un árbol) se estampa igual que siempre; R/Shift+R sí
// van por la rejilla, porque el giro cabe en la clave (mcClaveConOri), salvo en lo que se proyecta como cubo.
// true = estampar SIEMPRE una pieza suelta, como antes.
Object.defineProperty(game,'useOldStructBuildCall',{ enumerable:true, get:()=>mc.useOldStructBuild,
  set:v=>{ v=!!v; mc.useOldStructBuild=v; try{localStorage.setItem('vf_mcOldStructBuild', v?'1':'0');}catch(e){}
    toast(v?'Clic derecho: estampa una pieza suelta (como antes)':'Clic derecho: setVoxel cuando la pieza cabe en una celda'); return v; } });
// game.interiorDark (t7) = penumbra automática de interiores por SKYLIGHT. La luz del cielo se difunde por el aire
// (mcComputeLight) perdiendo 1 nivel por bloque; la sombra de cada cara depende de la LUZ que le llega: plena junto
// a una boca / a cielo abierto, y hasta interiorDark en el fondo sin luz de un túnel. Al basarse en la luz REAL, no
// hay bandas por el grosor de tierra encima y una figura flotante apenas ensombrece el suelo (la luz entra de lado).
// Mapeo exponencial `interiorDark^((MAX-lv)/MAX)`: 1 = desactivado; 0.55 por defecto; **0 = interiores hasta negro**
// (una sala con poca luz se apaga del todo, no solo el fondo con luz 0). Re-malla el terreno en vivo y persiste.
try{ const d=parseFloat(localStorage.getItem('vf_mcInteriorDark')); if(isFinite(d)) mc.interiorDark=Math.max(0,Math.min(1,d)); }catch(e){}
Object.defineProperty(game,'interiorDark',{ enumerable:true, get:()=>mc.interiorDark,
  set:v=>{ v=Math.max(0,Math.min(1, isFinite(+v)?+v:0.1)); mc.interiorDark=v; try{localStorage.setItem('vf_mcInteriorDark',v);}catch(e){}
    if(mc.grid){ mcMeshAll(); if(mc.structures.length) mcRestampAll(); }   // re-oscurece terreno Y estructuras en vivo
    return v; } });
// game.sunShade = SOMBRA PROYECTADA del sol vertical, que es COSA APARTE de game.interiorDark. interiorDark es
// oclusión ambiental (cuánto cielo abierto tienes a mano, medido en horizontal); esto es geometría: si hay algo por
// encima, estás en sombra, y se aplica a las 6 caras porque cada una pregunta por el aire al que da. 1 = desactivada
// (y entonces ni se renderiza el mapa: coste cero); 0.55 por defecto; 0 = sombra a negro. NO re-malla nada — es un
// uniforme, así que cambia en el frame siguiente. Persiste en vf_mcSunShade.
// game.sunProbe = a qué distancia (en bloques) pregunta cada cara al mapa del sol. La sombra del sol vertical se
// resuelve con una altura por columna, así que una cara VERTICAL tiene que preguntar por una columna que no sea la
// suya (la suya siempre tiene su propio techo encima); por eso se sondea «hacia el aire al que da».
// Por qué 0.51 y no 0.5: EMPÍRICO, no derivado. El dueño veía manchas moteadas en los laterales de una estructura
// pegada a un bloque, barrió este valor en su GPU y a 0.51 se van. No está explicado por qué un cambio tan pequeño
// basta: el barrido headless (SwiftShader, 4 separaciones × 4 sondas) no midió NINGUNA diferencia de brillo, así que
// el moteado no se reproduce fuera de una GPU real y la causa sigue sin confirmarse. Sospecha viva, sin comprobar: el
// mapa se lee con NEAREST y 0.5 bloques puede caer justo en un borde de téxel, donde el redondeo elige uno u otro
// píxel a píxel. Si alguien lo confirma, que lo escriba aquí; mientras tanto no se toca porque «0.5 es más redondo».
// Mínimo útil ≈ 1 téxel del mapa (mc.dim.x/mc.shadowSize) o vuelve el acné.
// game.shadowMoveMs = cada cuánto, como mucho, se rehace el mapa de sombra cuando lo único que ha cambiado es que un
// agente se ha movido. Rehacerlo cuesta ~20 ms medidos con 48 estructuras (mundo entero a 2048²), así que hacerlo en
// cada frame mientras alguien anda es justo lo que tiraba los fps de 144 a 60-80 durante los segundos posteriores a
// colocar una estructura (los agentes reaccionan, se mueven un rato y luego se quedan quietos → los fps volvían).
// Una edición del mundo NO pasa por aquí: esa va por mcShadowDirty() y se rehornea en el acto.
// 0 = comportamiento de antes. Subirlo = más fps y la sombra de los que andan va a saltos.
try{ const d=parseFloat(localStorage.getItem('vf_mcShadowMoveMs')); if(isFinite(d)) mc.shadowMoveMs=Math.max(0,Math.min(500,d)); }catch(e){}
Object.defineProperty(game,'shadowMoveMs',{ enumerable:true, get:()=>mc.shadowMoveMs,
  set:v=>{ v=Math.max(0,Math.min(500, isFinite(+v)?+v:45)); mc.shadowMoveMs=v; try{localStorage.setItem('vf_mcShadowMoveMs',v);}catch(e){} return v; } });
try{ const d=parseFloat(localStorage.getItem('vf_mcSunProbe')); if(isFinite(d)) mc.sunProbe=Math.max(0.01,Math.min(1,d)); }catch(e){}
Object.defineProperty(game,'sunProbe',{ enumerable:true, get:()=>mc.sunProbe,
  set:v=>{ v=Math.max(0.01,Math.min(1, isFinite(+v)?+v:0.51)); mc.sunProbe=v; try{localStorage.setItem('vf_mcSunProbe',v);}catch(e){} return v; } });
try{ const d=parseFloat(localStorage.getItem('vf_mcSunShade')); if(isFinite(d)) mc.sunShade=Math.max(0,Math.min(1,d)); }catch(e){}
Object.defineProperty(game,'sunShade',{ enumerable:true, get:()=>mc.sunShade,
  set:v=>{ v=Math.max(0,Math.min(1, isFinite(+v)?+v:0.55)); mc.sunShade=v; try{localStorage.setItem('vf_mcSunShade',v);}catch(e){}
    mcShadowDirty(); return v; } });
// game.shadowSize = lado del mapa de sombra en téxeles (256..4096, potencia de 2 recomendada). Cubre el mundo entero,
// así que la resolución REAL es shadowSize/dim: 2048 sobre 96 bloques = 21 téxeles por bloque (borde de sombra a
// 1/21 de bloque). Subirlo afina el borde y cuesta memoria (2048² RGBA = 16 MB); bajarlo lo hace dentado.
try{ const n=parseInt(localStorage.getItem('vf_mcShadowSize'),10); if(isFinite(n)) mc.shadowSize=Math.max(256,Math.min(4096,n)); }catch(e){}
Object.defineProperty(game,'shadowSize',{ enumerable:true, get:()=>mc.shadowSize,
  set:v=>{ v=Math.max(256,Math.min(4096, parseInt(v,10)||2048)); mc.shadowSize=v; try{localStorage.setItem('vf_mcShadowSize',v);}catch(e){}
    mcFreeShadow(); return v; } });   // mcInitShadow lo reserva de nuevo al siguiente frame
// game.glowLevel = alcance de la LUZ DE BLOQUE emisiva (voxeles *#hex): nivel de siembra 0..MC_MAXLIGHT (−1/paso por el
// aire). 0 = sin luz de bloque; 15 (=MC_MAXLIGHT, alcance máx) por defecto. La luz es escalar/neutra (no tiñe) en v1. Persiste en vf_mcGlow; al
// cambiarlo recalcula la luz de bloque, re-malla el terreno y re-hornea las estructuras (paredes cercanas encendidas).
try{ const g=parseInt(localStorage.getItem('vf_mcGlow'),10); if(isFinite(g)) mc.glowLevel=Math.max(0,Math.min(MC_MAXLIGHT,g)); }catch(e){}
Object.defineProperty(game,'glowLevel',{ enumerable:true, get:()=>mc.glowLevel,
  set:v=>{ v=Math.max(0,Math.min(MC_MAXLIGHT, isFinite(+v)?(+v|0):15)); mc.glowLevel=v; try{localStorage.setItem('vf_mcGlow',v);}catch(e){}
    if(mc.grid){ mc._blEmiSig=null; mcComputeBlockLight(); mcMeshAll(); if(mc.structures.length) mcRestampAll(); }   // _blEmiSig=null: glowLevel/glowFocus no cambian la firma del BFS ⇒ sin esto mcComputeBlockLight se saltaría y no verías el cambio hasta editar un bloque
    return v; } });
// game.glowFocus = ESTRECHEZ del HAZ emisivo 0..1. 0 = omnidireccional (antorcha: la luz sale por igual en todas direcciones);
// sube = haz más estrecho y largo hacia la normal neta de las caras emisivas expuestas (mapea a la penalización de paso
// PERPENDICULAR en el BFS anisótropo: focus·5 → un paso de lado cuesta hasta 6 niveles, así el cono se cierra). 0.2 por
// defecto (1 = lo más fino). La dirección es geométrica: si pintas todas las caras visibles emisivas las normales se
// cancelan → omnidireccional aunque focus=1. Persiste en vf_mcGlowFocus; recalcula la luz de bloque + re-hornea.
try{ const gf=parseFloat(localStorage.getItem('vf_mcGlowFocus')); if(isFinite(gf)) mc.glowFocus=Math.max(0,Math.min(1,gf)); }catch(e){}
Object.defineProperty(game,'glowFocus',{ enumerable:true, get:()=>mc.glowFocus,
  set:v=>{ v=Math.max(0,Math.min(1, isFinite(+v)?+v:0.2)); mc.glowFocus=v; try{localStorage.setItem('vf_mcGlowFocus',v);}catch(e){}
    if(mc.grid){ mc._blEmiSig=null; mcComputeBlockLight(); mcMeshAll(); if(mc.structures.length) mcRestampAll(); }   // _blEmiSig=null: glowLevel/glowFocus no cambian la firma del BFS ⇒ sin esto mcComputeBlockLight se saltaría y no verías el cambio hasta editar un bloque
    return v; } });
// game.glowGain = INTENSIDAD de la luz artificial (antorchas, gafas de agente…). 1 = tope normal (una superficie a plena
// luz de bloque llega al brillo de pleno día, ni más). >1 SOBREEXPONE: sube el techo del mix de exposición (uGlowGain), así
// una fuente brilla MÁS que el día (se «quema» a blanco cuanto más alto). NO confundir con MC_MAXLIGHT (eso son NIVELES de
// gradación/alcance, no intensidad: lightLut normaliza /MC_MAXLIGHT ⇒ a tope siempre ×1). NO re-siembra ni re-malla —es solo
// un uniforme que el shader lee cada frame— ⇒ cambio LIVE y baratísimo. 0 = apaga la aportación artificial. Persiste en vf_mcGlowGain.
try{ const gg=parseFloat(localStorage.getItem('vf_mcGlowGain')); if(isFinite(gg)) mc.glowGain=Math.max(0,Math.min(16,gg)); }catch(e){}
Object.defineProperty(game,'glowGain',{ enumerable:true, get:()=>mc.glowGain,
  set:v=>{ v=Math.max(0,Math.min(16, isFinite(+v)?+v:1)); mc.glowGain=v; try{localStorage.setItem('vf_mcGlowGain',v);}catch(e){}
    return v; } });   // solo uniforme: el bucle de render lo aplica en el siguiente frame, sin recalcular nada
// game.worldSize (t8) = límites del mundo. Lectura: '96×40×96'. Redimensionar en vivo: game.resizeWorld(x,y,z)
// (x/z 16..512, y 8..256). Conserva los bloques anclados en el origen, recoloca al jugador dentro y re-malla; las
// estructuras estampadas mantienen sus coords de mundo. Persiste en el servidor (dim viaja en el guardado).
Object.defineProperty(game,'worldSize',{ enumerable:true, get:()=>mc.dim.x+'×'+mc.dim.y+'×'+mc.dim.z });
game.resizeWorld=function(x,y,z){
  // Admite tres números — resizeWorld(90,40,90) — o una sola cadena "AxBxC" (x, X o ×): resizeWorld("90x40x90").
  if(typeof x==='string' && y===undefined){
    const p=x.split(/[x×X*,\s]+/).filter(s=>s.length);
    if(p.length===3){ x=+p[0]; y=+p[1]; z=+p[2]; }
  }
  const d=mcResizeWorld(x,y,z); if(mc.active) toast('Mundo: '+d.x+'×'+d.y+'×'+d.z); return d.x+'×'+d.y+'×'+d.z;
};
// game.unstick() = sácame de donde esté incrustado (equivale a la tecla U): sube por encima de lo que estorbe;
// si no encuentra hueco, teletransporta al spawn. Útil si cargaste el mundo dentro de una estructura.
game.unstick=function(){ if(!mc.active) return 'abre el Mundo primero'; mcForceUnstick(); return 'ok'; };
// game.atasco() = POR QUÉ estás atascado (REQ-DBG2). Mira dónde estás AHORA y devuelve quién te
// atrapa, repartido en las tres cosas que pueden hacerlo: `terreno` (bloques de mc.grid, con su clave
// y su celda), `piezas` (estructuras finas — ahí viven las piezas de los agentes articulados, y si el
// snippet tiene enganchado mcStuckExtra cada una trae su `etiqueta`: «el brazo izq de Zombie», más
// `agente` y `agenteId` para poder hacer game.esqueletos.empujar(agenteId) sin parsear el texto) y
// `npcs` (los NPC-cubo de mc.agents/game.defineAgent, que son OTRA cosa que los agentes articulados:
// éstos salen en `piezas`, un miembro por entrada). `motivo` es el texto corto que sale en el toast.
// game.atasco('ultimo') devuelve el último atasco que hubo, con su `cuando`: el toast dura 4 s y la
// pregunta casi siempre llega después.
game.atasco=function(cual){
  if(cual==='ultimo' || cual==='último') return mc._stuckWhy || 'ningún atasco en esta sesión';
  if(!mc.active) return 'abre el Mundo primero';
  return mcStuckWhy(mc.pos[0], mc.pos[1], mc.pos[2]);
};
// game.toast("mensaje", segundos) = muestra un aviso efímero desde la consola, en CUALQUIER vista de la app
// (Capas, editor 3D o Mundo). El 2º argumento es opcional (duración en segundos; def. 1.8 s). En el Mundo el
// toast sube por encima de la hotbar automáticamente (clase mc-mode en toast()). game.showToast es alias.
game.toast=game.showToast=function(msg, secs){ toast(String(msg), secs); return 'ok'; };
// game.dumpVars() = vuelca a la consola los VALORES ACTUALES de los tunables de F12 (los que voy ajustando en vivo)
// como un objeto plano copiable — sin funciones ni prototipos: `game` a secas muestra los accesores como `(...)`/`ƒ`
// y no se leen. Sirve para pasártelos como nuevos valores por defecto. Lee cada getter (fuente única, ya redondeado
// como se muestra); showFPS/showVoxels se resuelven a su booleano (sus getters devuelven funciones invocables).
game.dumpVars=function(){
  const keys=['nearClip','perspStrength','playFill','playZoom','playLift',   // edición 3D / modo jugar
    'fov','renderDist','renderScale','mouseSpeed','yaw','pitch','hotbarHide','reach','crosshair',   // Mundo (WebGL)
    'ghostAlpha','structGhostAlpha','noteAlpha','noteSigns','noteText','noteTextDist','noteFont','noteWidth','structBias','structCull','playerSpeed','playerScale','playerTool',
    'airControl','airAccel','airCap','autoUnstick',
    'structTextures','structGreedy','useOldStructBuildCall','interiorDark','sunShade','shadowSize','glowLevel','glowFocus','worldSize',
    'agentSpeed','agentSaveMs'];
  const V={ showFPS:_showFPS, showVoxels:_showVox, showColors:_showColors, carasMarcadas:carasMarcar }; // callables → su booleano subyacente
  for(const k of keys) V[k]=game[k];
  try{ console.table(V); }catch(e){}
  console.log(JSON.stringify(V,null,2));                                      // copiable como literal
  return V;
};
function closeWorld(){
  mc.active=false; mc.keys={}; mc.heldBtn=-1; mcClearPreview();
  mcTouchShow(false);
  mcStuckShow(false);   // salir del Mundo atascado dejaba el cartel colgado sobre el editor
  mcPauseAgents();   // los agentes se pausan al salir al editor: retienen memoria y coords hasta reabrir el Mundo
  mcCloseNote(); { const nv=$('#mc-noteview'); if(nv) nv.hidden=true; }   // t1 · cierra el editor/visor de notas al salir
  mcFreeNoteTexts();   // los rótulos horneados de los carteles: al volver se re-hornean con el texto de entonces
  mcFreeRefl();        // REQ-ENV5 · libera el framebuffer de reflejo planar
  if(mc.grid){ clearTimeout(mcSaveT); mcSaveWorld(); }   // vuelca cualquier edición pendiente al salir
  if(document.pointerLockElement===mc.canvas) document.exitPointerLock();
  if(mc.raf){ cancelAnimationFrame(mc.raf); mc.raf=0; }
  $('#mc-modal').hidden=true;
  mcDestapaApp();   // REQ-EDIT1 · CONSTRUIR sale al editor sin recargar: la tapa no puede seguir puesta
  mcMarcaSync();
}
// La salida táctil. Es un `mc-tbtn` de `#mc-touch`, no el «✕ Cerrar» de la esquina (quitado en
// REQ-OSD1): en escritorio no existe, y aquí no hace falta guardarlo de nada porque su contenedor ya
// se enciende y se apaga con `mcTouchShow`.
if($('#mc-tsalir')) $('#mc-tsalir').onclick=closeWorld;
// REQ-INTRO2 · la marca «VOXELFORGE» del editor devuelve al Mundo en modo intro, sin recargar. Solo se
// ve pulsable cuando de verdad hay un mundo en memoria al que volver (si no, el editor a secas y la
// marca es lo que era: un rótulo).
function mcMarcaSync(){
  const m=$('#marca-inicio'); if(!m) return;
  const activa = !!mc.grid && !mc.active;
  m.classList.toggle('clicable', activa);
  m.title = activa ? 'Volver a la intro del mundo' : '';
}
if($('#marca-inicio')) $('#marca-inicio').onclick=()=>{ mcVolverAIntro(); };
$('#mc-picker-close').onclick=mcClosePicker;
$('#mc-picker-remove').onclick=mcRemoveSlot;
$('#mc-note-save').onclick=mcSaveNote;
$('#mc-note-del').onclick=mcDeleteNote;
if($('#mc-note-trace')) $('#mc-note-trace').onclick=mcShowTraceModal;
if($('#trace-close')) $('#trace-close').onclick=mcCloseTraceModal;
if($('#trace-copy')) $('#trace-copy').onclick=mcCopyTraceText;
$('#mc-note-cancel').onclick=mcCloseNote;
$('#mc-note-text').addEventListener('keydown',e=>{                    // Ctrl/⌘+Enter guarda (Esc lo cierra el handler del Mundo; los atajos del editor no aplican con el Mundo abierto)
  if(e.key==='Enter' && (e.ctrlKey||e.metaKey)){ e.preventDefault(); mcSaveNote(); }
});
window.addEventListener('resize',()=>{ if(mc.active) mcResize(); });

// --- F4 · entrada: pointer-lock para mirar + teclas mantenidas para WASD/salto ---
const MC_KEYS=['w','a','s','d',' ','shift'];
const MC_ACT_MS=140;   // periodo de repetición al mantener el botón (construir/romper continuo)
const mcUserKeys={};   // atajos de teclado definidos por el usuario vía game.onKey (tecla → función)
// Teclas que usa el motor y NO se pueden re-ligar (evita romper controles por accidente).
// ⚠️ Esta lista tiene que llevar TODA tecla que el handler de más abajo atienda ANTES de mirar
// `mcUserKeys`, o ligarla se acepta sin rechistar y luego no hace nada: la rama del motor sale antes
// con su `return`. La `f` faltaba desde REQ-FLY1 (pasó a ser volar) y era exactamente ese caso.
const MC_RESERVED=new Set([...MC_KEYS,'e','p','b','x','u','n','r','z','f','escape','1','2','3','4','5','6','7','8','9']);
// REQ-OSD4 · en una pantalla de menú (?osd=1) el clic PULSA el bloque, no captura la cámara: capturarla
// escondería el cursor y dejaría el menú inservible. Se trabaja aquí, en el 'click', y no en el
// 'mousedown' de más abajo, porque aquel exige tener el puntero capturado — que es justo lo que no hay.
$('#mc-canvas').addEventListener('click',e=>{
  if(mc.escaparate){ mcEscaparatePulsa(e.clientX, e.clientY); return; }
  mcLockPointer();
});
// El cursor avisa de lo que es pulsable. Solo en escaparate: fuera, es un raycast por movimiento de
// ratón que nadie ha pedido.
$('#mc-canvas').addEventListener('mousemove',e=>{
  if(!mc.escaparate) return;
  mc.canvas.style.cursor = mcNotaBajoPixel(e.clientX, e.clientY) ? 'pointer' : '';
});
// Marca cuándo se soltó el pointer-lock: así el mismo Esc que lo libera no cierra el Mundo (Esc de 2 pasos).
document.addEventListener('pointerlockchange',()=>{ if(mc.active && document.pointerLockElement!==mc.canvas){ mc.unlockedAt=performance.now(); mc.heldBtn=-1; mcClearPreview(); } });
document.addEventListener('mousemove',e=>{
  if(!mc.active || document.pointerLockElement!==mc.canvas) return;
  const gs=mc.sens/Math.sqrt(mc.scale);   // giro ∝ 1/√scale: un gigante mueve la cabezota despacio (mole/peso), coherente con marcha y salto; a escala 1 no cambia
  mc.yaw-=e.movementX*gs; mc.pitch-=e.movementY*gs;   // dcha=mirar dcha, abajo=mirar abajo (mc.sens ← game.mouseSpeed)
  mc.pitch=Math.max(-1.55,Math.min(1.55,mc.pitch));
  // Reemerge la hotbar si el jugador está PARADO y mueve el ratón (gesto de «volver a mirar el inventario»).
  if(mc.hbTarget===0 && Math.hypot(mc.vel[0],mc.vel[2])<0.6 && (Math.abs(e.movementX)+Math.abs(e.movementY))>1) mcRevealHotbar();
});
window.addEventListener('keydown',e=>{ if(!mc.active || !$('#mc-picker').hidden || !$('#mc-note').hidden || !$('#snip-modal').hidden || !$('#ag-modal').hidden || (e.target && e.target.matches && e.target.matches('input,select,textarea'))) return;   // selector/editor de nota/código/agentes abierto ⇒ no mover/seleccionar
  if(/^[1-9]$/.test(e.key)){ const i=+e.key-1;
    // Alt+número: abre el selector de esa ranura (sin Esc+clic derecho); si no, selecciona la ranura.
    if(i<mc.hotbar.length){ if(e.altKey) mcOpenPicker(i); else { mc.sel=i; mcSelectSlot(); } }
    e.preventDefault(); return; }
  const k=e.key.toLowerCase();
  if((e.ctrlKey||e.metaKey) && k==='c'){ mcCopySelection(); e.preventDefault(); return; }   // Ctrl+C: copia la selección (tool=select) al portapapeles compatible con el editor
  if((e.ctrlKey||e.metaKey) && k==='v'){ mcPasteWorld(); e.preventDefault(); return; }        // Ctrl+V: pega el portapapeles EN EL MAPA, apoyado en la cara apuntada (el Mundo no se cierra)
  if(k==='e' || k==='p'){                                                                                   // e = conmuta construir↔volumen · E = conmuta pintar→seleccionar→cuentagotas
    if(e.altKey){ mcOpenPickerHerramientas(); e.preventDefault(); return; }
    mcRotaHerramienta(e.shiftKey || e.key === 'E'); e.preventDefault(); return; }
  if(k==='b'){ const st=1.15; game.playerScale=mc.scale*(e.shiftKey?1/st:st); toast('Tamaño ×'+(+mc.scale.toFixed(2))); e.preventDefault(); return; }   // b = más grande («big») · B (mayús) = más pequeño (paso fino ×1.15)
  if(k==='x'){ mc.xray=!mc.xray; toast('Rayos-X: '+(mc.xray?'ON':'OFF')); e.preventDefault(); return; }    // modo depuración: ver el volumen de colisión
  if(k==='u'){ mcForceUnstick(); toast('Desatascado'); e.preventDefault(); return; }                       // U = sácame de aquí (sube sobre lo que estorbe; si no, al spawn)
  if(k==='n'){ mcOpenNote(); e.preventDefault(); return; }                                                  // N = anota el bloque apuntado (post-it)
  // REQ-FLY1 · la F pasa a ser VOLAR y la foto se va a Alt+F. El dueño lo pidió así porque volar es de
  // cada minuto y la foto de vez en cuando; el botón táctil 📷 sigue siendo la foto (en táctil no hay Alt).
  // La rama de Alt mira e.code (tecla FÍSICA) y no `k`, por lo mismo que Alt+C (app.js:3529): con Alt
  // pulsado, e.key llega compuesto en varios teclados (en Mac, Alt+F es 'ƒ') y la foto no se dispararía.
  if(e.altKey && e.code==='KeyF' && !e.ctrlKey && !e.metaKey){ mcFoto(); e.preventDefault(); return; }       // Alt+F = foto de lo que se ve (ficha quemada en la imagen) → data/fotos/ y galería en /fotos
  if(k==='f' && !e.altKey){
    toast('Vuelo: '+(mcSetVolar(!mc.volar)?'ON':'OFF')+' — Espacio sube, Shift baja');
    e.preventDefault(); return; }
  if(k==='v' && mc.tool==='box' && mc.boxStep===3){
    if(e.shiftKey || e.key==='V'){
      mc.boxGiro = (mc.boxGiro + 1) & 3;
      toast('Volumen giro: ' + (mc.boxGiro * 90) + '° (' + (mc.boxGiro + 1) + '/4)');
    } else {
      mc.boxCara = (mc.boxCara + 1) % 6;
      toast('Volumen cara: ' + MC_ORI_CARA[mc.boxCara] + ' (' + (mc.boxCara + 1) + '/6)');
    }
    mc._volCache = null;
    e.preventDefault(); return;
  }
  if(k==='r' && (mc.slotStruct[mc.sel] || mc.tool==='box')){                                                                       // coloca la estructura en cualquiera de sus 24 posturas (mantén clic derecho para ver la vista-previa; suelta = estampa así)
    // Dos pasos, que es como se piensa: primero QUÉ CARA queda arriba, y luego cómo está girada sobre ella.
    if(e.shiftKey){ mc.previewGiro=(mc.previewGiro+1)&3; toast('Giro: '+(mc.previewGiro*90)+'° sobre esa cara'); }   // Shift+R = los 4 giros dentro de la cara elegida
    else { mc.previewCara=(mc.previewCara+1)%6; toast('Cara arriba: '+MC_ORI_CARA[mc.previewCara]+' ('+(mc.previewCara+1)+'/6)'); }  // R = las 6 caras
    const rawKey = mc.slotStruct[mc.sel] || (mc.hotbar[mc.sel] && mc.blockKey ? mc.blockKey[mc.hotbar[mc.sel]] : null);
    if(rawKey) mcPrecargaGirada(rawKey, mcPreviewOri());   // la pieza girada es otro material (mcClaveConOri): que esté listo ANTES del clic
    e.preventDefault(); return; }
  if(k==='r' && mc.tool==='select' && mc.selBox){ mcRotateSelBox(); e.preventDefault(); return; }              // gira 90° (horizontal) los bloques de la caja seleccionada — p.ej. tras Ctrl+V pegar
  // S SOLO mientras se MANTIENE el clic derecho colocando una estructura: alterna pegado canto↔centrado (la
  // vista-previa se re-malla sola). Fuera de ese gesto, S sigue siendo andar hacia atrás (no lo tocamos). !e.repeat
  // evita que mantener S pulsado parpadee entre modos.
  if(k==='s' && !e.repeat && mc.heldBtn===2 && mc.slotStruct[mc.sel]){ mc.stampCenter=!mc.stampCenter; toast('Pegado: '+(mc.stampCenter?'centrado':'canto')); e.preventDefault(); return; }
  if(k==='z'){ if(e.shiftKey) mcRedo(); else mcUndo(); e.preventDefault(); return; }   // z = deshacer · Z (mayús) = rehacer (romper/poner/pintar/estampar/retirar)
  if(mcUserKeys[k]){ try{ mcUserKeys[k](e); }catch(err){ console.error('game.onKey("'+k+'"):', err); } e.preventDefault(); return; }   // atajos del usuario (game.onKey)
  if(e.key==='Control' && !e.repeat && mc.tool==='box' && mc.boxStep===3 && !mc.boxCtrlHeld){
    mc.boxCtrlHeld = true;
    const near = mcRaycast(mcReach(), true);
    if(near && near.cell[1] >= 0){
      const n = near.normal;
      mc.boxCtrlFreeze = [near.cell[0] + n[0], near.cell[1] + n[1], near.cell[2] + n[2]];
    } else {
      mc.boxCtrlFreeze = mc.pos.map(Math.floor);
    }
    mc.boxAnchorHover = (mc.boxAnchor ? mc.boxAnchor.slice() : [0, 0, 0]);
    toast('Ajustando agarre: apunta al bloque del volumen · Suelta Control para fijar');
  }
  if(MC_KEYS.includes(k)){
    mc.keys[k]=true; if(k!=='shift') e.preventDefault();
    // Si el ratón no está capturado, moverse con WASD/salto lo captura (como un clic) — keydown es gesto de usuario.
    if(document.pointerLockElement!==mc.canvas){ mcLockPointer(); }
  }
});
window.addEventListener('keyup',e=>{
  if(!mc.active || !$('#snip-modal').hidden || !$('#ag-modal').hidden) return;
  const k = e.key.toLowerCase();
  mc.keys[k]=false;
  if(e.key==='Control' && mc.tool==='box' && mc.boxCtrlHeld){
    mc.boxCtrlHeld = false;
    if(mc.boxAnchorHover) mc.boxAnchor = mc.boxAnchorHover.slice();
    mc.boxCtrlFreeze = null;
    const [ax, ay, az] = mc.boxAnchor || [0, 0, 0];
    toast('Punto de agarre fijado en [' + ax + ', ' + ay + ', ' + az + ']');
  }
});

// --- F4b · controles táctiles: sin teclado no se puede andar por el Mundo ---
// Una pantalla táctil no tiene ni pointer-lock ni WASD, así que desde un móvil el Mundo se veía pero
// era literalmente inmóvil: no había forma de dar un paso.
//
// NO se toca la física ni mcUpdate. El joystick escribe en mc.keys las MISMAS teclas que escribiría
// un teclado (8 direcciones) y el arrastre mueve mc.yaw/mc.pitch con la misma cuenta que el ratón.
// Así todo lo que depende del movimiento —colisión, agentes que te persiguen, la hotbar que se hunde
// al correr— sigue funcionando igual sin enterarse de que no hay teclado.
//
// A propósito NO hay botones de romper/poner: un toque de más sería una edición de verdad, con su
// autoguardado en mundo.json. Mirar y andar no escriben nada, y lo que faltaba era andar.
const MC_TOUCH=matchMedia('(pointer:coarse)').matches || navigator.maxTouchPoints>0;
const MC_LOOK_BASE=0.006;      // rad/px del arrastre; el ratón usa 0.000625, que en un dedo sería nada
// El recorrido del pulgar sale del ANCHO REAL del aro, no de una constante: el CSS encoge el
// joystick en apaisado (@media max-height) y con un número fijo el pomo se saldría del dibujo y la
// zona muerta dejaría de coincidir. 0.39 reproduce los 46 px de siempre en el aro de 118.
const MC_STICK_F=0.39;         // recorrido = ancho del aro × esto
let mcLookSens=MC_LOOK_BASE, mcStickId=-1, mcLookId=-1, mcJumpId=-1, mcLookX=0, mcLookY=0;
try{ const s=parseFloat(localStorage.getItem('vf_mcTouchLook')); if(isFinite(s)&&s>0) mcLookSens=MC_LOOK_BASE*s; }catch(e){}
// game.touchLook = múltiplo de la sensibilidad del arrastre (1 = normal), como game.mouseSpeed.
Object.defineProperty(game,'touchLook',{ enumerable:true, get:()=>+(mcLookSens/MC_LOOK_BASE).toFixed(2),
  set:v=>{ v=Math.max(0.1,Math.min(10,+v||1)); mcLookSens=MC_LOOK_BASE*v; try{localStorage.setItem('vf_mcTouchLook',v);}catch(e){} return v; } });
// game.touchControls = enseñar los mandos aunque haya ratón (o esconderlos en un portátil táctil).
let mcTouchOn=MC_TOUCH;
try{ const t=localStorage.getItem('vf_mcTouch'); if(t==='0'||t==='1') mcTouchOn=(t==='1'); }catch(e){}
Object.defineProperty(game,'touchControls',{ enumerable:true, get:()=>mcTouchOn,
  set:v=>{ mcTouchOn=!!v; try{localStorage.setItem('vf_mcTouch',mcTouchOn?'1':'0');}catch(e){} mcTouchShow(mc.active);
           // Ya no hay `updateOSDbuttons` que llamar (REQ-OSD1): la salida táctil está DENTRO de
           // `#mc-touch`, así que `mcTouchShow` la trae y se la lleva con el resto de los mandos.
           return mcTouchOn; } });

function mcTouchShow(on){ const z=$('#mc-touch'); if(z) z.hidden=!(on && mcTouchOn); if(!on) mcStickSuelta(); }
function mcStickSuelta(){    // el pulgar levantado deja de andar: si no, te quedas caminando solo
  mcStickId=-1; mc.keys['w']=mc.keys['a']=mc.keys['s']=mc.keys['d']=false;
  const k=$('#mc-stick-knob'); if(k) k.style.transform='translate(-50%,-50%)';
}
{
  const base=$('#mc-stick'), knob=$('#mc-stick-knob'), salto=$('#mc-tjump');
  const mueve=e=>{
    const r=base.getBoundingClientRect();
    const dx=e.clientX-(r.left+r.width/2), dy=e.clientY-(r.top+r.height/2), len=Math.hypot(dx,dy);
    const R=r.width*MC_STICK_F;                    // el aro puede encoger (apaisado): se mide, no se supone
    const k=len>R ? R/len : 1;                     // el pomo no se sale de su aro, el dedo sí puede
    knob.style.transform='translate(calc(-50% + '+(dx*k).toFixed(1)+'px), calc(-50% + '+(dy*k).toFixed(1)+'px))';
    // Zona muerta: sin ella, el propio peso del pulgar apoyado en el centro ya te hace andar.
    if(len<R*0.3){ mc.keys['w']=mc.keys['a']=mc.keys['s']=mc.keys['d']=false; return; }
    const nx=dx/len, ny=-dy/len;                   // en pantalla +y es ABAJO; ny>0 = hacia delante
    // 0.38 ≈ cos(67,5°): cada sector de 45° enciende una tecla o dos, exactamente como un teclado.
    mc.keys['w']=ny>0.38; mc.keys['s']=ny<-0.38; mc.keys['d']=nx>0.38; mc.keys['a']=nx<-0.38;
  };
  base.addEventListener('pointerdown',e=>{ if(!mc.active) return;
    mcStickId=e.pointerId; try{ base.setPointerCapture(e.pointerId); }catch(err){} mueve(e); e.preventDefault(); });
  base.addEventListener('pointermove',e=>{ if(e.pointerId===mcStickId) mueve(e); });

  salto.addEventListener('pointerdown',e=>{ if(!mc.active) return;
    mcJumpId=e.pointerId; mc.keys[' ']=true; try{ salto.setPointerCapture(e.pointerId); }catch(err){} e.preventDefault(); });

  // La foto se dispara en pointerUP y no en down como el salto: un botón que dispara al tocarlo se
  // activa al rozarlo mientras se busca el pulgar, y esto escribe un fichero. Nada de estado que
  // soltar, así que mcTouchSuelta no tiene que saber de él.
  const foto=$('#mc-tfoto');
  if(foto) foto.addEventListener('pointerup',e=>{ if(!mc.active) return; mcFoto(); e.preventDefault(); });
  // Desatasco (BUG-AG7). Va aquí con los demás mandos pero NO dentro de #mc-touch: en el escritorio
  // también hace falta. También en pointerup, por lo mismo que la foto. Lo esconde el propio mcUpdate
  // en cuanto quedas libre; no hace falta apagarlo a mano.
  const stuck=$('#mc-stuck');
  if(stuck) stuck.addEventListener('pointerup',e=>{ if(!mc.active) return; mcForceUnstick(); toast('Desatascado'); e.preventDefault(); });
}
// ⚠️ LOS FINALES SE ESCUCHAN EN WINDOW, NO EN CADA MANDO. Un `pointerup` perdido deja el estado
// pegado, y los dos síntomas salen a la vez: te quedas ANDANDO SOLO (la tecla del joystick no se
// apaga) y la cámara MUERTA (mcLookId se queda con el id de un dedo que ya no existe, y el
// `if(mcLookId>=0) return` de abajo rechaza todos los dedos siguientes para siempre).
// Se pierde más de lo que parece: si el dedo se sale del aro del joystick y setPointerCapture no
// prendió, el `up` cae sobre el canvas; si el navegador se queda el gesto, llega un `pointercancel`
// en otro sitio; y si te llaman por teléfono, no llega nada. En window (fase de captura) llegan
// todos, y lo que no llega lo barre el blur/visibilitychange.
function mcTouchSuelta(id){          // un dedo concreto, o TODOS si no se pasa ninguno
  if(id===undefined || id===mcStickId) mcStickSuelta();
  if(id===undefined || id===mcLookId) mcLookId=-1;
  if(id===undefined || id===mcJumpId){ mcJumpId=-1; if(mc.keys) mc.keys[' ']=false; }
}
addEventListener('pointerup',e=>mcTouchSuelta(e.pointerId),true);
addEventListener('pointercancel',e=>mcTouchSuelta(e.pointerId),true);
addEventListener('blur',()=>mcTouchSuelta());
document.addEventListener('visibilitychange',()=>{ if(document.hidden) mcTouchSuelta(); });

// Mirar = arrastrar por el canvas. Solo dedos: el ratón ya tiene su pointer-lock, y atender a los dos
// haría que un ratón girase el doble.
// Manda el dedo MÁS NUEVO. Antes el primero se quedaba el turno, y bastaba un id colgado para no
// poder volver a girar la cámara en toda la sesión; así, cualquier toque nuevo rearma el control.
$('#mc-canvas').addEventListener('pointerdown',e=>{
  if(!mc.active || e.pointerType==='mouse') return;
  mcLookId=e.pointerId; mcLookX=e.clientX; mcLookY=e.clientY;
  try{ mc.canvas.setPointerCapture(e.pointerId); }catch(err){}
});
$('#mc-canvas').addEventListener('pointermove',e=>{
  if(e.pointerId!==mcLookId) return;
  const gs=mcLookSens/Math.sqrt(mc.scale);   // igual que el ratón: un gigante gira la cabezota despacio
  mc.yaw-=(e.clientX-mcLookX)*gs; mc.pitch-=(e.clientY-mcLookY)*gs;
  mc.pitch=Math.max(-1.55,Math.min(1.55,mc.pitch));
  mcLookX=e.clientX; mcLookY=e.clientY;
  e.preventDefault();
});
// (el final del arrastre lo suelta mcTouchSuelta desde window: aquí no hace falta nada)

// game.onKey('t', fn) · liga una tecla a tu función mientras el Mundo (🌍) esté activo. Ejemplo:
//   game.onKey('t', ()=> throwAndExplodeTNT(...game.aim(), {radius:8, fuseTimeMs:500, tntMat:'roca'}));
// Re-registrar la misma tecla la REEMPLAZA (no acumula listeners); game.onKey('t', null) la quita.
// Las teclas del motor (WASD, espacio, shift, 1-9, p/b/x/u/n/r/z, Esc) están reservadas. game.keys() lista las tuyas.
game.onKey=function(tecla, fn){
  const k=String(tecla==null?'':tecla).toLowerCase();
  if(k.length!==1 && k!=='escape'){ console.warn('game.onKey: indica UNA tecla, p.ej. game.onKey("t", fn)'); return; }
  if(fn==null){ delete mcUserKeys[k]; return k; }                 // quitar
  if(typeof fn!=='function'){ console.warn('game.onKey: el 2º argumento debe ser una función (o null para quitar)'); return; }
  if(MC_RESERVED.has(k)){ console.warn('game.onKey: la tecla "'+k+'" la usa el Mundo; elige una libre (t,g,h,j,k,l,y,c,v,m,q,e…)'); return; }
  mcUserKeys[k]=fn; return k;
};
// game.keys() · lista las teclas que has ligado con game.onKey
game.keys=function(){ const ks=Object.keys(mcUserKeys); console.log(ks.length?('teclas ligadas: '+ks.join(', ')):'sin teclas ligadas (game.onKey)'); return ks; };

// game.snippet('mi-menu', opts) · corre OTRO snippet desde el tuyo. El argumento es el ID del documento (el de
// la URL /api/snippets/<id>), no el nombre bonito del panel Código. Los argumentos opcionales que pases detrás
// se entregan al snippet como variables `opts` (el primero) y `args` (o arguments). Devuelve lo que el invitado retorne,
// así que también vale de librería: `const util = await game.snippet('mis-utiles');` con un `return {…}`
// al final del otro. Es await-able sin envolver nada porque un snippet ya es el cuerpo de un AsyncFunction.
// Va por mcCorreSnippet y NO por eval a propósito: así lo que el invitado registre —una acción de OSD, un
// comportamiento de bloque— sigue sabiendo de qué documento salió (`mc._snippetActual`), que es lo único
// que contesta «¿y esto dónde lo cambio?» cuando el código no está en ningún fichero del repo.
// No hay guardia contra ciclos: si A llama a B y B a A, se cuelga la pestaña.
game.snippet=async function(id, ...args){
  const s=await mcPideSnippet(String(id==null?'':id).trim());
  if(!s || !s.code) throw new Error('game.snippet("'+id+'"): no existe ese snippet (el argumento es el ID, mira el panel Código)');
  return mcCorreSnippet(s.id||id, s.code, ...args);
};

// ─────────────────────────────────────────────────────────────────────────────────────────────────────────
// AGENTES (NPC) del Mundo · game.defineAgent
// ─────────────────────────────────────────────────────────────────────────────────────────────────────────
// Reparto de responsabilidades: AQUÍ va la MECÁNICA (tick, andar, pintar, notas, telemetría, dibujo); la
// HEURÍSTICA (a dónde girar, cómo evitar la propia cola, cuándo terminar, qué anotar) va en tu snippet, en
// onTick(a). El framework nunca decide política.
//   game.defineAgent({ id:'pintor', block:'sand', tickMs:120, onTick(a){ a.walk(1,0); a.paint('grass'); } })
// Redefinir un id existente DETIENE el viejo y lo reemplaza (iterar la heurística sin recargar la página).
// Inspección en F12: game.agents() · game.agent('pintor').vars / .stats · game.stopAgents().
const MC_AGENT_MAX_STEPS=4;      // pasos por agente y frame a velocidad normal (para tickMs < duración de frame)
const MC_AGENT_FRAME_MS=8;       // presupuesto de CPU por frame para TODOS los agentes (medio frame a 60 fps).
                                 // game.agentSpeed no tiene tope, así que el freno real no puede ser un número
                                 // de pasos sino TIEMPO: sin esto, agentSpeed=1000 congela la pestaña en vez de
                                 // ir más rápido. Con esto los agentes corren lo que quepa y el Mundo sigue vivo.
const MC_AGENT_SAVE_MS=30000;    // cada cuánto se vuelca el mundo mientras hay agentes escribiendo
let mcAgentSpeed=1;              // game.agentSpeed: multiplicador de VELOCIDAD (2 = el doble de rápido); divide tickMs
let mcAgentSaveMs=MC_AGENT_SAVE_MS;
const mcAgentDirty=new Set();    // chunks "cx,cz" pendientes de re-mallar por escrituras de agentes
let mcAgentSaveDirty=false, mcAgentSaveAt=0;

// Escritura BARATA para agentes. mcSetVoxel/mcFlushBuild no valen en un bucle continuo: hacen mcMeshAll()
// completo, mcUnstick, guardado y un toast cada 80ms. Aquí: mc.grid + marcar el chunk, y remallar UNA vez por
// frame. La luz solo cambia si se rompe el invariante sólido↔aire (mcComputeLight difunde por aire) → sólido↔
// sólido (pintar) puede saltarse el BFS; aire↔sólido cae al camino caro. Y desde que la rejilla también puede
// llevar emisores (mcGlowCeldas), pintar una antorcha ENCIMA de piedra —o taparla— tampoco puede saltárselo.
function mcAgentSetBlock(x,y,z,id){
  if(!mc.grid || !mcInside(x,y,z)) return false;
  const i=mcIdx(x,y,z), prev=mc.grid[i];
  if(prev===id) return false;
  const glowAntes=!!(mc._glowCeldas && mc._glowCeldas.has(i));
  mc.grid[i]=id; mcDirty(x,y,z); mcGlowTocada(x,y,z);
  mcAgentSaveDirty=true;
  const glowDespues=!!(mc._glowCeldas && mc._glowCeldas.has(i));
  if(prev===0 || id===0 || glowAntes!==glowDespues) mcRemeshAround(x,z);   // cambia la luz: recomputar + re-mallar 3×3 (raro: los agentes pintan)
  else mcAgentDirty.add(Math.floor(x/MC_CHUNK)+','+Math.floor(z/MC_CHUNK));
  return true;
}
function mcAgentFlushDirty(){
  if(!mcAgentDirty.size) return;
  for(const k of mcAgentDirty){ const p=k.split(','); mcMeshChunk(+p[0], +p[1]); }
  mcAgentDirty.clear();
}
// Guardado espaciado: mcSaveWorld POSTea el mundo ENTERO, así que un agente que corre minutos no puede usar
// el debounce normal de 900ms. Se vuelca cada mcAgentSaveMs y siempre al parar/fallar/cerrar.
function mcAgentMaybeSave(now){
  if(!mcAgentSaveDirty) return;
  if(!mcAgentSaveAt){ mcAgentSaveAt=now; return; }
  if(now-mcAgentSaveAt<mcAgentSaveMs) return;
  mcAgentSaveAt=now; mcAgentSaveDirty=false;
  clearTimeout(mcSaveT); mcSaveWorld();
}
function mcAgentFlushSave(){ if(!mcAgentSaveDirty) return; mcAgentSaveDirty=false; mcAgentSaveAt=0; mcScheduleSave(); }

// Suelo: bloque sólido más alto de la columna (−1 si la columna está vacía).
function mcSurfaceY(x,z){
  if(!mc.grid || !mcInside(x,0,z)) return -1;
  for(let y=mc.dim.y-1;y>=0;y--) if(mc.grid[mcIdx(x,y,z)]) return y;
  return -1;
}
// Suelo PISABLE cerca de la altura actual: sólido con aire encima, a ±climb de y0. Evita escanear la columna
// entera en cada paso (mcSurfaceY es O(alto) y se llamaría 4 veces por tick y agente).
function mcSurfaceNear(x,z,y0,climb,drop){
  if(!mc.grid || !mcInside(x,0,z)) return -1;
  const H=mc.dim.y;
  const maxUp = climb !== undefined ? climb : 1;
  const maxDown = drop !== undefined ? drop : 3;
  const maxD = Math.max(maxUp, maxDown);
  for(let d=0; d<=maxD; d++){
    const candidates = [];
    if(d <= maxUp) candidates.push(y0 + d);
    if(d > 0 && d <= maxDown) candidates.push(y0 - d);
    for(const y of candidates){
      if(y<0||y>=H) continue;
      if(mc.grid[mcIdx(x,y,z)] && (y+1>=H || !mc.grid[mcIdx(x,y+1,z)])) return y;
    }
  }
  return -1;
}

// Cuerpo del agente: cubo suelto de 36 vértices con el formato del terreno (x,y,z,u,v,shade) y su atlas.
// Va en un VBO propio y NO en mc.grid: en la rejilla el jugador colisionaría con los agentes, ensuciaría el
// mundo guardado y obligaría a re-mallar dos chunks por paso. Siempre a pleno brillo (se ve en salas oscuras).
const MC_AGENT_INSET_XZ=0.02;     // ligero inset en X y Z para no hacer z-fighting con paredes adyacentes
const MC_AGENT_INSET_Y=0.001;     // asentamiento de la cara inferior totalmente pegado a la cota del suelo
function mcAgentMesh(a){
  const gl=mc.gl; if(!gl) return;
  let rects=mc.palette[a.blockId];
  if(!rects && mc.palette.length > 1){ a.blockId = 1; rects = mc.palette[1]; }
  if(!rects){ a.count=0; return; }
  const rx = a.renderX !== undefined ? a.renderX : a.x;
  const ry = a.renderY !== undefined ? a.renderY : a.y;
  const rz = a.renderZ !== undefined ? a.renderZ : a.z;
  // mcAgentsSmoothUpdate llama aquí en CADA frame de CADA agente, se haya movido o no. Si los vértices van a
  // salir idénticos no hay nada que subir a la GPU... ni sombra que rehacer: sin esta guarda, un solo agente
  // quieto obligaba a redibujar el mapa de sombra entero 60 veces por segundo.
  const sig = rx+'|'+ry+'|'+rz+'|'+a.blockId;
  if(a._meshSig===sig && a.count) return;
  a._meshSig=sig;
  const Sx=1-2*MC_AGENT_INSET_XZ, Sy=1-2*MC_AGENT_INSET_Y, Sz=1-2*MC_AGENT_INSET_XZ;
  const ox=rx+MC_AGENT_INSET_XZ, oy=ry+1+MC_AGENT_INSET_Y, oz=rz+MC_AGENT_INSET_XZ;
  const verts=[];
  for(let f=0;f<6;f++){
    const F=MC_FACES[f], r=rects[F.tex], C=F.corners;
    const uv=[[r.u0,r.v0],[r.u1,r.v0],[r.u1,r.v1],[r.u0,r.v1]];
    for(const k of [0,1,2,0,2,3]){
      const c=C[k];
      verts.push(ox+c[0]*Sx, oy+c[1]*Sy, oz+c[2]*Sz, uv[k][0], uv[k][1], F.s);
    }
  }
  if(!a.vbo) a.vbo=gl.createBuffer();
  gl.bindBuffer(gl.ARRAY_BUFFER, a.vbo);
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(verts), gl.DYNAMIC_DRAW);
  a.count=36;
  mcShadowMoved();   // el agente se movió → su sombra también (esta es TODA la integración que necesita), pero sin
                     // prisa: un cuerpo que APARECE o cambia de nº de vértices sí entra ya, vía la firma de geometría
}
function mcAgentFreeMesh(a){ if(a.vbo && mc.gl) mc.gl.deleteBuffer(a.vbo); a.vbo=null; a.count=0; mcShadowDirty(); }

// Notas: REUTILIZAN los post-it del Mundo (mc.notes), así que se serializan en el JSON del mundo y se pueden
// leer/procesar desde FUERA del juego para mejorar las heurísticas. Formato compacto «[id] texto».
function mcAgentNoteForce(a, texto, celda){
  const txt=('['+a.id+'] '+String(texto)).slice(0, MC_NOTE_MAX);
  const c = celda ? [Math.round(celda[0]),Math.round(celda[1]),Math.round(celda[2])] : [a.x, a.y, a.z];
  let k=mcNoteKey(c);
  for(let r=1; r<=3 && mc.notes[k]; r++){          // espiral hacia fuera: no pisar una nota que ya existe
    let libre=null;
    for(let dz=-r; dz<=r && !libre; dz++) for(let dx=-r; dx<=r && !libre; dx++){
      if(Math.max(Math.abs(dx),Math.abs(dz))!==r) continue;
      const nx=c[0]+dx, nz=c[2]+dz, ny=mcSurfaceY(nx,nz);
      if(ny<0) continue;
      const nk=nx+','+ny+','+nz; if(!mc.notes[nk]) libre=nk;
    }
    if(libre){ k=libre; break; }
  }
  if(mc.notes[k]){                                  // sin hueco alrededor: acumula en la existente (o la sustituye si no cabe)
    const j=mc.notes[k]+' | '+txt;
    mc.notes[k] = j.length<=MC_NOTE_MAX ? j : txt;
  } else mc.notes[k]=txt;
  a.stats.notes++; a._noteAt=performance.now(); mcAgentSaveDirty=true; mcDirtyHeader();
  return true;
}
function mcAgentNote(a, texto, celda){              // con cuota antiinundación (noteMax / noteMinMs)
  const now=performance.now();
  const urgente = a.state==='stopped' || a.state==='error';   // el informe final nunca se pierde por cadencia
  if(a.stats.notes>=a.noteMax || (!urgente && a._noteAt && now-a._noteAt<a.noteMinMs)){ a.stats.notesDropped++; return false; }
  return mcAgentNoteForce(a, texto, celda);
}

// Una heurística rota NUNCA puede matar el bucle del Mundo: se aísla el agente, se deja rastro y se sigue.
function mcAgentFail(a, err, donde){
  a.state='error';
  const msg = (err && err.message) ? err.message : String(err);
  console.error('[agente '+a.id+'] '+(donde||'onTick')+': '+msg);
  mcAgentNoteForce(a, 'ERROR '+msg);   // la nota de error se salta la cuota
  toast('Agente '+a.id+': error (ver consola F12)');
  try{ if(a.cfg.onError) a.cfg.onError(a, err); }catch(e2){ console.error('[agente '+a.id+'] onError: '+(e2&&e2.message?e2.message:e2)); }
  mcAgentFlushDirty(); mcAgentFlushSave();
}

// Celda destino de un paso: devuelve la Y de suelo pisable, o −1 si no se puede ir (borde, abismo, desnivel).
function mcAgentTarget(a, dx, dz){
  dx=dx|0; dz=dz|0;
  const nx=a.x+dx, nz=a.z+dz, m=a.margin;
  if(nx<m || nz<m || nx>=mc.dim.x-m || nz>=mc.dim.z-m) return -1;
  return mcSurfaceNear(nx, nz, a.y, a.climb, a.drop);
}

function mcAgentMake(id, cfg){
  const num=(v,d)=>isFinite(+v)?+v:d;
  // Posición inicial: la que pidas, o dos celdas por delante del jugador (así «invocar un agente» funciona en
  // CUALQUIER mapa, sin depender de uno dedicado).
  let sx, sz;
  if(cfg.start && isFinite(+cfg.start.x) && isFinite(+cfg.start.z)){ sx=Math.round(+cfg.start.x); sz=Math.round(+cfg.start.z); }
  else { sx=Math.floor(mc.pos[0]-Math.sin(mc.yaw)*2); sz=Math.floor(mc.pos[2]-Math.cos(mc.yaw)*2); }
  sx=Math.max(1, Math.min(mc.dim.x-2, sx)); sz=Math.max(1, Math.min(mc.dim.z-2, sz));
  const a={
    id, cfg,
    name: String(cfg.name||id),
    goal: String(cfg.goal||''),
    block: cfg.block==null ? 'stone' : cfg.block,
    blockId: 0,
    x:sx, y:Math.max(0, mcSurfaceY(sx,sz)), z:sz, dir:[1,0],
    vars: (cfg.vars && typeof cfg.vars==='object') ? cfg.vars : {},   // estado libre del snippet: el framework NO lo toca
    state:'idle',
    tickMs: Math.max(16, num(cfg.tickMs,120)),
    climb: Math.max(0, num(cfg.climb,1)|0),
    drop: Math.max(0, num(cfg.drop,3)|0),
    margin: Math.max(0, num(cfg.margin,1)|0),
    maxTicks: Math.max(0, num(cfg.maxTicks,0)|0),
    noteMax: Math.max(0, num(cfg.noteMax,20)|0),
    noteMinMs: Math.max(0, num(cfg.noteMinMs,3000)),
    debug: !!cfg.debug,
    stats:{ ticks:0, steps:0, painted:0, repainted:0, blocked:0, idleTicks:0, distance:0,
            notes:0, notesDropped:0, startedAt:0, lastMoveAt:0, elapsedMs:0 },
    vbo:null, count:0, _nextAt:0, _noteAt:0, _moved:false, _mat:{},
  };
  a.passengers = cfg.passengers !== false && cfg.rideable !== false;
  a.isMounted = function(){
    if(a._dismountedAt && (performance.now() - a._dismountedAt < 2500)) return false;
    const p = mc.pos;
    const rx = a.renderX !== undefined ? a.renderX : a.x;
    const ry = a.renderY !== undefined ? a.renderY : a.y;
    const rz = a.renderZ !== undefined ? a.renderZ : a.z;
    // Si el jugador está apoyado sobre un bloque sólido del mundo (suelo/arena/hormigón), NO está montado en el agente
    const px = Math.floor(p[0]), py = Math.floor(p[1]), pz = Math.floor(p[2]);
    if(typeof mcGetVoxel === 'function' && mcGetVoxel(px, py - 1, pz) > 0) return false;
    // COTAS (no tocar sin releer esto): a.y/renderY = celda de SUELO SÓLIDA bajo el agente; el cuerpo se dibuja
    // en ry+1 (mcAgentMesh: oy=ry+1) y mcCollides le da un AABB en [ry+1, ry+2). Por tanto, quien va de paseo
    // encima tiene los PIES en ry+2, no en ry+1: la ventana antigua (ry+0.95..ry+1.25) caía DENTRO del propio
    // cuerpo del agente, una cota inaccesible, así que isMounted() no devolvía true jamás y nunca te llevaba.
    return (p[0] >= rx + 0.1 && p[0] <= rx + 0.9 &&
            p[2] >= rz + 0.1 && p[2] <= rz + 0.9 &&
            p[1] >= ry + 1.9 && p[1] <= ry + 2.5);
  };
  // OJO: a.blockId NO se resuelve aquí. onStart puede precargar la textura del cuerpo con game.addMaterial
  // (p.ej. obsidiana, que no está en la paleta por defecto); resolverlo antes poblaría la caché de
  // mcResolveMat con el fallback a roca. Se resuelve en start(), después de onStart.
  // ── Skills (mecánica). La política —girar, evitar la cola, terminar— la pone tu onTick. ──
  a.matId=function(mat){ const k=String(mat); if(a._mat[k]===undefined) a._mat[k]=mcResolveMat(mat); return a._mat[k]; };
  a.canWalk=function(dx,dz){ return mcAgentTarget(a,dx,dz)>=0; };
  a.walk=function(dx,dz){
    const ny=mcAgentTarget(a,dx,dz);
    if(ny<0){ a.stats.blocked++; return false; }
    if(a.renderX === undefined){ a.renderX = a.x; a.renderY = a.y; a.renderZ = a.z; }
    a.x+=dx|0; a.z+=dz|0; a.y=ny;
    if(dx||dz) a.dir=[Math.sign(dx|0), Math.sign(dz|0)];
    a.stats.steps++; a.stats.distance+=Math.abs(dx|0)+Math.abs(dz|0); a.stats.lastMoveAt=performance.now();
    a._moved=true; mcAgentMesh(a);
    return true;
  };
  a.surfaceY=function(x,z){ return mcSurfaceY(Math.round(x), Math.round(z)); };
  a.getBlock=function(x,y,z){ const px=(x===undefined?a.x:Math.round(x)), py=(y===undefined?a.y:Math.round(y)), pz=(z===undefined?a.z:Math.round(z)); return mcGetVoxel(px,py,pz); };
  a.floor=function(x,z){                        // id del bloque de suelo (0 = aire/nada) en (x,z) o bajo el agente
    const px=(x===undefined?a.x:Math.round(x)), pz=(z===undefined?a.z:Math.round(z));
    const py=(px===a.x&&pz===a.z)?a.y:mcSurfaceY(px,pz);
    return py<0 ? 0 : mc.grid[mcIdx(px,py,pz)];
  };
  a.paint=function(mat, x, z){                  // devuelve true SOLO si cambió algo (repintar cuenta aparte)
    if(x!==undefined || z!==undefined){
      const px=Math.round(x), pz=Math.round(z), py=mcSurfaceY(px,pz);
      if(py<0) return false;
      const id=a.matId(mat); if(!id) return false;
      const prev=mc.grid[mcIdx(px,py,pz)];
      if(!prev) return false;
      if(prev===id){ a.stats.repainted++; return false; }
      mcAgentSetBlock(px,py,pz,id); a.stats.painted++; return true;
    }
    const id=a.matId(mat); if(!id) return false;
    a._pendingPaint = { matId: id, targetX: a.x, targetY: a.y, targetZ: a.z };
    return true;
  };
  a.setBlock=function(x,y,z,mat){ return mcAgentSetBlock(Math.round(x),Math.round(y),Math.round(z), a.matId(mat)); };
  a.agentsAt=function(x,z){                     // otros agentes en esa celda (evitarse entre ellos es política tuya)
    const px=Math.round(x), pz=Math.round(z), out=[];
    for(const o of mc.agents.values()) if(o!==a && o.x===px && o.z===pz) out.push(o.id);
    return out;
  };
  a.note=function(texto, celda){ return mcAgentNote(a, texto, celda); };
  a.getNote=function(x,y,z){
    const px=(x===undefined?a.x:Math.round(x)), py=(y===undefined?a.y:Math.round(y)), pz=(z===undefined?a.z:Math.round(z));
    return (mc.notes && mc.notes[px+','+py+','+pz]) || '';
  };
  a.rnd=function(n){ return n==null ? Math.random() : Math.floor(Math.random()*n); };
  a.log=function(){ console.log('[agente '+a.id+']', a.state, 'pos', a.x+','+a.y+','+a.z, a.stats, a.vars); return a; };
  // ── Ciclo de vida ──
  a.start=function(){
    if(a.state==='running') return a;
    a.state='running'; a._nextAt=0;
    if(!a.stats.startedAt) a.stats.startedAt=performance.now();
    let p=null;
    try{ if(a.cfg.onStart) p=a.cfg.onStart(a); }catch(err){ mcAgentFail(a, err, 'onStart'); return a; }
    // onStart puede ser ASÍNCRONO (típico: `await game.addMaterial('asset:…')` para precargar la textura del
    // cuerpo). Si devuelve una promesa, el cuerpo se malla al resolverse —ya con el material bueno— y hasta
    // entonces el agente no da su primer paso (_nextAt=Infinity lo deja fuera del planificador).
    const listo=()=>{ a._mat={}; a.blockId=mcResolveMat(a.block); mcAgentMesh(a); };
    if(p && typeof p.then==='function'){ a._nextAt=Infinity; p.then(()=>{ listo(); a._nextAt=0; }, err=>mcAgentFail(a, err, 'onStart')); }
    else listo();
    return a;
  };
  a.pause=function(){ if(a.state==='running'){ a.state='paused'; mcAgentFlushDirty(); mcAgentFlushSave(); } return a; };
  a.resume=function(){ if(a.state==='paused'){ a.state='running'; a._nextAt=0; } return a; };
  a.stop=function(motivo){
    if(a.state==='stopped') return a;
    a.state='stopped';
    try{ if(a.cfg.onStop) a.cfg.onStop(a, motivo||'stop'); }catch(err){ console.error('[agente '+a.id+'] onStop:', err); }
    mcAgentFlushDirty(); mcAgentFlushSave();
    return a;
  };
  a.step=function(){ mcAgentStep(a); return a; };   // un tick manual desde consola, para depurar la heurística
  return a;
}

function mcAgentStep(a){
  a.stats.ticks++;
  a._moved=false;
  try{ a.cfg.onTick(a); }
  catch(err){ mcAgentFail(a, err); return; }
  if(!a._moved) a.stats.idleTicks++;
  a.stats.elapsedMs=performance.now()-(a.stats.startedAt||performance.now());
  if(a.maxTicks>0 && a.stats.ticks>=a.maxTicks && a.state==='running') a.stop('maxTicks');
}

// Reparto justo del presupuesto de frame. El primero del Map se comía los 8 ms enteros y `agotado`
// saltaba a TODOS los demás — y como el orden del Map es fijo, los mismos agentes se quedaban sin CPU
// para siempre: medido, a game.agentSpeed=10 se quedaban a cero 4 de 6, y a 100, 5 de 6. Dos frenos:
// se empieza la vuelta por quien se quedó sin turno, y ningún agente puede pasarse de su rodaja.
let mcAgentRR = 0;
const mcTickOrder = [];   // buffer reutilizado: nada de reservar un array por frame

function mcAgentsTick(now){
  const speedMult = mcAgentSpeed > 0 ? mcAgentSpeed : 1;
  // Tope de pasos por frame ∝ velocidad (a x1 son los 4 de siempre), pero quien manda de verdad es el
  // presupuesto de tiempo de abajo: es lo que permite que game.agentSpeed no tenga techo sin colgar el navegador.
  const tope = Math.max(MC_AGENT_MAX_STEPS, Math.ceil(MC_AGENT_MAX_STEPS*speedMult));
  const t0 = performance.now();

  mcTickOrder.length=0;
  for(const a of mc.agents.values()) if(a.state==='running') mcTickOrder.push(a);
  const vivos = mcTickOrder.length;
  if(!vivos){ mcAgentFlushDirty(); return; }
  if(mcAgentRR >= vivos) mcAgentRR = 0;
  const rodaja = MC_AGENT_FRAME_MS / vivos;   // lo que como mucho puede consumir uno sin dejar secos a los otros

  let agotado = false;
  for(let k=0; k<vivos; k++){
    const a = mcTickOrder[(mcAgentRR + k) % vivos];
    if(!a._nextAt) a._nextAt=now;
    if(!agotado){
      // Sin suelo de 16 ms: antes el paso no podía bajar de un frame, así que a partir de agentSpeed≈7 (tickMs 110)
      // subirlo más no aceleraba NADA. Ahora el paso puede ser submilisegundo y se dan varios por frame.
      const paso = Math.max(0.05, a.tickMs / speedMult);
      const finRodaja = performance.now() + rodaja;
      let n=0;
      while(a.state==='running' && now>=a._nextAt && n<tope){
        n++; a._nextAt+=paso; mcAgentStep(a);
        const ahora = performance.now();
        if(ahora-t0 > MC_AGENT_FRAME_MS){ agotado=true; mcAgentRR=(mcAgentRR+k+1)%vivos; break; }  // el siguiente frame empieza por el de después
        if(ahora > finRodaja) break;                                                                // su rodaja, no la de todos
      }
    }
    // Sin catch-up ni para los que no llegaron a tocar CPU: si no, acumulan deuda y en cuanto les toca
    // turno se gastan el frame entero poniéndose al día, que es como empezó todo esto.
    if(a._nextAt<now) a._nextAt=now;
  }
  if(!agotado) mcAgentRR = 0;   // cupo entero: la próxima vuelta puede empezar por el principio
  mcAgentFlushDirty();
  mcAgentMaybeSave(now);
}

function mcAgentsSmoothUpdate(dt){
  if(dt <= 0 || !mc.agents || !mc.agents.size) return;
  for(const a of mc.agents.values()){
    if(a.state === 'stopped') continue;
    if(a.renderX === undefined){ a.renderX = a.x; a.renderY = a.y; a.renderZ = a.z; continue; }
    const dx = a.x - a.renderX, dz = a.z - a.renderZ;
    const distHoriz = Math.hypot(dx, dz);
    const oldRx = a.renderX, oldRy = a.renderY, oldRz = a.renderZ;
    const mounted = a.passengers && a.isMounted();
    if(distHoriz > 1e-4){
      const speedMult = mcAgentSpeed > 0 ? mcAgentSpeed : 1;
      // Mismo suelo que el planificador (0.05 ms, no 16): si aquí se quedaba en 16 ms, a velocidad alta el
      // cuerpo interpolado no alcanzaba nunca a la posición lógica y el agente se veía «arrastrándose» detrás.
      const effectiveTickMs = Math.max(0.05, a.tickMs / speedMult);
      const speed = 1000 / effectiveTickMs;
      const maxMove = Math.min(distHoriz, dt * speed);
      a.renderX += (dx / distHoriz) * maxMove;
      a.renderZ += (dz / distHoriz) * maxMove;
    } else {
      a.renderX = a.x;
      a.renderZ = a.z;
    }
    const xMin = Math.floor(a.renderX + 0.05), xMax = Math.floor(a.renderX + 0.95);
    const zMin = Math.floor(a.renderZ + 0.05), zMax = Math.floor(a.renderZ + 0.95);
    const baseTargetY = Math.round(a.y);
    let maxY = Math.min(a.y, mcSurfaceNear(Math.round(a.renderX), Math.round(a.renderZ), baseTargetY, 1));
    if(maxY < 0) maxY = a.y;
    for(let ix = xMin; ix <= xMax; ix++){
      for(let iz = zMin; iz <= zMax; iz++){
        const sy = mcSurfaceNear(ix, iz, baseTargetY, 1);
        if(sy > maxY) maxY = sy;
      }
    }
    a.renderY = maxY;
    if(a._pendingPaint){
      const p = a._pendingPaint;
      const distToTarget = Math.hypot(a.renderX - p.targetX, a.renderZ - p.targetZ);
      if(distToTarget < 0.25){
        const prev = mc.grid[mcIdx(p.targetX, p.targetY, p.targetZ)];
        if(prev && prev !== p.matId){
          mcAgentSetBlock(p.targetX, p.targetY, p.targetZ, p.matId);
          a.stats.painted++;
        } else if(prev === p.matId){
          a.stats.repainted++;
        }
        a._pendingPaint = null;
      }
    }
    mcAgentMesh(a);
    // Si el cuerpo se ha movido, su sombra tiene que rehacerse. Va aquí y no en mcAgentMesh porque esa función
    // se puede envolver desde fuera (los cuerpos a escala de la librería de agentes construyen su propia malla y
    // nunca llegaban al mcShadowDirty de app.js): la nube se deslizaba con la sombra clavada donde estuvo, y solo
    // saltaba al colocar un bloque, que es lo que sí marcaba el mapa. La regla es del motor, no de los agentes:
    // si la geometría se mueve entre frames, el mapa de sombra caduca.
    if(a.renderX!==oldRx || a.renderY!==oldRy || a.renderZ!==oldRz) mcShadowMoved();   // andar no es urgente (ver mcShadowMoved)
    if(mounted){
      const dxP = a.renderX - oldRx;
      const dyP = a.renderY - oldRy;
      const dzP = a.renderZ - oldRz;
      const targetPx = mc.pos[0] + dxP;
      const targetPy = mc.pos[1] + dyP;
      const targetPz = mc.pos[2] + dzP;

      if(mcCollidesWorld(targetPx, targetPy, targetPz)){
        a._dismountedAt = performance.now();
        const pushDx = oldRx - a.renderX;
        const pushDz = oldRz - a.renderZ;
        const pushLen = Math.hypot(pushDx, pushDz) || 1;
        const dirX = pushDx / pushLen;
        const dirZ = pushDz / pushLen;

        // Posicionar al jugador fuera del perímetro del túnel (atrás, sobre suelo libre) sin saltos bruscos en Y
        mc.pos[0] = oldRx + 0.5 + dirX * 0.6;
        mc.pos[2] = oldRz + 0.5 + dirZ * 0.6;

        // Inercia de caída parabólica suave a 60 FPS impulsada por la gravedad del juego
        mc.vel[0] = dirX * 2.5;
        mc.vel[2] = dirZ * 2.5;
        mc.vel[1] = -1.8;

        if(!a._warnedKnockoff){
          toast('💥 ¡Te has chocado con un bloque y has caído al suelo!');
          a._warnedKnockoff = true;
          setTimeout(() => { a._warnedKnockoff = false; }, 2500);
        }
      } else {
        mc.pos[0] = targetPx;
        mc.pos[1] = targetPy;
        mc.pos[2] = targetPz;
      }
    }
  }
}

function mcStopAgents(motivo){
  for(const a of mc.agents.values()) a.stop(motivo||'stop');
  return mc.agents.size;
}

function mcPauseAgents(){
  let n=0;
  for(const a of mc.agents.values()) if(a.state==='running'){ a.pause(); n++; }
  return n;
}

function mcResumeAgents(){
  let n=0;
  for(const a of mc.agents.values()) if(a.state==='paused'){ a.resume(); n++; }
  return n;
}

// game.defineAgent(cfg) · registra (o REEMPLAZA) un agente. Mismo contrato que game.onKey: valida, avisa por
// consola y devuelve null si algo falta. Devuelve el handle VIVO → game.agent(id).vars/.stats en F12.
game.defineAgent=function(cfg){
  if(!cfg || typeof cfg!=='object'){ console.warn('game.defineAgent: pasa un objeto, p.ej. game.defineAgent({id:"pintor", onTick(a){…}})'); return null; }
  const id=String(cfg.id==null?'':cfg.id).trim();
  if(!id){ console.warn('game.defineAgent: falta `id` (cadena no vacía)'); return null; }
  if(typeof cfg.onTick!=='function'){ console.warn('game.defineAgent("'+id+'"): falta `onTick(a)`, que es la heurística del agente'); return null; }
  if(!mc.grid){ console.warn('game.defineAgent("'+id+'"): abre el Mundo (🌍) antes de invocar agentes'); return null; }
  const viejo=mc.agents.get(id);
  if(viejo){ viejo.stop('redefinido'); mcAgentFreeMesh(viejo); mc.agents.delete(id); }   // redefinir = reemplazar
  const a=mcAgentMake(id, cfg);
  mc.agents.set(id, a);
  if(cfg.autostart!==false) a.start();
  return a;
};

// game.agents() · tabla de agentes vivos · game.agents.killAll() · game.agents.kill(id) · game.agents.stopAll()
function getAgentsTable(){
  const filas=[...mc.agents.values()].map(a=>({ id:a.id, estado:a.state, pos:a.x+','+a.y+','+a.z,
    ticks:a.stats.ticks, pasos:a.stats.steps, pintados:a.stats.painted, notas:a.stats.notes, meta:a.goal }));
  if(!filas.length) console.log('sin agentes (game.defineAgent)'); else console.table(filas);
  return filas;
}
game.agents=getAgentsTable;
game.agents.killAll=function(){
  const count=mc.agents.size;
  if(!count){ console.log('Sin agentes activos para eliminar.'); return 0; }
  for(const a of [...mc.agents.values()]){ a.stop('killAll'); mcAgentFreeMesh(a); mc.agents.delete(a.id); }
  toast('💀 '+count+' agente(s) eliminado(s)');
  console.log('💀 '+count+' agente(s) eliminado(s) desde game.agents.killAll()');
  return count;
};
game.agents.kill=function(id){
  if(id===undefined || id===null || id==='all' || id==='*') return game.agents.killAll();
  const a=mc.agents.get(String(id));
  if(!a){ console.warn('game.agents.kill: no existe el agente "'+id+'"'); return false; }
  a.stop('killed_from_console'); mcAgentFreeMesh(a); mc.agents.delete(a.id);
  toast('💀 Agente "'+a.name+'" eliminado');
  console.log('💀 Agente "'+a.id+'" ('+a.name+') eliminado desde game.agents.kill("'+id+'")');
  return true;
};
game.agents.stopAll=function(){ const n=mcStopAgents('game.agents.stopAll'); toast(n+' agente(s) detenido(s)'); return n; };
game.agents.get=function(id){ return mc.agents.get(String(id)) || null; };

game.showToastsEnabled = false;
game.agents.showToasts = function(enable){
  if(enable === undefined) return game.showToastsEnabled;
  game.showToastsEnabled = Boolean(enable);
  const status = game.showToastsEnabled ? 'ACTIVADAS' : 'DESACTIVADAS (silenciosas por defecto)';
  console.log('🔔 Notificaciones toast de agentes: ' + status);
  return game.showToastsEnabled;
};
game.showToasts = game.agents.showToasts;

game.agent=function(id){ return mc.agents.get(String(id)) || null; };
game.stopAgents=game.agents.stopAll;
game.removeAgent=game.agents.kill;
game.kill=game.agents.kill;
game.killAll=game.agents.killAll;
window.kill=game.agents.kill;
window.killAll=game.agents.killAll;
window.stopAgents=game.agents.stopAll;
// game.pruneAgentNotes(id) · borra SOLO las notas escritas por ese agente (prefijo «[id] »). Nunca toca las
// notas del usuario ni las de otros agentes.
game.pruneAgentNotes=function(id){
  const pre='['+String(id)+'] '; let n=0;
  for(const k of Object.keys(mc.notes)) if(String(mc.notes[k]).startsWith(pre)){ delete mc.notes[k]; n++; }
  if(n){ mcDirtyHeader(); mcScheduleSave(); mcUpdateNoteView(); }
  console.log(n+' nota(s) de "'+id+'" borradas'); return n;
};
// game.agentSpeed = multiplicador global de VELOCIDAD: divide el tickMs de cada agente, así que 2 = el doble de
// rápido y 0.5 = la mitad (el comentario de antes decía justo lo contrario y era falso). Persiste.
// SIN TOPE por arriba: el freno no es un número, es MC_AGENT_FRAME_MS (el tiempo de CPU que los agentes pueden
// gastar por frame). Pedir más velocidad de la que cabe no acelera más, pero tampoco cuelga el Mundo.
try{ const s=parseFloat(localStorage.getItem('vf_agentSpeed')); if(isFinite(s)) mcAgentSpeed=Math.max(0.1,s); }catch(e){}
Object.defineProperty(game,'agentSpeed',{ enumerable:true, get:()=>mcAgentSpeed,
  set:v=>{ v=Math.max(0.1, isFinite(+v)?+v:1); mcAgentSpeed=v; try{localStorage.setItem('vf_agentSpeed',v);}catch(e){}
    for(const a of mc.agents.values()) a._nextAt=0; } });
// game.agentSaveMs = cada cuánto (ms) se vuelca el mundo mientras los agentes escriben (mcSaveWorld POSTea el
// mundo ENTERO, así que bajarlo mucho satura la red). Persiste.
try{ const s=parseFloat(localStorage.getItem('vf_agentSaveMs')); if(isFinite(s)) mcAgentSaveMs=Math.max(2000,s); }catch(e){}
Object.defineProperty(game,'agentSaveMs',{ enumerable:true, get:()=>mcAgentSaveMs,
  set:v=>{ v=Math.max(2000, isFinite(+v)?+v:MC_AGENT_SAVE_MS); mcAgentSaveMs=v; try{localStorage.setItem('vf_agentSaveMs',v);}catch(e){} } });
// clic izq = romper · clic der = poner/pintar (solo con pointer-lock activo; el 1er clic solo bloquea el puntero).
// Mantener el botón repite la acción (mcTick, cada MC_ACT_MS) → construir/romper en fila arrastrando la mira.
$('#mc-canvas').addEventListener('mousedown',e=>{
  if(!mc.active || document.pointerLockElement!==mc.canvas) return;
  if(e.button!==0 && e.button!==2) return;
  mc.heldBtn=e.button; mc.actAt=performance.now();
  mcDoAction(e.button);
});
window.addEventListener('mouseup',e=>{ if(!mc.active) return;
  if(mc.tool==='box' && mc.heldBtn===0 && mc.boxStep===1 && document.pointerLockElement===mc.canvas) mcBoxMouseUp();
  mc.heldBtn=-1; });
$('#mc-canvas').addEventListener('contextmenu',e=>{ if(mc.active) e.preventDefault(); });

buildPalette();
// En /map/<nombre> el Mundo se abre ENCIMA del editor y lo tapa entero, pero hasta ahora el editor
// arrancaba primero igual: sus galerías (Assets, Habitaciones, Habitantes, texturas) bajan un documento
// por miniatura —decenas, megas— y todas van por el MISMO host, del que el navegador solo abre ~6
// sockets. Resultado medido en el portátil del dueño: la paleta del Mundo se pasaba la apertura
// HACIENDO COLA detrás de miniaturas que nadie estaba viendo, y el primer bloque se comía ~10 s.
// Aquí se separa lo que el Mundo sí necesita (los nombres cortos del índice, que usan los snippets) de
// lo que solo mira el editor, y esto último se arranca cuando el Mundo ya está en pie.
const _enMundo=/^\/map\//.test(location.pathname);
// REQ-OSD3 · se marca ANTES de abrir el mundo: mcScheduleSave y la hotbar se consultan durante la
// carga, así que enterarse después dejaría una ventana en la que la pantalla del menú sí guarda.
mc.escaparate = _enMundo && mcEsEscaparate();
// REQ-INTRO1 · con ?intro=1, el snippet de la intro se pide YA, en paralelo con la carga del mundo: para
// cuando openWorld lo necesite tiene que estar en la mano, no a un viaje de red de distancia.
if(_enMundo) mcIntroPrefetch();
// REQ-EDIT1 · En /map/ la tapa NO se quita aquí: entre el final de este script y `openWorld()` hay un
// viaje de red (`assetIndex()`), y en ese hueco la página pintaba el editor 2D/3D — el mismo flashazo,
// por el otro lado. La quita `openWorld` en cuanto enseña el modal del Mundo, que es su primera línea.
// Red de seguridad para los dos caminos: si algo se cuelga, la página no se queda en negro.
setTimeout(mcDestapaApp, 5000);
let _assetsEditorP=null;
if(!_enMundo){ _assetsEditorP = loadServerAssets().catch(()=>{}); refreshHabitantesList(); }
if(!restore()){ setSize(16,16,16); state.voxels=presetBarril(); }
$('#meta-name').value=state.meta.name;
$('#meta-type').value=state.meta.type;
syncMetaCategoria();                   // categoría + el sub-selector de herramienta (REQ-TOOL1)
$('#meta-role').textContent=state.meta.role||'';
$('#meta-role').hidden=!state.meta.role;
$('#meta-atravesable').checked=state.atravesable;
setTool(state.tool);
isoCv.style.cursor='ns-resize';
syncLayer(); syncColor(); updateZoomLabel(); updateUndoUI(); updateInfo();
// Aquí NO se llama a render() ni a resizeEdit(): setMode('3d') (la línea de abajo) ya hace
// resizeEdit3d + drawEdit3d + drawIso, y resizeEdit dibuja un lienzo 2D que se oculta acto seguido.
// Dejarlos duplicaba el arranque: render() encola un rAF que repite drawIso y drawEdit3d DESPUÉS de
// que setMode ya los hubiera pintado, así que el dibujo entero se rasterizaba dos veces. Con un modelo
// grande eso es el congelado de varios segundos que aparecía ~1 s después de refrescar (el primer
// segundo la página va fina porque el rAF todavía no ha entrado). Si se vuelve a Capas, setMode llama
// a resizeEdit() por su rama, así que el lienzo 2D se dimensiona y se pinta cuando de verdad se ve.
setMode('3d');   // arrancar en Edición 3D (no en Capas)
// URL /map/<nombre>: entrar directo a ese mundo (persistente y propio). Sin /map/ arranca en el editor como siempre.
// El índice se espera A PROPÓSITO: el autoarranque del Mundo resuelve materiales por nombre corto
// («hierba»), y esos nombres los da de alta mcIndexAssets. Antes esto era una carrera —loadServerAssets()
// era async y openWorld() salía sin esperarla—, así que el snippet podía encontrarse el registro a medias.
// Son unos KB de index.json; las galerías, que son lo caro, van después de que el Mundo esté cargado.
if(_enMundo) assetIndex().then(mcIndexAssets).catch(()=>{})
  .then(openWorld)   // REQ-INTRO1 · la intro la lanza openWorld por dentro, en cuanto el mundo está pintado
  .then(()=>{ loadServerAssets(); refreshHabitantesList(); });
// …y sin /map/, el gemelo: el snippet 'editor-autoarranque' (mcEditorAutoarranque). Va enganchado al
// final del arranque a propósito: cuando corre, el editor ya está montado y en Edición 3D y las galerías
// están cargadas, así que el snippet puede tocar el modelo, abrir el Mundo o irse a un mapa con game.map.
// Si no existe ese snippet no pasa nada; si falla, tampoco. `?noauto=1` lo salta.
else {
  // REQ-EDIT1 · El snippet se PIDE ya, en paralelo con las galerías, y no porque corra antes (sigue
  // corriendo al final): es para poder destapar la página cuanto antes cuando resulta que no hay ninguno.
  const _autoP = mcEditorSaltaAuto() ? Promise.resolve(null)
                                     : mcPideSnippet(MC_EDITOR_AUTOARRANQUE).catch(()=>null);
  _autoP.then(s => { if(!s || !s.code) mcDestapaApp(); });   // nada que esperar: el editor, ya
  // `beforeunload` llega SÍNCRONO al asignar `location.href` (medido en Chromium), así que cuando el
  // snippet vuelve ya se sabe si se ha ido. Si se fue, no se destapa: destaparlo es exactamente el flash.
  addEventListener('beforeunload', ()=>{ mc._navegando = true; });
  addEventListener('pagehide',     ()=>{ mc._navegando = true; });
  setTimeout(mcDestapaApp, 5000);   // red de seguridad: un snippet colgado no deja la página en negro
  _assetsEditorP.then(()=>mcEditorAutoarranque(_autoP))
    .catch(e=>console.warn(MC_EDITOR_AUTOARRANQUE+': '+(e && e.message ? e.message : e)))
    .then(()=>{ if(!mc._navegando) mcDestapaApp(); });   // se quedó: el editor, ahora sí, entero
}
